window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s7-600","number":600,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"ما أثر قراءة ﴿حقيقٌ عليَّ﴾ في معنى الآية؟","answer":"على قراءة ﴿حقيق عليَّ﴾ يكون المعنى: واجب عليّ ولازم لي ألا أقول على الله إلا الحق، فتصرح القراءة بالتزام موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص164–165، تحت «دلالة توجيه قراءة ﴿على﴾»","url":""}]},{"id":"s7-601","number":601,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"ما الذي يضيفه وصف موسى نفسه بـ﴿حقيق﴾ إلى إعلانه الرسالة؟","answer":"يفيد أنه جدير بالقول الحق وثابت عليه، وأن الصدق لازم لما يبلغه عن الله. ويربط المصدر الوصف بحقيقة الرسالة وثبوتها؛ فليس إعلانه دعوى منفصلة عن الأمانة في التبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص165–166، تحت «سر إيثار لفظ ﴿حقيق﴾ على غيره»","url":""}]},{"id":"s7-602","number":602,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا جاء القصر بـ﴿إلا الحق﴾؟","answer":"القصر يحصر كل ما يقوله موسى منسوبًا إلى الله في الحق وحده، فينفي عنه أدنى افتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص166، تحت «دلالة التعبير بلفظ ﴿الحق﴾»","url":""}]},{"id":"s7-603","number":603,"surah":7,"verses":[105,118],"references":[{"surah":7,"verses":[105,118]},{"surah":13,"verses":[1]}],"verseLabel":"الأعراف: 105؛ الأعراف: 118؛ الرعد: 1","question":"ما دلالة تعريف ﴿الحق﴾ في قول موسى: ﴿حقيق على أن لا أقول على الله إلا الحق﴾؟","answer":"يفيد الحق الكامل الثابت الذي لا يشوبه باطل، ويحتمل العهد إلى الحق الذي أوحاه الله إلى موسى؛ فليس كلامه رأيًا يحتمل الصدق والكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص166، تحت «سر التعبير بالمصدر المعرّف بـ﴿أل﴾»","url":""}]},{"id":"s7-1610","number":1610,"surah":7,"verses":[105,118],"references":[{"surah":7,"verses":[105,118]},{"surah":13,"verses":[1]}],"verseLabel":"الأعراف: 105؛ الأعراف: 118؛ الرعد: 1","question":"ما دلالة التعبير عن ﴿الحق﴾ مصدرًا معرفًا في قوله: ﴿فوقع الحق﴾؟","answer":"يصوّر ثبوت الحق الكامل وظهوره ظهورًا حاسمًا في مقابل بطلان السحر؛ فالمصدر المعرّف يعظم حقيقته ويؤكد تمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص240، تحت «سر التعبير عن ﴿الحق﴾ مصدرًا معرفًا»","url":""}]},{"id":"s7-1611","number":1611,"surah":7,"verses":[105,118],"references":[{"surah":7,"verses":[105,118]},{"surah":13,"verses":[1]}],"verseLabel":"الأعراف: 105؛ الأعراف: 118؛ الرعد: 1","question":"ما دلالة تخصيص ﴿الحق﴾ بالذكر في قوله: ﴿والذي أنزل إليك من ربك الحق﴾؟","answer":"ينبه إلى أن القرآن هو الحق الكامل الذي سلم من الباطل، ويرد على من زعم أنه أساطير أو سحر؛ فخُص الحق بالذكر لأنه جوهر النزاع مع المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص594، تحت «توجيه تخصيص ذكر الحق بالذكر»","url":""}]},{"id":"s7-604","number":604,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لم أكد موسى مجيئه بالبينة بقوله ﴿قد جئتكم ببينة﴾؟","answer":"تحقق ﴿قد﴾ وقوع مجيئه بالحجة وتثبته في مقام قد يستغرب فيه المخاطبون دعوى الرسالة. وتأتي الجملة استئنافًا يجيب عن طلب الدليل الذي يثيره قوله إنه رسول لا يقول على الله إلا الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص166–167، تحت «بلاغة الاستئناف في قوله تعالى: ﴿قد جئتكم﴾»","url":""}]},{"id":"s7-605","number":605,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"ما دلالة تنكير ﴿ببينة﴾ في قول موسى؟","answer":"في التنكير تفخيم للحجة وتعظيم لشأنها؛ فهي بينة عظيمة تثبت رسالته. ويذكر المصدر أن البينة تحتمل البرهان العقلي وتحتمل المعجزة، ثم يأتي طلب فرعون لما يراه من آية حسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص167، تحت «سر تنوع معاني البينة وتنكيرها في سياق الآية الحكيم»","url":""}]},{"id":"s7-606","number":606,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا كرر وصف الله بـ﴿ربكم﴾ بعد قوله ﴿رب العالمين﴾؟","answer":"انتقل من رب العالمين إلى ﴿ربكم﴾ لإلزام المخاطبين خاصة: الرب العام هو ربهم الذي تجب طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص168، تحت «دلالة حرف الجر ﴿من﴾ وإضافة الرب»","url":""}]},{"id":"s7-607","number":607,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا انتقل من المفرد في خطاب فرعون إلى الجمع: ﴿جئتكم... ربكم﴾؟","answer":"بدأ بمواجهة فرعون، ثم عم الخطاب فرعون وملأه الحاضرين لأن الحجة والمطالبة متوجهتان إليهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص167–168، تحت «سر التعبير بقوله تعالى: ﴿ببينة من ربكم﴾»","url":""}]},{"id":"s7-608","number":608,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لم فرع موسى طلبه ﴿فأرسل معي بني إسرائيل﴾ على إعلانه الرسالة والبينة؟","answer":"فالفاء تصل الطلب بما أقامه من حجة، ويصور الإرسال إطلاق من كان مقيدًا بالاستعباد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص168–169، تحت «علة التعبير بحرف الفاء في الإرسال في قوله تعالى: ﴿فأرسل﴾»","url":""}]},{"id":"s7-609","number":609,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿معي﴾ لا «إليّ» أو «معنا»؟","answer":"﴿معي﴾ تفيد المصاحبة في الخروج تحت قيادته، لا مجرد إرسالهم إليه؛ وأفرد لأن موسى المتصدر للخطاب والطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص169، تحت «سر تقييد الإرسال بـ﴿معي﴾ وأثرها في المعنى»","url":""}]},{"id":"s7-610","number":610,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"لماذا أجاب فرعون بشرط: ﴿إن كنت جئت بآية﴾ مع أن موسى قال: ﴿قد جئتكم ببينة﴾؟","answer":"تجاهل فرعون وصف البينة وردّه إلى شرط مشكوك فيه ﴿إن كنت﴾ مكابرةً، كأنه لم يثبت عنده شيء بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص172–173، تحت «دلالة التعبير بـ﴿إن﴾ دون ﴿إذا﴾»","url":""}]},{"id":"s7-611","number":611,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿بآية﴾ لا ﴿ببينة﴾ كما قال موسى؟","answer":"البينة حجة واضحة قد تكون عقلية أو حسية، أما طلب فرعون للآية في هذا المقام فمتجه إلى معجزة محسوسة يراها. فاختلاف اللفظين يكشف انتقاله من سماع البرهان إلى طلب أمر خارق مشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص167–168، تحت «سر التعبير بقوله تعالى: ﴿ببينة من ربكم﴾»","url":""}]},{"id":"s7-612","number":612,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"لماذا أمره بقوله: ﴿فأت بها﴾؟","answer":"الفاء جواب للشرط؛ أي إن كان معك دليل كما تزعم فأحضره وأظهره، وفي الأمر تحدٍّ واستخفاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص173–174، تحت «التعبير عن الإتيان بالمجاز المرسل»","url":""}]},{"id":"s7-613","number":613,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"لماذا أعاد الشرط: ﴿إن كنت من الصادقين﴾؟","answer":"أعاد الشرط تشكيكًا في صدقه وتحديًا له، فجعل إظهار الآية محك الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص174، تحت «بلاغة التعبير بالأخص في سياق هذا النص»","url":""}]},{"id":"s7-614","number":614,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"كيف يرتبط قوله ﴿إن كنت من الصادقين﴾ بطلب إظهار الآية؟","answer":"يشكك فرعون في دعوى موسى الصدق والرسالة، ويجعل إظهار الآية دليلًا يطالب به على تلك الدعوى. فالصدق أعم من الإتيان بآية؛ لأنه يكون في الأقوال والأفعال، والآية هنا شاهد خاص على صدقه فيما ادعاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص174، تحت «بلاغة التعبير بالأخص في سياق هذا النص»","url":""}]},{"id":"s7-615","number":615,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا عطف إلقاء العصا بالفاء: ﴿فألقى عصاه﴾؟","answer":"الفاء تدل على سرعة امتثال موسى للتحدي من غير تردد؛ فما إن طلب الآية حتى ألقى العصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص177–178، تحت «سر التعبير بالإلقاء في قوله: ﴿فألقى عصاه﴾»","url":""}]},{"id":"s7-616","number":616,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا أضاف العصا إلى موسى: ﴿عصاه﴾؟","answer":"الإضافة تؤكد أنها عصاه المعهودة البسيطة التي يعرفها، فتظهر المفارقة المعجزة حين تنقلب ثعبانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص177–178، تحت «نكتة تخصيص العصا الحسية بالمعجزة الإلهية»","url":""}]},{"id":"s7-617","number":617,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا هي ثعبان﴾ بأداة المفاجأة؟","answer":"﴿إذا﴾ الفجائية تصور التحول المباغت من عصا جامدة إلى ثعبان حاضر، من غير زمن أو معالجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص178، تحت «دلالة التعبير بقوله: ﴿فإذا﴾»","url":""}]},{"id":"s7-618","number":618,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"كيف تؤكد جملة ﴿هي ثعبان﴾ حقيقة تحول العصا؟","answer":"﴿هي﴾ مبتدأ يعود إلى العصا، و﴿ثعبان﴾ خبره؛ فالجملة تثبت أن العصا نفسها صارت ثعبانًا حقيقيًا. ويؤكد المصدر هذا الوجه في مقابل التخييل، وهو ما يجعل المشهد دليلًا ظاهرًا على المعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص178–179، تحت «دلالة الجملة الاسمية بين الحقيقة والمجاز»","url":""}]},{"id":"s7-619","number":619,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا وصف الحية هنا بـ﴿ثعبان مبين﴾، وفي طه بـ﴿حية تسعى﴾، وفي موضع بـ﴿كأنها جان﴾؟","answer":"هي حية في حقيقتها، وثعبان في عظمها، وكأنها جان في سرعة حركتها؛ فكل وصف يبرز جهة تلائم مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص181–182، تحت «الثعبان والحية والجان»","url":""}]},{"id":"s7-620","number":620,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا اختير ﴿ثعبان﴾ في مواجهة فرعون والسحرة؟","answer":"الثعبان يبرز كبر الحية وضخامتها، وهو وصف يلائم إظهار قوة المعجزة وهيبتها في مواجهة فرعون.؛ وتتكامل معه أوصاف الحية والجان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص181–182، تحت «الثعبان والحية والجان»","url":""}]},{"id":"s7-621","number":621,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا وُصف الثعبان بـ﴿مبين﴾؟","answer":"﴿مبين﴾ أي ظاهر الثعبانية لا تخييل فيه ولا اشتباه، فالمعجزة حقيقة مشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص176، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-622","number":622,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿ونزع يده﴾ لا «وأخرج يده»؟","answer":"النزع إخراج فيه قوة وشدة، وقد أخرج موسى يده من جيبه فظهرت بيضاء على وجه خارق.؛ وفي اختيار النزع تصوير لقوة إظهار المعجزة وثقل حجتها على فرعون ومن حوله، بحسب ما يذكره المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص184–185، تحت «نكتة إيثار لفظ النزع في قوله تعالى: ﴿ونزع﴾»","url":""}]},{"id":"s7-623","number":623,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"لماذا عطف معجزة اليد بالواو لا بالفاء؟","answer":"الواو تجمع آية اليد إلى آية العصا باعتبارهما حجتين مستقلتين، لا تجعل الثانية نتيجة للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص183–184، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-624","number":624,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"لم قيل ﴿بيضاء للناظرين﴾، ولم يقتصر على وصف اليد بالبياض؟","answer":"يبين القيد أن بياضها ظاهر لمن يراها، لافت للنظر على وجه الإعجاز، لا بياض علة ومرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص184–185، تحت «بلاغة التتميم في التعبير عن بياض اليد بقوله تعالى: ﴿بيضاء﴾»","url":""}]},{"id":"s7-625","number":625,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"لماذا تكرر تركيب المفاجأة: ﴿فإذا هي﴾؟","answer":"تكرار ﴿فإذا هي﴾ يجدد المفاجأة في الآية الثانية ويثبت أن اليد نفسها صارت بيضاء للناظرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص178، تحت «دلالة التعبير بقوله: ﴿فإذا﴾»","url":""}]},{"id":"s7-626","number":626,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿بيضاء﴾ من غير ذكر «من غير سوء» هنا؟","answer":"قيد ﴿للناظرين﴾ هنا يبين أن البياض خارق لافت للنظر، وليس بياض علة؛ ولذلك لا يلزم إعادة ﴿من غير سوء﴾ في هذا الموضع. ويشرح المصدر هذا القيد بنظيره في طه الذي يصرح بنفي المرض والبرص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص184–185، تحت «بلاغة التتميم في التعبير عن بياض اليد بقوله تعالى: ﴿بيضاء﴾»","url":""}]},{"id":"s7-627","number":627,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"لماذا قيد بياض اليد بـ﴿للناظرين﴾؟","answer":"قيدها بالناظرين لأن بياضها آية ضوئية ظاهرة يدركها كل من يشاهدها، لا إحساسًا خاصًا بموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص184–185، تحت «فائدة التعدي باللام في سياق الكلام»","url":""}]},{"id":"s7-628","number":628,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لماذا تولّى الملأ الجواب فقال: ﴿قال الملأ﴾ ولم يُذكر قول فرعون؟","answer":"حكى قول الملأ لأنه كان رأي الحاشية المتداول أو لأن فرعون قال لهم وقالوا له، فاختصر السياق المشاورة الجماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص188، تحت «بلاغة الفصل في الآية الكريمة»","url":""}]},{"id":"s7-629","number":629,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿الملأ من قوم فرعون﴾، وفي الشعراء: ﴿قال للملإ حوله﴾؟","answer":"في الأعراف نُسب الحكم إلى ملأ فرعون، وفي الشعراء صُوّر فرعون مخاطبًا من حوله؛ والمشهدان يكشفان تواطؤ الرأس والحاشية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص190، تحت «متشابه اللفظ بين آية الأعراف109 وآية الشعراء34»","url":""}]},{"id":"s7-630","number":630,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لماذا خُصّ الملأ بذكر قولهم: ﴿إن هذا لساحر عليم﴾؟","answer":"لأنهم وجوه القوم الذين تولوا المشاورة ومواجهة دعوة موسى؛ فذكر موقفهم يبرز دور القيادة في ترويج تهمة السحر وصرف الناس عن دلالة الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص187–188، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-631","number":631,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لماذا أكدوا قولهم بـ﴿إن هذا لساحر﴾؟","answer":"أكدوا بـ﴿إن﴾ واللام لتثبيت التهمة وصرف الأنظار عن المعجزة الواضحة إلى دعوى السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص189–190، تحت «بلاغة جماع المؤكدات في سياق الآية الكريمة»","url":""}]},{"id":"s7-632","number":632,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لماذا أشاروا إلى موسى بـ﴿هذا﴾ بدل تسميته؟","answer":"اسم الإشارة للحاضر يعيّنه أمامهم، وقد يحمل نبرة تحقير وإبعاد عن وصف الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص189، تحت «علة التعبير باسم الإشارة فيما تحويه الآية من عبارة»","url":""}]},{"id":"s7-633","number":633,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"ماذا أضاف وصف ﴿عليم﴾ إلى تهمتهم لموسى بأنه ﴿ساحر﴾؟","answer":"نسبوا إليه الرسوخ والمهارة في السحر، ليزعموا أن ما شاهدوه من الآيات ناشئ عن معرفة فائقة بهذه الصناعة. والوصف يقوي التهمة في زعمهم ويهيئ طلب سحرة على قدر ما نسبوه إليه من العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص189–190، تحت «بلاغة جماع المؤكدات في سياق الآية الكريمة»","url":""}]},{"id":"s7-634","number":634,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لم نسب القول في الأعراف إلى ﴿الملأ من قوم فرعون﴾، وفي الشعراء إلى فرعون: ﴿قال للملإ حوله﴾؟","answer":"المشهد محاورة بين فرعون وملئه، وقد قالوا هذا الرأي وتداوله بعضهم مع بعض؛ فحكت الأعراف قول الملأ، وحكت الشعراء خطاب فرعون لهم. ويذكر المصدر أن نسبته إلى الملأ تلائم ذكرهم مع فرعون في افتتاح قصة الأعراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص188، تحت «بلاغة الفصل في الآية الكريمة»","url":""}]},{"id":"s7-635","number":635,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"لماذا نسب الملأ إلى موسى إرادة إخراجهم: ﴿يريد أن يخرجكم﴾ مع أنه طلب إخراج بني إسرائيل؟","answer":"حوّلوا طلب تحرير بني إسرائيل إلى مؤامرة على الأرض تحريضًا للناس؛ فقلبوا غاية الرسالة السياسية ليحموا سلطانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص193–194، تحت «نكتة نسبة الإخراج والأرض إليهم في السياق الحكيم»","url":""}]},{"id":"s7-636","number":636,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"لماذا جاء ﴿يريد﴾ بالمضارع؟","answer":"المضارع يصور الإرادة متجددة قائمة الآن، ويستحضر خطرًا مزعومًا يوشك الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص193، تحت «بلاغة التعبير بالمضارع والمصدر المؤول»","url":""}]},{"id":"s7-637","number":637,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"ما سرّ تعبيرهم بـ﴿يخرجكم من أرضكم﴾، وإضافة الأرض إليهم؟","answer":"أضافوا الأرض إلى المخاطبين لاستثارة عصبيتهم وخوفهم على الوطن والملك، مع أنهم هم المستبدون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص193–194، تحت «نكتة نسبة الإخراج والأرض إليهم في السياق الحكيم»","url":""}]},{"id":"s7-638","number":638,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"لماذا حُذف ذكر السحر من قوله: ﴿يريد أن يخرجكم﴾ مع أنه أساس تهمتهم؟","answer":"يجري عرض القصة في الأعراف على الاختصار، فطوي قيد ﴿بسحره﴾ مع وضوح تهمة السحر من كلامهم السابق. أما التصريح به في الشعراء فيأتي في كلام فرعون بما يصوره من خوفه وتشبثه بتلك التهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص194–195، تحت «العدول عن ذكر لفظ ﴿بسحره﴾ بحذفه من السياق»","url":""}]},{"id":"s7-639","number":639,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿فماذا تأمرون﴾، وفيه ظهور فرعون مستشيرًا للملأ أو مخاطبًا لهم؟","answer":"إما أن فرعون قال للملأ ﴿فماذا تأمرون﴾ طالبًا رأيهم، أو أن الملأ قالوا لفرعون فحكي الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص195–196، تحت «موقع الفعل المضارع ﴿تأمرون﴾ ودلالته في السياق»","url":""}]},{"id":"s7-640","number":640,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"لماذا اختير فعل ﴿تأمرون﴾ لا «تشيرون»؟","answer":"المراد طلب المشورة والرأي، وقد عبر عنه بالأمر تلطفًا بالمخاطبين وتطييبًا لنفوسهم. وعلى جعله كلام فرعون، يكشف استناده إلى رأي الملأ عن اضطرابه وحاجته إليهم أمام الحجة، بعد ما كان يدعيه من الاستعلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص196، تحت «سر التعبير بلفظ الأمر في السياق الكريم»","url":""}]},{"id":"s7-641","number":641,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿يريد أن يخرجكم من أرضكم﴾، وزاد في الشعراء: ﴿بسحره﴾؟","answer":"قصة الأعراف مبنية هنا على الاختصار، فحذف القيد مع سبق نسبة السحر إلى موسى. وفي الشعراء صرح فرعون بـ﴿بسحره﴾؛ ويذكر المصدر أن كلامه كان أشد إظهارًا للخوف من موسى، فأضاف الإخراج إلى السحر ترسيخًا لتهمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص194–195، تحت «العدول عن ذكر لفظ ﴿بسحره﴾ بحذفه من السياق»","url":""}]},{"id":"s7-642","number":642,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"ما سرّ تعبيرهم بـ﴿أرجه وأخاه﴾، وما دلالة ﴿أرجه﴾؟","answer":"﴿أرجه﴾ أي أخّره وأمهله ولا تعاجله بالعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص197، تحت «شرح المفردات: ﴿أرجه﴾»","url":""}]},{"id":"s7-643","number":643,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"لماذا جمعوا موسى وأخاه في التأخير مع أن المواجهة صدرت من موسى؟","answer":"أدخلوا هارون معه لأنه شريكه في الرسالة والعون، وإن كان موسى المتصدر لإظهار الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص200–201، تحت «علة إخفاء اسم هارون مع أنه مرسل مع أخيه ووزير له»","url":""}]},{"id":"s7-644","number":644,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"لماذا لم يصرح باسم هارون فقال: ﴿وأخاه﴾؟","answer":"استغني عن التصريح باسمه لظهور أنه كان مع موسى، وقد بينت مواضع أخرى ذلك وذكرت اسمه. وفي وصفه بالأخوة ما يكفي لتعيينه هنا، مع كون موسى متصدر هذه المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص200–201، تحت «علة إخفاء اسم هارون مع أنه مرسل مع أخيه ووزير له»","url":""}]},{"id":"s7-645","number":645,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وأرسل في المدائن حاشرين﴾، وفي الشعراء: ﴿وابعث في المدائن حاشرين﴾؟","answer":"الإرسال أخص من البعث؛ فالبعث يأتي للإرسال وغيره كالإحياء. ويذكر المصدر أن الأعراف، وهي الموضع الأسبق، اختارت اللفظ الأخص، ثم ورد الأعم في الشعراء تنويعًا للعبارة، مع اتحاد المطلوب وهو إحضار السحرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص201، تحت «إيثار لفظ الإرسال»","url":""}]},{"id":"s7-646","number":646,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿في المدائن﴾ لا «إلى المدائن»؟","answer":"﴿في المدائن﴾ تصور الحاشرين منتشرين داخلها يجوبونها ويبحثون، لا متجهين إلى حدودها فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص201، تحت «سر تعدية فعل الإرسال بـ﴿في﴾ دون ﴿إلى﴾»","url":""}]},{"id":"s7-647","number":647,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"لماذا جمع ﴿المدائن﴾؟","answer":"الجمع لأن السحرة موزعون في مدن متعددة، فأرادوا استقصاء مراكزهم كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص201–202، تحت «نكتة جمع المدينة على ﴿المدائن﴾»","url":""}]},{"id":"s7-648","number":648,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"لماذا وصف المرسلين بـ﴿حاشرين﴾ لا «جامعين»؟","answer":"الحشر جمع الناس من جهات مختلفة وسوقهم إلى مكان واحد، وهو أدق من مجرد الجمع في تصوير مهمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص203–204، تحت «الجمع والحشر»","url":""}]},{"id":"s7-649","number":649,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"لم جاء ﴿يأتوك﴾ جوابًا للأمر بإرسال الحاشرين؟","answer":"وصل الجزمُ بين إرسال الحاشرين ومجيئهم بالسحرة، فجعل الإتيان نتيجة متصلة بالأمر. ففيه بيان أن تنفيذ الاقتراح يفضي إلى جمع من يريدون الاستعانة بهم في مواجهة موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص204، تحت «إيثار الفعل المجزوم ﴿يأتوك﴾»","url":""}]},{"id":"s7-650","number":650,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿بكل ساحر﴾، وما الذي أفادته ﴿كل﴾؟","answer":"﴿كل﴾ تفيد الاستقصاء العرفي أو الكثرة؛ أي لا تتركوا ساحرًا متقنًا يمكن الاستعانة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص205، تحت «نكتة التعبير بلفظ ﴿كل﴾ الدال على العموم»","url":""}]},{"id":"s7-651","number":651,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"لماذا قرئ ﴿ساحر عليم﴾ و﴿سحّار عليم﴾؟","answer":"﴿ساحر﴾ اسم فاعل، و﴿سحّار﴾ صيغة مبالغة في كثرة السحر وإتقانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص205–206، تحت «سر المجيء بصيغة اسم الفاعل ﴿ساحر﴾ وصفته»","url":""}]},{"id":"s7-652","number":652,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"لماذا وصف كل ساحر بـ﴿عليم﴾؟","answer":"﴿عليم﴾ يدل على رسوخ معرفته بصناعة السحر ودقائقه، لا مجرد ممارسته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص205–206، تحت «سر المجيء بصيغة اسم الفاعل ﴿ساحر﴾ وصفته»","url":""}]},{"id":"s7-653","number":653,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"لماذا لم يقولوا: يأتوك بسحرة كثيرين؟","answer":"﴿كل ساحر عليم﴾ توجه الطلب إلى كل فرد من أهل الخبرة، فتفيد استقصاء هذا الصنف بحسب المقام، أو المبالغة في كثرة المطلوبين. فليست الغاية كثرة العدد وحدها، بل جمع من توفرت فيه المعرفة التي يريدونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص205، تحت «نكتة التعبير بلفظ ﴿كل﴾ الدال على العموم»","url":""}]},{"id":"s7-654","number":654,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"ما سرّ التعبير في الأعراف بـ﴿كل ساحر عليم﴾، وفي الشعراء بـ﴿كل سحار عليم﴾؟","answer":"على قراءة ﴿ساحر﴾ في الأعراف يوافق اللفظ ما سبقه من قولهم: ﴿إن هذا لساحر عليم﴾، وجاءت الشعراء بـ﴿سحار﴾ للمبالغة في طلب من يضاهي ما زعموه لموسى من مهارة، بما يلائم اشتداد خوف فرعون. وفي الأعراف قراءة ﴿سحار﴾ أيضًا، فلا يعمم الفرق على جميع القراءات.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص477، تحت «توجيه التشابه اللفظي»","url":""}]},{"id":"s7-655","number":655,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]},{"surah":10,"verses":[79]}],"verseLabel":"الأعراف: 112؛ يونس: 79","question":"ما سرّ اختلاف جهة الأمر: ﴿يأتوك بكل ساحر عليم﴾ على لسان الملأ في الأعراف، و﴿ائتوني بكل ساحر عليم﴾ على لسان فرعون في يونس؟","answer":"في الأعراف الحكاية عن مشورة الملأ لفرعون: أرسل حاشرين يأتوك بالسحرة؛ وفي يونس أصدر فرعون الأمر بنفسه فقال: ﴿ائتوني﴾، فناسب كل فعل جهة الخطاب ومن صدر عنه الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص33، تحت «توجيه التشابه اللفظي»","url":""}]},{"id":"s7-656","number":656,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"لم صرح باسم فرعون في ﴿وجاء السحرة فرعون﴾؟","answer":"التصريح باسمه يبين أنه المقصود بمجيئهم، وفيه اهتمام بصورة اجتماع السحرة عليه وتناصرهم معه. ويبرز بذلك طرف المواجهة الذي حشدهم في وجه رسالة موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص210، تحت «سر إظهار المفعول به ﴿فرعون﴾ في الجملة»","url":""}]},{"id":"s7-657","number":657,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ما سرّ تقديم مجيء السحرة قبل حوارهم؟","answer":"قدم مجيئهم لإقامة المشهد وبيان تنفيذ خطة الحشر، ثم نقل الحوار الذي كشف غايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص210، تحت «دلالة التعبير عن المجيء بالماضي في ﴿وجاء السحرة﴾»","url":""}]},{"id":"s7-658","number":658,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"لماذا بدأ السحرة بالسؤال عن الأجر قبل المبارزة؟","answer":"كشف سؤالهم أن باعثهم الأجر والمنزلة لا طلب الحق؛ فجعلوا المقابل شرطًا لبذل مهارتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص212–213، تحت «بيان التعريض بالتخضع في كلام السحرة»","url":""}]},{"id":"s7-659","number":659,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ماذا تضيف قراءة الاستفهام في طلب السحرة للأجر؟","answer":"تجعل القراءة الطلب استثباتًا للجزاء وإلزامًا لفرعون بإقراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص211–212، تحت «الاستفهام التقريري وتوجيه تعدد القراءات»","url":""}]},{"id":"s7-1612","number":1612,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ما أثر حشد المؤكدات واسمية الجملة في قراءة الخبر؟","answer":"تؤكد استحقاق الأجر وتطلب تقريره وضمانه؛ فتجتمع ﴿إن﴾ واللام مع ثبات الجملة الاسمية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص211–212، تحت «بلاغة حشد المؤكدات واسمية الجملة»","url":""}]},{"id":"s7-660","number":660,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"لماذا نكّروا ﴿أجرًا﴾؟","answer":"نكروه للتعظيم والتكثير؛ أي أجرًا عظيمًا مجزيًا يليق بما سيصنعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص212، تحت «نكتة تنكير الأجر في قوله تعالى: ﴿لأجرًا﴾»","url":""}]},{"id":"s7-661","number":661,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ما سرّ تعبيرهم بـ﴿إن كنا نحن الغالبين﴾ وإظهار ضمير ﴿نحن﴾؟","answer":"أظهروا ﴿نحن﴾ توكيدًا لاختصاصهم بالغلبة واستعلاءً بثقتهم في صناعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص212–213، تحت «فائدة جمع لفظ ﴿الغالبين﴾ ودلالته»","url":""}]},{"id":"s7-662","number":662,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"لماذا جاء في الشعراء استفهام صريح: ﴿أئن لنا لأجرًا﴾، وهنا ﴿إن لنا لأجرًا﴾؟","answer":"فعلى الخبر يقررون استحقاق الأجر، وعلى الاستفهام يستثبتونه ويطلبون إقرار فرعون به؛ أما مقارنة الخبرية هنا بالاستفهام في الشعراء فتكشف اختلاف أسلوب الاستيثاق، ولا يصح اختزال جميع القراءات في حذف همزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص211، تحت «الاستفهام التقريري وتوجيه تعدد القراءات»","url":""}]},{"id":"s7-663","number":663,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وجاء السحرة فرعون قالوا﴾، وفي الشعراء: ﴿فلما جاء السحرة قالوا لفرعون﴾؟","answer":"الأعراف تجمل ما بين إرسال الحاشرين ومجيء السحرة، فتصل المشهد بالواو، وتذكر فرعون مع المجيء لتبين أنهم قصدوه هو. أما الشعراء فتفصل الحشر وجمع الناس، ثم تقول ﴿فلما جاء السحرة قالوا لفرعون﴾، فتربط حضورهم بما سبق وتعين المخاطب في القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص513–515، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-664","number":664,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"لماذا أجاب فرعون بكلمة واحدة: ﴿نعم﴾؟","answer":"﴿نعم﴾ تصديق لقولهم على الوجه الخبري، وجواب بالإيجاب على الوجه الاستفهامي؛ فهي تقرر حصول مطلوبهم. ثم زاد فرعون وعد التقريب تشجيعًا لهم، فلا يقتصر جوابه كله على الكلمة الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص215–216، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-665","number":665,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"لماذا لم يكتف بالأجر بل قال: ﴿وإنكم لمن المقربين﴾؟","answer":"زادهم وعد القرب من مجلسه وسلطانه فوق المال، ليبلغ تحريضهم غايته ويضمن ولاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص216–217، تحت «فائدة التعبير بالجملة الاسمية واسم الفاعل»","url":""}]},{"id":"s7-666","number":666,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"كيف قوي وعد فرعون في ﴿وإنكم لمن المقربين﴾؟","answer":"أكد الوعد بإن واللام، وجاء به في جملة اسمية تفيد ثبات المنزلة. وتدخلهم ﴿من المقربين﴾ في زمرة خاصته ذوي الحظوة، فيجتمع توكيد الخبر مع إغرائهم بالمكانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص216–217، تحت «علة تجديد التكريم في إجابة فرعون للسحرة المغرورين»","url":""}]},{"id":"s7-667","number":667,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"ما سرّ التعبير بـ﴿من المقربين﴾ بدل «مقربون»؟","answer":"تفيد ﴿من﴾ أنهم سيكونون أفرادًا داخل زمرة معروفة من أهل القرب والمنزلة، وهو أبلغ من مجرد إثبات وصف التقريب لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص512، تحت «معنى ﴿من﴾ ودلالتها في قوله تعالى: ﴿لمن المقربين﴾»","url":""}]},{"id":"s7-668","number":668,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"ما المقابلة بين طلبهم ﴿أجرًا﴾ ووعده لهم بالقرب؟","answer":"طلبوا منفعة المال، فوعدهم معها منفعة الجاه والقرب؛ فصعد بالجزاء ليشتد تنافسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص217، تحت «علة تجديد التكريم في إجابة فرعون للسحرة المغرورين»","url":""}]},{"id":"s7-669","number":669,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"ما سرّ زيادة ﴿إذًا﴾ في قول فرعون في الشعراء: ﴿نعم وإنكم إذًا لمن المقربين﴾، وحذفها في الأعراف؟","answer":"تصرح ﴿إذًا﴾ في الشعراء بالجواب والجزاء، فتربط التقريب بما سألوا عنه من أجر عند الغلبة. ويوجه المصدر زيادتها بمجيء كلام السحرة هناك في صورة سؤال، في حين وافق خلو الأعراف منها الأسلوب الخبري في القراءة التي تجري عليها المقارنة؛ وليس التعليل مجرد حذف كلمة مقدرة للاختصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص510–511، تحت «دلالة التعبير بـ﴿إذًا﴾»","url":""}]},{"id":"s7-670","number":670,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"لماذا خيّر السحرة موسى: ﴿إما أن تلقي وإما أن نكون نحن الملقين﴾؟","answer":"التخيير إظهار للثقة والأدب الظاهر قبل المنافسة، مع ما فيه من تحدٍ لمن يبدأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص221، تحت «سر التخيير بين المتقابلات»","url":""}]},{"id":"s7-671","number":671,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"ما سرّ التعبير أولًا بـ﴿أن تلقي﴾ بالفعل، وثانيًا بـ﴿أن نكون نحن الملقين﴾ بالكون والاسم؟","answer":"قالوا لموسى ﴿أن تلقي﴾ بالفعل المجرد، ووصفوا أنفسهم بالاسم ﴿الملقين﴾ مع ﴿نحن﴾ لتوكيد ثبات الإلقاء واختصاصهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص223، تحت «فائدة هيئة لفظ ﴿الملقين﴾»","url":""}]},{"id":"s7-672","number":672,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"لماذا كرروا ﴿إما﴾ في طرفي التخيير؟","answer":"تأتي ﴿إما﴾ لتفصيل وجهي التخيير، فيعرض كل طرف مستقلًا: إلقاء موسى أو إلقاؤهم. وتكرارها مع تركيب الطرفين يوضح التقسيم الذي يسألونه عنه، ويهيئ تعيين من يبدأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص220، تحت «دلالة التعبير بحرف التفصيل ﴿إما﴾»","url":""}]},{"id":"s7-673","number":673,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"لماذا أظهروا ضمير ﴿نحن﴾؟","answer":"ضمير ﴿نحن﴾ لتوكيد أنهم الفريق المقابل وتضخيم شأنهم واستعدادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص220–221، تحت «دلالة التعريف بأل للفظ ﴿الملقين﴾»","url":""}]},{"id":"s7-674","number":674,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"لم لم يذكروا ما سيلقونه في ﴿إما أن تلقي وإما أن نكون نحن الملقين﴾؟","answer":"حذف مفعول الإلقاء للعلم به من المقام؛ فالمواجهة بين عصا موسى وما معهم من أدوات السحر. وهذا إيجاز يركز الحوار على اختيار من يبدأ، ويترك تفصيل الملقى لمشهد الإلقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص223، تحت «بلاغة الإيجاز بحذف المفعولات»","url":""}]},{"id":"s7-675","number":675,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"ما سرّ اختلاف التعبير بين قول السحرة في الأعراف: ﴿وإما أن نكون نحن الملقين﴾، وفي طه: ﴿وإما أن نكون أول من ألقى﴾؟","answer":"يؤكد تركيب الأعراف رغبتهم في تولي الإلقاء بصيغة ﴿نكون نحن الملقين﴾، وتصرح طه بقيد السبق في ﴿أول من ألقى﴾؛ وكلاهما في عرض التخيير في البدء. ويذكر المصدر أن كلا التعبيرين يلائم فواصل سورته، مع أداء المعنى المتقارب بأسلوبين مختلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص224، تحت «بلاغة التشابه والاختلاف في الآي»","url":""}]},{"id":"s7-676","number":676,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"لماذا أجاب موسى باقتضاب: ﴿ألقوا﴾؟","answer":"اقتضب ثقةً بربه وعدم مبالاة بسحرهم؛ فأمرهم أن يظهروا أقصى ما عندهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص226–227، تحت «توجيه العموم في خطاب موسى»","url":""}]},{"id":"s7-677","number":677,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"لماذا سمح لهم موسى أن يبدؤوا بالإلقاء؟","answer":"قدم إلقاءهم ليبلغوا غاية جهدهم في السحر، ثم تأتي المعجزة فتبطل ما جمعوه. فظهور الحق بعد تشوق الناس وانتظارهم أشد وقعًا في نفوسهم وأوضح في إظهار عجز السحرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص226–227، تحت «توجيه العموم في خطاب موسى»","url":""}]},{"id":"s7-678","number":678,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"ما وجه الإيجاز في الانتقال من ﴿قال ألقوا﴾ إلى ﴿فلما ألقوا﴾؟","answer":"حذف ما دل عليه السياق، والتقدير: فألقوا، فلما ألقوا؛ كما حذف مفعول الإلقاء للعلم به، أي آلات سحرهم. فجمع التعبير إيجاز الحدث وإيجاز المفعول، وانتقل إلى بيان أثر السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص227، تحت «دلالة الإيجاز بالحذف، في قوله تعالى: ﴿فلما ألقوا﴾»","url":""}]},{"id":"s7-679","number":679,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿سحروا أعين الناس﴾، دون أن يقال: سحروا الناس؟","answer":"قصر أثر سحرهم على الأعين لأنه تخييل بصري، لا تغيير لحقيقة الحبال والعصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص227، تحت «بلاغة التعبير بالمجاز»","url":""}]},{"id":"s7-680","number":680,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"كيف أفاد ﴿أعين الناس﴾ شمول أثر السحر للحاضرين؟","answer":"﴿أعين﴾ جمع قلة أريد به الكثرة لإضافته إلى ﴿الناس﴾ المعرف بأل الجنسية المستغرقة عرفًا؛ أي عيون الناس المحتشدين في ذلك الجمع. فدل التركيب على عموم التأثير في أبصار الحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص227–228، تحت «نكتة ائتلاف الجمع، والتعريف بأل الجنسية في لفظ ﴿الناس﴾»","url":""}]},{"id":"s7-681","number":681,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿واسترهبوهم﴾ لا «وأرهبوهم»؟","answer":"الاسترهـاب طلب الرهبة واستجلابها والمبالغة في إحداثها، فهو أقوى من مجرد أرهبوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص228، تحت «بلاغة صيغة الاستفعال، في الفعل: ﴿واسترهبوهم﴾»","url":""}]},{"id":"s7-682","number":682,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"ما دلالة تنكير ﴿سحر﴾ في ﴿وجاءوا بسحر عظيم﴾؟","answer":"يفيد التنكير تهويل شأن ما جاءوا به من السحر، بما فيه من تنوع ودقة وقوة تأثير في نفوس الناظرين؛ فيهيئ لوصفه بالعظمة من جهة أثره المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص228، تحت «علة تنكير السحر، في قوله تعالى: ﴿وجاءوا بسحر عظيم﴾»","url":""}]},{"id":"s7-683","number":683,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"لماذا وصف السحر بـ﴿عظيم﴾ مع أنه باطل؟","answer":"وصف بالعظم من جهة قوته في التخييل وأثره في الناس وكثرة وسائله، لا من جهة الحق والقيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص228–229، تحت «دلالة وصف السحر بالعظمة»","url":""}]},{"id":"s7-684","number":684,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿وأوحينا إلى موسى﴾ في أثناء المواجهة؟","answer":"ذكر الوحي في قلب المواجهة يبين أن حركة موسى بتوجيه ربه، وأن المعجزة ليست صناعة بشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص232، تحت «سر إيثار فعل الوحي ﴿وأوحينا﴾»","url":""}]},{"id":"s7-685","number":685,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"لم أظهر اسم موسى في ﴿وأوحينا إلى موسى﴾؟","answer":"في إظهار اسمه تشريف له وإبراز لمكانته عند تلقي الوحي وظهور الآية على يده. ويقابل ذلك إغفال أسماء السحرة، فاختص موسى بالتنويه في مقام إبطال سحرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص232–233، تحت «نكتة إظهار اسم موسى»","url":""}]},{"id":"s7-686","number":686,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿أن ألق عصاك﴾، فعاد إلى العصا المضافة إليه؟","answer":"إضافة العصا تذكر بأنها أداته المعهودة نفسها، وأن التحول من الشيء المألوف هو موضع الإعجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص234، تحت «دلالة إضافة العصا، واستحضار الضمير، في ﴿عصاك﴾»","url":""}]},{"id":"s7-687","number":687,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"لماذا جاءت المفاجأة مرة أخرى: ﴿فإذا هي تلقف﴾؟","answer":"﴿إذا﴾ الفجائية تصور شروع العصا في ابتلاع إفكهم فور إلقائها، فتحول المشهد في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص234–235، تحت «دلالة حرف الفاء، والحذف في السياق»","url":""}]},{"id":"s7-688","number":688,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿تلقف﴾ بالمضارع لا «لقفت»؟","answer":"المضارع يستحضر سرعة الالتقاط وتتابعه أمام العيون، كأن القارئ يشاهدها تبتلع ما ألقوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص235–236، تحت «دلالة صيغة المضارع ﴿تلقف﴾»","url":""}]},{"id":"s7-689","number":689,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿تلقف ما يأفكون﴾، وفي طه: ﴿تلقف ما صنعوا﴾؟","answer":"﴿ما يأفكون﴾ يكشف حقيقة سحرهم الأخلاقية: كذب مصروف عن الحق، و﴿ما صنعوا﴾ يركز في طه على إحكام عملهم الذي أبطلته العصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص299، تحت «سر اختيار لفظ ﴿صنعوا﴾»","url":""}]},{"id":"s7-690","number":690,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"لماذا عبّر عن سحرهم بـ﴿ما يأفكون﴾؟","answer":"الإفك قلب الحقيقة وصرفها؛ فسحرهم أظهر الساكن متحركًا، ولذلك سمى عملهم إفكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص236، تحت «إيثار التعبير بالإفك، في فاصلة الآية»","url":""}]},{"id":"s7-691","number":691,"surah":7,"verses":[118],"references":[{"surah":7,"verses":[118]}],"verseLabel":"الأعراف: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿فوقع الحق﴾، وما معنى وقوع الحق؟","answer":"الوقوع هنا الثبوت والظهور والتحقق؛ فلما بطلت المخايل استقر الحق ظاهرًا لا يدفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص239–240، تحت «بلاغة التعبير، بالوقوع على طريق الاستعارة»","url":""}]},{"id":"s7-693","number":693,"surah":7,"verses":[118],"references":[{"surah":7,"verses":[118]}],"verseLabel":"الأعراف: 118","question":"لماذا قابل وقوع الحق بـ﴿وبطل ما كانوا يعملون﴾؟","answer":"قابل ثبوت الحق بزوال عملهم؛ فظهور أحد الضدين يقتضي بطلان الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص240، تحت «بلاغة الطباق بين الحق والباطل»","url":""}]},{"id":"s7-694","number":694,"surah":7,"verses":[118,139,147],"references":[{"surah":7,"verses":[118,139,147]}],"verseLabel":"الأعراف: 118؛ الأعراف: 139؛ الأعراف: 147","question":"ما دلالة ﴿ما كانوا يعملون﴾ في الأعراف118؟","answer":"تدل كان مع المضارع على أن السحر كان دأبًا راسخًا وصناعة متكررة، ثم أبطل الله ذلك العمل حين ظهر الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص241، تحت «بيان التعبير بكان والمضارع، في سياق الآية»","url":""}]},{"id":"s7-1613","number":1613,"surah":7,"verses":[118,139,147],"references":[{"surah":7,"verses":[118,139,147]}],"verseLabel":"الأعراف: 118؛ الأعراف: 139؛ الأعراف: 147","question":"ما دلالة الجمع بين الماضي والمضارع في ﴿ما كانوا يعملون﴾ بالأعراف139؟","answer":"يجمع التركيب معنى الاستمرار والتجدد مع استحضار صورة أعمالهم الباطلة؛ فكان ذلك شأنًا متكررًا لا حادثة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص421، تحت «سر الجمع بين الماضي والمضارع»","url":""}]},{"id":"s7-1614","number":1614,"surah":7,"verses":[118,139,147],"references":[{"surah":7,"verses":[118,139,147]}],"verseLabel":"الأعراف: 118؛ الأعراف: 139؛ الأعراف: 147","question":"ما دلالة لفظ ﴿يعملون﴾ في الأعراف147؟","answer":"يشمل العمل ما اعتقدوه وما ظهر من آثاره في أقوالهم وأفعالهم؛ فالجزاء متعلق بما قدموه من ذلك كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص541–542، تحت «نكتة التعبير بلفظ ﴿يعملون﴾»","url":""}]},{"id":"s7-695","number":695,"surah":7,"verses":[118],"references":[{"surah":7,"verses":[118]}],"verseLabel":"الأعراف: 118","question":"ما الفرق بين التعبير بـ﴿يعملون﴾ و﴿يفعلون﴾ و﴿يصنعون﴾؟","answer":"العمل فعل مقصود، ويستعمل في الصالح والسيئ؛ والفعل أعم منه، فقد يقع بقصد أو بغير قصد وينسب إلى الإنسان وغيره؛ والصنع أخص، لأنه فعل محكم مجاد. فاختيار ﴿يعملون﴾ يلائم سحرًا قصدوه وداوموا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص242–243، تحت «يعملون، يفعلون، يصنعون»","url":""}]},{"id":"s7-696","number":696,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"لماذا بُني ﴿فغُلبوا﴾ للمجهول؟","answer":"يركز البناء للمجهول على تحقق الغلبة عليهم، فلا حاجة إلى التصريح بالغالب بعد ظهور آية موسى. وفي ذلك إسناد النصر والتثبيت إلى الله الذي أيده بالمعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص246، تحت «نكتة التعبير بصيغة المبني للمجهول ﴿فغلبوا﴾»","url":""}]},{"id":"s7-697","number":697,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿هنالك﴾ باسم الإشارة للمكان البعيد؟","answer":"﴿هنالك﴾ تشير إلى مقام المواجهة الحاسم وتبعده رتبةً لعظم ما وقع فيه، لا لمجرد البعد المكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص246–247، تحت «سر التعبير باسم الإشارة ﴿هنالك﴾»","url":""}]},{"id":"s7-698","number":698,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"كيف يوضح الضمير في ﴿وانقلبوا صاغرين﴾ مآل أهل الباطل؟","answer":"إذا حمل الانقلاب على الرجوع شمل الضمير الجمع ومنهم السحرة؛ أما إذا حمل على الصيرورة فالمراد فرعون وملؤه الذين صاروا صاغرين. ولا يحمل الصغار في هذا الوجه على السحرة بعد إيمانهم، فقد انتقلوا إلى عزة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص247، تحت «مرجع الضمير في ﴿وانقلبوا﴾»","url":""}]},{"id":"s7-699","number":699,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿انقلبوا صاغرين﴾ لا «رجعوا مهزومين»؟","answer":"يفيد الانقلاب تحول الحال، وهو أبلغ من مجرد الرجوع؛ فقد انقلب أهل الباطل إلى حال أدنى مما كانوا عليه. ويبين وصف الصغار أن الغلبة أورثتهم الذل والانقياد، مع مناسبة جرس ﴿انقلبوا﴾ لقوله ﴿فغلبوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص247–248، تحت «نكتة إيثار لفظ ﴿وانقلبوا﴾»","url":""}]},{"id":"s7-700","number":700,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"لماذا وصفوا بـ﴿صاغرين﴾؟","answer":"الصغار ذلة مع قهر؛ فناسب من تكبروا بالسحر ثم أظهر الله عجزهم أمام الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص247، تحت «علة التعبير بلفظ ﴿صاغرين﴾»","url":""}]},{"id":"s7-701","number":701,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"لماذا بُني ﴿وألقي السحرة ساجدين﴾ للمجهول؟","answer":"يصور البناء للمجهول سرعة خرورهم وقوة استجابتهم لما عاينوه، كأن قوة قاهرة ألقتهم ساجدين؛ فقد أخذت المعجزة بمجامع قلوبهم. وهو تصوير لاندفاعهم إلى السجود من غير تردد، لا تقرير لإكراه ينفي اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص250–251، تحت «نكتة إطلاق فعل الإلقاء، بصيغة البناء للمجهول»","url":""}]},{"id":"s7-702","number":702,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿أُلقي السحرة﴾ مع أنهم سجدوا باختيارهم؟","answer":"مع اختيارهم الإيمان، كانت المعجزة من شدة ظهورها سببًا غالبًا حملهم على السجود بلا تردد؛ فصوّر الفعل الاختياري في هيئة إلقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص251، تحت «بلاغة الاستعارة التمثيلية، في الآية القرآنية»","url":""}]},{"id":"s7-703","number":703,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"لم أظهر وصف ﴿السحرة﴾ في ﴿وألقي السحرة ساجدين﴾ مع أنهم آمنوا؟","answer":"عين اللفظ السحرة المعروفين الذين باشروا المنازلة دون سائر الحاضرين، وأبرز أن أهل الصنعة أنفسهم عرفوا الفرق بين السحر والمعجزة. فسجودهم أقوى في الدلالة على بطلان السحر وصدق موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص252، تحت «سر عهدية الألف واللام، وإظهار الفاعل»","url":""}]},{"id":"s7-704","number":704,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"لماذا عبّر بـ﴿ساجدين﴾ لا «فسجدوا»؟","answer":"﴿ساجدين﴾ حال تصور هيئة سقوطهم وثباتهم في السجود لحظة الإلقاء، بخلاف فعل مجرد يخبر بوقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص252–253، تحت «نكتة الإتيان بالسجود على صيغة اسم الفاعل ﴿ساجدين﴾»","url":""}]},{"id":"s7-705","number":705,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"ما مناسبة انتقالهم من الإلقاء للسحر إلى أن يُلقوا هم ساجدين؟","answer":"في لفظ الإلقاء مشاكلة لإلقائهم السحر قبل ذلك؛ فألقوا أولًا أدوات سحرهم، ثم خروا هم ساجدين حين ظهر الحق. ويصور هذا التحول سرعة استجابتهم وشدة تأثير المعجزة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص250–251، تحت «نكتة إطلاق فعل الإلقاء، بصيغة البناء للمجهول»","url":""}]},{"id":"s7-706","number":706,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]},{"surah":20,"verses":[70]},{"surah":26,"verses":[46]}],"verseLabel":"الأعراف: 120؛ طه: 70؛ الشعراء: 46","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وألقي السحرة ساجدين﴾ بالواو، وفي طه والشعراء: ﴿فألقي السحرة﴾ بالفاء؟","answer":"الواو في الأعراف تشرك سجود السحرة مع ما سبق في الدلالة على ثبوت نبوة موسى وظهور الحق؛ فلا تجعله مجرد أثر مترتب على غلبة السحرة. وفي الشعراء تأتي الفاء بعد تلقف العصا ما يأفكون للتعقيب، وفي طه تفصح الفاء عن سرعة الاستجابة بعد الأمر بالإلقاء وما دل عليه من وقوع المعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص251–252، تحت «سر العدول إلى العطف بالواو، دون غيره»","url":""}]},{"id":"s7-707","number":707,"surah":7,"verses":[121],"references":[{"surah":7,"verses":[121]}],"verseLabel":"الأعراف: 121","question":"ما دلالة الجملة الفعلية ﴿قالوا آمنا برب العالمين﴾ بعد سجودهم؟","answer":"تنسب إليهم إعلان الإيمان بالقول كما أظهروا السجود بالفعل، وتبرز حدوث هذا الإعلان عقب المعجزة. فصورته الجملة الفعلية انتقالًا متجددًا من الكفر إلى الإيمان، يوافق ما ظهر على جوارحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص255، تحت «التعبير بالفعل المبني للمعلوم، والجملة الفعلية»","url":""}]},{"id":"s7-708","number":708,"surah":7,"verses":[121],"references":[{"surah":7,"verses":[121]}],"verseLabel":"الأعراف: 121","question":"لماذا اختاروا وصف ﴿رب العالمين﴾ نفسه الذي واجه به موسى فرعون؟","answer":"اختاروا ﴿رب العالمين﴾ ردًا على ربوبية فرعون المزعومة، وموافقةً لما أعلن موسى أنه رسول منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص256–257، تحت «تعريف لفظ الرب، ودلالة الباء الجارة»","url":""}]},{"id":"s7-709","number":709,"surah":7,"verses":[121],"references":[{"surah":7,"verses":[121]}],"verseLabel":"الأعراف: 121","question":"لم أسند القول إلى السحرة معلومًا في ﴿قالوا آمنا﴾؟","answer":"ليصرح بأنهم أظهروا الإيمان بألسنتهم، كما أظهروه بسجودهم؛ فإسناد القول إليهم يثبت إعلانهم ما استقر في قلوبهم، ويجعل شهادة اللسان موافقة لعمل الجوارح.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص255، تحت «التعبير بالفعل المبني للمعلوم، والجملة الفعلية»","url":""}]},{"id":"s7-710","number":710,"surah":7,"verses":[121],"references":[{"surah":7,"verses":[121]}],"verseLabel":"الأعراف: 121","question":"ما أثر الجمع بين سجود السحرة وقولهم ﴿آمنا برب العالمين﴾؟","answer":"السجود إعلان مرئي للخضوع، وقولهم ﴿آمنا﴾ إعلان صريح لمعناه. فاجتمع الفعل والقول لتقرير إيمانهم وإزالة احتمال أن يحمل سجودهم على غير الإيمان بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص255، تحت «إعلان الإيمان، بين الفعل المرئي، والقولي»","url":""}]},{"id":"s7-711","number":711,"surah":7,"verses":[122],"references":[{"surah":7,"verses":[122]}],"verseLabel":"الأعراف: 122","question":"لماذا بيّنوا بعد ذلك: ﴿رب موسى وهارون﴾؟","answer":"بيّنوا ﴿رب موسى وهارون﴾ ليرفعوا احتمال أن يريد فرعون برب العالمين نفسه أو معبودًا آخر، فعيّنوا رب الرسولين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص258–259، تحت «وجه الاحتراس والتبكيت في الآية»","url":""}]},{"id":"s7-712","number":712,"surah":7,"verses":[122],"references":[{"surah":7,"verses":[122]}],"verseLabel":"الأعراف: 122","question":"ما سرّ تقديم موسى على هارون؟","answer":"قُدم موسى لأنه صاحب المواجهة وإظهار العصا والمتصدر في الرسالة، وهارون تابع له في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص260–261، تحت «توجيه متشابه اللفظ، بين هذه الآية ومثيلاتها في مواقع أخر»","url":""}]},{"id":"s7-713","number":713,"surah":7,"verses":[122],"references":[{"surah":7,"verses":[122]}],"verseLabel":"الأعراف: 122","question":"لماذا أضافوا الرب إلى موسى وهارون مع أنه رب العالمين؟","answer":"الإضافة تعيّن رب العالمين الذي دعوا إليه وتعلن انضمامهم إلى دعوة موسى وهارون في وجه فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص259–260، تحت «سر إتباع التراكيب بعضها بعضًا في السياق»","url":""}]},{"id":"s7-714","number":714,"surah":7,"verses":[122],"references":[{"surah":7,"verses":[122]}],"verseLabel":"الأعراف: 122","question":"ما أثر تكرير لفظ ﴿رب﴾ في ﴿رب العالمين﴾ ثم ﴿رب موسى وهارون﴾؟","answer":"هو من الترديد؛ عاد اللفظ متعلقًا في كل موضع بما يخصص جهة من المعنى. فالأول يقرر عموم الربوبية، والثاني يعين المقصود ويدفع اللبس، فيؤكد المعنى ويزيده وضوحًا في نفس السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص260، تحت «بلاغة الترديد في الآية الكريمة»","url":""}]},{"id":"s7-715","number":715,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما سرّ تعبير فرعون بـ﴿آمنتم به قبل أن آذن لكم﴾، فجعل الإيمان محتاجًا إلى إذنه؟","answer":"كشف قوله أن الطاغية يعد ضمائر الناس ملكًا له، فلا يجيز الإيمان إلا بإذنه؛ وفي ذلك تصوير لأقصى الاستبداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص265، تحت «فصل الكلام، والتعبير بالمصدر المنسبك»","url":""}]},{"id":"s7-716","number":716,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لماذا جاء الاستفهام في قراءة ﴿أآمنتم﴾ للإنكار؟","answer":"الاستفهام إنكاري توبيخي؛ يستنكر استقلالهم بالإيمان ويهددهم، لا يستفهم عن وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص263–264، تحت «توجيه تعدد القراءات القرآنية في السياق»","url":""}]},{"id":"s7-717","number":717,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿آمنتم به﴾، وفي طه والشعراء: ﴿آمنتم له﴾؟","answer":"﴿آمنتم به﴾ تفيد التصديق بموسى أو بالله، و﴿آمنتم له﴾ تتضمن معنى الانقياد والتصديق لما دعا إليه؛ وكل سياق يبرز جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص264–265، تحت «سر تعدية الإيمان بالباء ﴿به﴾ واللام ﴿له﴾»","url":""}]},{"id":"s7-718","number":718,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لم صرح باسم فرعون في ﴿قال فرعون آمنتم به﴾؟","answer":"أظهر اسمه في مورد الذم والخسران، كما أظهر اسم موسى في موطن التشريف. وفي التصريح تعيين لصاحب الاعتراض والطغيان، وزيادة في إشهار مذمته في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص263، تحت «سر إظهار الفاعل، لفظ ﴿فرعون﴾ في السياق»","url":""}]},{"id":"s7-719","number":719,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لم جاء ﴿قبل أن آذن لكم﴾ بالمصدر المؤول بدل «قبل إذني لكم»؟","answer":"يبرز تركيب ﴿أن آذن﴾ نفس فعل الإذن الذي يزعم فرعون اشتراطه، فيقوي توبيخه لهم على سبق إيمانهم إذنه، ويكشف كبره وادعاء التحكم في استجابتهم للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص265، تحت «فصل الكلام، والتعبير بالمصدر المنسبك»","url":""}]},{"id":"s7-720","number":720,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"كيف قوّى فرعون تهمة المكر في ﴿إن هذا لمكر مكرتموه﴾؟","answer":"حشد إن واللام، وجاء بالجملة الاسمية لتقرير التهمة في أذهان السامعين. ومقصوده تهويل ما نسبه إلى السحرة وتسويغ الوعيد الشديد الذي سيلحقه بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص265–266، تحت «بلاغة حشد التوكيدات والتعبير باسمية الجملة»","url":""}]},{"id":"s7-721","number":721,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لماذا كرر مادة المكر: ﴿لمكر مكرتموه﴾؟","answer":"الجمع بين الاسم والفعل توكيد؛ سمى الحادث كله مكرًا ثم نسب صنعه إليهم عمدًا، تثبيتًا لتهمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص266، تحت «بديع الجناس الاشتقاقي، في سياق الآية»","url":""}]},{"id":"s7-722","number":722,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿في المدينة﴾ مع أن المكر المزعوم ظهر في ساحة اللقاء؟","answer":"يجوز أن يريد اتفاقهم المزعوم في المدينة قبل خروجهم إلى موضع الاجتماع، ويجوز أن تكون الظرفية مجازية، أي مكر قصدوا به الإضرار بالمدينة وأهلها. فلا ينحصر التعبير في تعيين مكان تدبير المؤامرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص266–267، تحت «بلاغة مجاز الظرف للحرف ﴿في﴾ من الآية»","url":""}]},{"id":"s7-723","number":723,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما غرض فرعون من اتهامهم بقوله ﴿لتخرجوا منها أهلها﴾؟","answer":"زعم أن إيمانهم حيلة متفق عليها للإضرار بأهل المدينة وإخراجهم، فحول دلالة المعجزة إلى تهمة تهدد الملك والسلطان. والمراد بأهلها في هذا المقام فرعون وقومه الذين يتولى حمايتهم في زعمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص266–267، تحت «بلاغة مجاز الظرف للحرف ﴿في﴾ من الآية»","url":""}]},{"id":"s7-724","number":724,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لماذا قدّم الجار والمجرور في ﴿منها أهلها﴾؟","answer":"قدم ﴿منها﴾ للعناية بالمدينة؛ فهي مقر الحكم ودار الملك وموضع أطماع السلطان. فتصدر ذكرها يصور الخطر الذي يزعمه فرعون على سلطانه وأهل مدينته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص267–268، تحت «نكتة تقديم ﴿منها﴾ على المفعول ﴿أهلها﴾»","url":""}]},{"id":"s7-725","number":725,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لماذا هددهم بإبهام: ﴿فسوف تعلمون﴾ قبل تفصيل العقوبة؟","answer":"أبهم ما سيعلمونه ليضخم الوعيد ويفتح الخيال على عقاب مهول، ثم فصله في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص268، تحت «بلاغة التفريع على الإنكار، على طريق المجاز»","url":""}]},{"id":"s7-726","number":726,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما سرّ التصريح باسم فرعون في الأعراف: ﴿قال فرعون آمنتم به﴾، وإضماره في طه والشعراء؟","answer":"التصريح بفرعون في الأعراف يبرز اسمه في مقام الذم مقابل إظهار موسى في مقام التشريف. ويذكر المصدر في مقارنة طه أن ذكره في الأعراف يجلي المقابلة بين رب العالمين ومدعي الربوبية، أما طه فورد فيها ﴿رب هارون وموسى﴾. وفي الشعراء أضمر الفاعل لأمن اللبس، مع ملاءمة الإضمار للإعراض عنه؛ فلا يحصر الفرق في قرب الاسم وبعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص314، تحت «توجيه المتشابه اللفظي في الحذف والذكر»","url":""}]},{"id":"s7-727","number":727,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"لماذا أكد الوعيد باللام والنون: ﴿لأقطعن... ولأصلبنكم﴾؟","answer":"اللام ونون التوكيد الثقيلة تصوران قسمه وتصميمه على تنفيذ التعذيب، في مواجهة ثبات المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص271، تحت «بلاغة التوكيد باللام في لفظ ﴿لأقطعن﴾»","url":""}]},{"id":"s7-728","number":728,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"لماذا قدّم تقطيع الأيدي والأرجل على الصلب؟","answer":"على وجه الترتيب الزمني يبدأ الوعيد بالتقطيع ثم يتبعه التصليب، فتجتمع صور التنكيل ويشتد التهديد. ويعرض المصدر وجوهًا في توالي العقوبتين، منها إمهالهم بعد القطع ليشاهد الناس أثره، فلا يجعل تعليل الترتيب منحصرًا في إطالة الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص272–273، تحت «دلالة ﴿ثم﴾ على توالي العذابين، التقطيع ثم التصليب»","url":""}]},{"id":"s7-729","number":729,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿أيديكم وأرجلكم﴾ فجمع الطرفين؟","answer":"جمع الأيدي والأرجل لاستيعاب السحرة وبيان أن العقوبة ستصيب طرفي كل واحد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص271، تحت «سر تقديم لفظ ﴿أيديكم﴾ وجمعها»","url":""}]},{"id":"s7-730","number":730,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿من خلاف﴾؟","answer":"أي يقطع اليد من جانب والرجل من الجانب المقابل؛ فتشتد الإعاقة والتشويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص269، تحت «شرح المفردات: ﴿خلاف﴾»","url":""}]},{"id":"s7-731","number":731,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"لماذا عطف الصلب بـ﴿ثم﴾؟","answer":"تحتمل ﴿ثم﴾ التراخي الرتبي لتعظيم التصليب وما فيه من تنكيل، دون اشتراط مهلة زمنية. ويذكر المصدر أيضًا وجه الترتيب والمهلة بعد القطع؛ فالمقصود تهويل الوعيد، ولا تنحصر الدلالة في طول الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص272–273، تحت «دلالة التعبير بحرف التراخي ﴿ثم﴾»","url":""}]},{"id":"s7-732","number":732,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"لماذا ختم التهديد بـ﴿أجمعين﴾؟","answer":"﴿أجمعين﴾ تهديد بالاستئصال الشامل؛ لا يستثني من المؤمنين أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص272–273، تحت «دلالة ﴿ثم﴾ على توالي العذابين، التقطيع ثم التصليب»","url":""}]},{"id":"s7-733","number":733,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"ما سرّ مجيء ﴿ثم لأصلبنكم﴾ في الأعراف، و﴿ولأصلبنكم﴾ في طه والشعراء؟","answer":"تخص ﴿ثم﴾ في الأعراف معنى التراخي، ومن وجوهه تعظيم التصليب رتبة بعد التقطيع. أما الواو في طه والشعراء فتفيد مطلق الجمع ولا تعين ترتيبًا أو مهلة، فلا تعارض بين التعبيرين. ويربط المصدر اتساع دلالة الواو ببسط القصة في السورتين، لا باختصارهما ولا بمجرد الفواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص273، تحت «بيان متشابه الألفاظ بين الآي»","url":""}]},{"id":"s7-734","number":734,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"لماذا أجاب السحرة التهديد بقولهم: ﴿إنا إلى ربنا منقلبون﴾؟","answer":"واجهوا تهديده بأن الموت ليس نهاية بل رجوع إلى ربهم؛ فسلطان فرعون ينتهي عند الجسد وحكم الله هو الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص275–276، تحت «بلاغة الإيجاز في الجواب الصادر منهم»","url":""}]},{"id":"s7-735","number":735,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"ما أثر الجملة الاسمية واسم الفاعل في ﴿إنا إلى ربنا منقلبون﴾؟","answer":"تقرر الجملة رجوعهم إلى الله أمرًا ثابتًا، ويصور اسم الفاعل ﴿منقلبون﴾ هذا المآل كالوصف المستقر لهم. فتكشف ثبات يقينهم وطمأنينتهم في مواجهة الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص277، تحت «قصدية التعبير بالجملة الاسمية، واسم الفاعل»","url":""}]},{"id":"s7-736","number":736,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"لماذا قدّموا ﴿إلى ربنا﴾ على ﴿منقلبون﴾؟","answer":"قدموا ﴿إلى ربنا﴾ للاختصاص والعناية: إلى ربنا وحده المصير، لا إلى سلطانك وحكمك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص276، تحت «بلاغة تقديم الجار والمجرور ﴿إلى ربنا﴾»","url":""}]},{"id":"s7-737","number":737,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"ما سرّ تعبير السحرة بـ﴿ربنا﴾ في وجه فرعون؟","answer":"إضافة الرب إليهم إعلان ولائهم لله وقطع لربوبية فرعون عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص276–277، تحت «بلاغة اتحاد الضمائر، في السياق الحكيم»","url":""}]},{"id":"s7-738","number":738,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"لماذا اختاروا ﴿منقلبون﴾ لا «راجعون» أو «ميتون»؟","answer":"الانقلاب رجوع مع تحول من حال إلى حال؛ فهو انتقال بالموت إلى حكم الله وثوابه، لا فناء مجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص274، تحت «شرح المفردات: ﴿منقلبون﴾»","url":""}]},{"id":"s7-739","number":739,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"ما سرّ زيادة ﴿لا ضير﴾ في الشعراء قبل ﴿إنا إلى ربنا منقلبون﴾، وحذفها في الأعراف؟","answer":"زاد الشعراء ﴿لا ضير﴾ لأن قصتها أبسط وأوفى في حوار المواجهة، أما الأعراف فاختصرت فبدأت مباشرة بعلة عدم المبالاة: الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص277–278، تحت «بلاغة المتشابه اللفظي بين آية الأعراف125، وآية الشعراء50»","url":""}]},{"id":"s7-740","number":740,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"ما سرّ تعبيرهم بـ﴿وما تنقم منا﴾، وما دلالة ﴿تنقم﴾؟","answer":"﴿تنقم﴾ أي تعيب وتكره وتعاقب؛ فهم ينكرون أن يكون له عليهم مأخذ إلا إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279، تحت «شرح المفردات: ﴿تنقم﴾»","url":""}]},{"id":"s7-741","number":741,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا جاء القصر: ﴿إلا أن آمنا﴾؟","answer":"القصر يفضح ظلم فرعون: لا جريمة لهم إلا أن صدقوا آيات ربهم حين ظهرت.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص281–282، تحت «بلاغة التعبير بالاستثناء المفرغ في السياق»","url":""}]},{"id":"s7-742","number":742,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"ما أثر ربط الإيمان بالآيات في ﴿آمنا بآيات ربنا﴾؟","answer":"تربط الباء إيمانهم بموضوع التصديق ربطًا وثيقًا، وتضيف الآيات إلى ربهم تنويهًا بها وبمصدرها. فإيمانهم استجابة لحجج ربهم التي ظهرت لهم، وهو ما يجعل معاقبتهم عليه ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص282–283، تحت «دلالة حرف الباء في قوله تعالى: ﴿بآيات﴾»","url":""}]},{"id":"s7-743","number":743,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"ما وجه اختيار ﴿جاءتنا﴾ في وصف آيات الله التي آمن بها السحرة؟","answer":"المجيء أعم من الإتيان، وقد يقع فيما فيه شدة وصعوبة؛ والآيات التي شاهدوها كان لها وقع شديد مهيب في نفوسهم. فاختياره يصور قوة أثرها حين ظهرت لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص283، تحت «دلالة إيثار فعل المجيء، على الإتيان»","url":""}]},{"id":"s7-744","number":744,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"كيف تتكامل الإضافتان في ﴿آيات ربنا﴾؟","answer":"أضيفت الآيات إلى الرب تنويهًا بعظمتها، وأضيف الرب إلى ضميرهم إعلانًا لانتسابهم إلى ربوبيته. فاجتمع تشريف الآيات وتشريف المؤمنين بها، وتهيأ بذلك دعاؤهم اللاحق ﴿ربنا أفرغ علينا صبرًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص283، تحت «دلالة تعالق التعريفات بالإضافة»","url":""}]},{"id":"s7-745","number":745,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا قيدوا إيمانهم بـ﴿لما جاءتنا﴾؟","answer":"تربط ﴿لما﴾ إيمانهم بمجيء الآيات وظهورها، فتجعل الإيمان استجابة للدليل حين حضر. ويذكر المصدر احتمال الظرفية بمعنى حين، واحتمال الحرفية؛ وفي تقييد إيمانهم بظهور الآيات بيان لقوة حجتهم في مواجهة فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص283، تحت «سر توجيه التعبير بـ﴿لما﴾»","url":""}]},{"id":"s7-746","number":746,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا انتقلوا من محاورة فرعون إلى الدعاء: ﴿ربنا أفرغ علينا صبرًا﴾؟","answer":"بعد أن بان عجز فرعون وتهديده انقطع التعلق به، فتوجهوا إلى من يملك القلوب والمصير طالبين الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص284، تحت «بلاغة الالتفات في الخطاب»","url":""}]},{"id":"s7-747","number":747,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا استعير الإفراغ للصبر: ﴿أفرغ علينا صبرًا﴾؟","answer":"شُبّه الصبر بماء كثير يفرغ عليهم فيغمرهم؛ فطلبوا صبرًا واسعًا يحيط بنفوسهم أمام العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص285–286، تحت «دلالة الكناية، وجماع الاستعارات، عن شدة اضطرارهم إلى الله»","url":""}]},{"id":"s7-748","number":748,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا عُدّي الإفراغ بـ﴿على﴾؟","answer":"عُدّي بـ﴿على﴾ لتصوير الصبر نازلًا من فوق يغشاهم ويثبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص284، تحت «علة تقديم الجار على المفعول المطلق»","url":""}]},{"id":"s7-749","number":749,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا نُكّر ﴿صبرًا﴾؟","answer":"نُكّر للتعظيم والتكثير؛ طلبوا صبرًا عظيمًا يناسب شدة ما توعدهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص284، تحت «بلاغة الالتفات في الخطاب»","url":""}]},{"id":"s7-750","number":750,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا دعوا: ﴿وتوفنا مسلمين﴾ ولم يسألوا النجاة من فرعون؟","answer":"سألوا الثبات على الإسلام حتى الموت لأن سلامة الدين أعظم من سلامة الجسد، وقد استهانوا بعقوبة فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص280–281، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-751","number":751,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"ما دلالة وصفهم باسم الفاعل ﴿مسلمين﴾ في دعائهم ﴿وتوفنا مسلمين﴾؟","answer":"طلبوا أن تقع وفاتهم وهم ثابتون على الإسلام؛ فاسم الفاعل يصور الإسلام حالًا متحققة فيهم عند الوفاة. وفي الدعاء سؤال دوام الانقياد لله إلى ختام حياتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص286، تحت «بلاغة التعبير بلفظ اسم الفاعل، والجملة الفعلية»","url":""}]},{"id":"s7-752","number":752,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ قول الملأ: ﴿أتذر موسى وقومه﴾ بعد إشارتهم بتأخيره وجمع السحرة؟","answer":"بعد فشل السحرة عاد الملأ يحرضون فرعون، متناسين أنهم أشاروا بالإمهال؛ فالاستفهام يدفعه إلى استئناف البطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-753","number":753,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لم جعل الملأ موسى مفعولًا لفعل الترك في ﴿أتذر موسى وقومه﴾؟","answer":"صوروه بمنزلة من صار في يد فرعون ثم يوشك أن يطلقه؛ فوجهوا الإنكار إلى تركه هو، مع أنه أبعد الناس عن الخضوع لفرعون. وفي هذا التصوير تحريض على البطش وإيهام بالقدرة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص291، تحت «نكتة إسناد فعل الترك ﴿أتذر﴾ واقعًا على موسى»","url":""}]},{"id":"s7-754","number":754,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لم حذف مفعول الإفساد في اتهام موسى وقومه: ﴿ليفسدوا في الأرض﴾؟","answer":"حذف المفعول للتعميم، فكأنهم ينسبون إليهم إفساد كل ما يخشون عليه. ويدخل في زعمهم مخالفة دينهم، وانفضاض الناس عن فرعون، ومنازعة سلطانه؛ فتتسع التهمة للتحريض عليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص292–293، تحت «سر حذف مفعول الإفساد، في قوله تعالى: ﴿ليفسدوا﴾»","url":""}]},{"id":"s7-755","number":755,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ اتهامهم موسى وقومه بأنهم ﴿ليفسدوا في الأرض﴾ مع وصف السياق فرعون وملأه بالمفسدين؟","answer":"سموا دعوة الناس إلى ترك عبادة فرعون وآلهته، ورفع الاستعباد عن بني إسرائيل، إفسادًا بحسب تصورهم الباطل للمصلحة. فالتعبير يحكي تحريضهم وقلبهم حقيقة الإصلاح إلى تهمة، مع أن مقصدهم حماية سلطان فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص292–293، تحت «نكتة التعبير باللام على طريق المجاز»","url":""}]},{"id":"s7-756","number":756,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ تعبيرهم بـ﴿في الأرض﴾ مع إرادتهم أرض مصر؟","answer":"أل للعهد الحضوري؛ فالمراد أرض مصر، مملكة فرعون وموطن بني إسرائيل. فهو إطلاق اسم عام أريد به موضع مخصوص يعرفه المخاطبون، ولا يلزم منه أنهم عدوا مصر كل الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص293، تحت «دلالة أل التعريف، في لفظ ﴿الأرض﴾»","url":""}]},{"id":"s7-757","number":757,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لماذا عطفوا ﴿ويذرك وآلهتك﴾ على الإفساد؟","answer":"جمعوا بين دعوى الإفساد العامة وبين ما يعدونه أخص خطرًا، وهو ترك موسى عبادة فرعون وآلهته. فبدؤوا بالعلة العامة ثم بالتحريض الخاص الذي يمس سلطانه، ليغروه بالبطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص293–294، تحت «دلالة تقديم فعل ﴿ليفسدوا﴾ على ﴿ويذرك﴾»","url":""}]},{"id":"s7-758","number":758,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"كيف يُفهم وجود ﴿آلهة﴾ لفرعون مع ادعائه: ﴿أنا ربكم الأعلى﴾؟","answer":"يذكر المصدر أن فرعون وقومه كانوا على تعدد المعبودات، وأن الآلهة قد تكون مما عبدوه من صور الكواكب ونحوها، أو مما شرعه هو لقومه. فدعواه الربوبية العليا لا تستلزم أنه ينفي تلك الآلهة؛ وإنما جمع بين دعوى العلو عليهم وتقرير عبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص294–295، تحت «نكتة جمع ﴿وآلهتك﴾»","url":""}]},{"id":"s7-759","number":759,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ تعبير فرعون بصيغة الاستقبال في قوله: ﴿سنقتل أبناءهم﴾؟","answer":"السين تهديد بفعل متجدد سيستأنفه مستقبلًا، بعد أن كان قتل الأبناء قد وقع من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص295–296، تحت «فائدة السين، وتشديد فعل القتل ﴿سنقتل﴾»","url":""}]},{"id":"s7-760","number":760,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما دلالة قراءة ﴿سنقتّل أبناءهم﴾ بالتشديد؟","answer":"التشديد يدل على التكثير والتكرار؛ أي يكثر قتل الأبناء مرة بعد مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص295–296، تحت «فائدة السين، وتشديد فعل القتل ﴿سنقتل﴾»","url":""}]},{"id":"s7-761","number":761,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿ونستحيي نساءهم﴾ لا «ونترك نساءهم»؟","answer":"الاستحياء إبقاؤهن أحياءً للخدمة والاستذلال، فهو أخص من مجرد الترك وينطوي على قصد مهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص297، تحت «التعبير عن فعل ﴿ونستحيي﴾، على طريق المبالغة والتتميم»","url":""}]},{"id":"s7-762","number":762,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لماذا قابل قتل الأبناء باستحياء النساء؟","answer":"جمع بين إفناء قوة الرجال وإبقاء النساء للخدمة، لتصوير سياسة استئصالٍ واستعباد شاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص297–298، تحت «بلاغة أسلوب الطباق، والأسلوب الحكيم»","url":""}]},{"id":"s7-763","number":763,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لماذا ختم فرعون بقوله: ﴿وإنا فوقهم قاهرون﴾؟","answer":"أكد قدرته بـ﴿إن﴾ والجملة الاسمية ردًا على خوف الملأ، وزعم أن قهره لبني إسرائيل ثابت لا يتغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص299، تحت «سر التوكيد في الفاصلة، في هذه الآية»","url":""}]},{"id":"s7-764","number":764,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لماذا اختار ﴿فوقهم﴾ بدل «عليهم»؟","answer":"﴿فوقهم﴾ تصور علو القاهر واستيلاءه، كأنه متمكن من أعلى، وهي أقوى تصويرًا من مجرد ﴿عليهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص299، تحت «بلاغة الاستعارة في الفاصلة»","url":""}]},{"id":"s7-765","number":765,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا بدأ موسى جوابه لقومه بـ﴿استعينوا بالله﴾ قبل الأمر بالصبر؟","answer":"قدم الاستعانة لأنها مصدر القدرة على الصبر؛ فلا يثبتون أمام الطغيان بقوتهم وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص303–304، تحت «نكتة تقديم ﴿استعينوا﴾ على ﴿واصبروا﴾»","url":""}]},{"id":"s7-766","number":766,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا جمع بين الاستعانة والصبر؟","answer":"جمع لهم بين التعلق بالله وطلب معونته، وبين الثبات على ما يلقونه من البلاء. فالاستعانة بما لله من القدرة والتدبير تمدهم بما يعين على الصبر، واجتماعهما يواجه دعوى فرعون القهر والقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص304، تحت «بلاغة التعبير عن معنى التوكل بالأسلوب الحكيم»","url":""}]},{"id":"s7-767","number":767,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لم حذف متعلق الصبر في ﴿استعينوا بالله واصبروا﴾؟","answer":"حذف للتعميم، فيشمل الصبر على انتظار نصر الله، وعلى البلاء الذي يصيبهم، وعلى أذى من يجاهرهم بالعداء. فالأمر يتسع لما يحتاجون فيه إلى الثبات ولا يقصره على صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص303، تحت «سر حذف مفعول ﴿واصبروا﴾»","url":""}]},{"id":"s7-768","number":768,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الأرض لله﴾ ردًا على تهديد فرعون؟","answer":"الجملة تهدم ملك فرعون المزعوم: الأرض كلها لله، فلا يملك الطاغية أن يمنحها أو يمنعها استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص305، تحت «علة الفصل في جملة ﴿إن الأرض لله﴾»","url":""}]},{"id":"s7-769","number":769,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا عرّف ﴿الأرض﴾ مع أن النزاع على مصر؟","answer":"يحتمل التعريف العهد، فتكون الأرض أرض مصر خاصة، ويحتمل الجنس، فتدخل مصر في عموم الأرض المملوكة لله. ويذكر المصدر أيضًا حملها على أرض الجنة؛ فلا يجزم بأن التعريف للاستغراق وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص305، تحت «دلالة أل التعريف في لفظ ﴿الأرض﴾»","url":""}]},{"id":"s7-770","number":770,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿يورثها﴾، دون أن يقال: يعطيها؟","answer":"الإيراث انتقال الملك بعد زوال سابقه؛ فيوحي بأن سلطان فرعون عارض وأن الله ينقل الأرض لمن يشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص304، تحت «بلاغة التعبير بالكناية»","url":""}]},{"id":"s7-771","number":771,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"ما دلالة المضارع ﴿يشاء﴾ في ﴿يورثها من يشاء من عباده﴾؟","answer":"يدل على دوام نفاذ مشيئة الله في تمكين من يشاء ونزع الملك ممن يشاء، في الحال والاستقبال. فإيراث الأرض جار وفق إرادته، ولا يثبت لفرعون سلطان مستقل عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص306، تحت «إيثار المضارع في فعل المشيئة ﴿يشاء﴾»","url":""}]},{"id":"s7-772","number":772,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"ما أثر إضافة العباد إلى ضمير الله في ﴿من يشاء من عباده﴾؟","answer":"تخص الإضافة العباد بانتسابهم إلى الله، وفيها تشريف لهم، وتصل إيراث الأرض بسلطانه ومشيئته. فمصير الملك مرده إلى ربهم الذي يتصرف في عباده وأرضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص306، تحت «سر تعريف العباد بالإضافة في ﴿عباده﴾»","url":""}]},{"id":"s7-773","number":773,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا ختم بـ﴿والعاقبة للمتقين﴾ ولم يقل: والنصر لبني إسرائيل؟","answer":"عمم الوعد للمتقين بدل تخصيص بني إسرائيل ليقرر سنة باقية: حسن النهاية لكل من اتقى، لا امتيازًا عرقيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص307–308، تحت «بلاغة عموم جملتي الفاصلة»","url":""}]},{"id":"s7-774","number":774,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا اختيرت ﴿العاقبة﴾ لا «الغلبة»؟","answer":"العاقبة تنظر إلى نهاية الطريق بعد الابتلاء، وهي أوسع من غلبة وقتية؛ تشمل النصر والنجاة وحسن المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص307–308، تحت «دلالة التعريف بأل للفظ ﴿والعاقبة﴾»","url":""}]},{"id":"s7-775","number":775,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما سرّ قول بني إسرائيل: ﴿أوذينا من قبل أن تأتينا ومن بعد ما جئتنا﴾؟","answer":"عبّروا عن ضيقهم لأن الأذى استمر قبل رسالة موسى وبعد مجيئه، فكأنهم لم يروا أثر البشارة العاجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص311–312، تحت «نكتة التعريض بنفاد الصبر، بعد طول القهر»","url":""}]},{"id":"s7-776","number":776,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير أولًا بـ﴿أن تأتينا﴾ ثم بـ﴿ما جئتنا﴾؟","answer":"﴿أن تأتينا﴾ مصدرية تنظر إلى زمن المجيء المتوقع، و﴿ما جئتنا﴾ تؤكد تحقق المجيء الذي أعقبه استمرار الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص312–313، تحت «بديع التناوب في استعمال الإتيان والمجيء»","url":""}]},{"id":"s7-777","number":777,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"لم بني ﴿أوذينا﴾ للمجهول في شكوى بني إسرائيل؟","answer":"صرف البناء للمجهول الاهتمام إلى الأذى الذي أصابهم وقوته، دون تعيين مصدره في كل صورة. فجمع ما لحقهم من قتل واستعباد وأعمال شاقة وما تجدد من الوعيد، وركز شكواهم على استمرار المعاناة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص312، تحت «سر التعبير بالفعل المبني للمجهول ﴿أوذينا﴾»","url":""}]},{"id":"s7-778","number":778,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"لماذا أجابهم موسى بـ﴿عسى ربكم﴾ مع يقينه بوعد الله؟","answer":"ساق موسى الوعد في صورة الرجاء تعليمًا لقومه ألا يتكلوا على حصول النصر فيتركوا التقوى والعمل. والرجاء من حصول المنّة يهيئهم لشكرها؛ ويذكر المصدر أيضًا احتمال أنه لم يجزم باستحقاقهم العطاء ما داموا على حال الشكوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص314–315، تحت «نكتة التعبير بفعل الرجاء ﴿عسى﴾»","url":""}]},{"id":"s7-779","number":779,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿ربكم﴾ لا «ربي»؟","answer":"قال ﴿ربكم﴾ ليقوي صلتهم بربهم ويطمئنهم أن من يتولى إهلاك عدوهم هو مربيهم وناصرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص315، تحت «بلاغة إضمار الفاعل مقدمًا بلفظ ﴿ربكم﴾»","url":""}]},{"id":"s7-780","number":780,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما دلالة إضافة العدو إلى ضمير القوم في ﴿عدوكم﴾؟","answer":"تستحضر الإضافة ما نالهم من هذا العدو من استعباد وإذلال وتعذيب، فتربط الوعد بالإهلاك بمعاناتهم المشتركة. وفيها تذكير لهم بأن أعظم الخسران الانصراف عن عبادة الله إلى الخضوع لذلك الطغيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص315، تحت «سر نسبة العدو إلى القوم ﴿عدوكم﴾، بصيغة الجمع»","url":""}]},{"id":"s7-781","number":781,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"لم جمع موسى بين ﴿أن يهلك عدوكم﴾ و﴿ويستخلفكم في الأرض﴾؟","answer":"جمع الوعد بزوال قهر العدو والوعد بقيامهم مقامه في الأرض أحرارًا بعد الاستعباد. فالاستخلاف يتم البشارة بإزالة الطغيان، ويقابل انتقالهم إلى التمكين ما كانوا فيه من القهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص315–316، تحت «بلاغة التعبير بالمقابلة في السياق الحكيم»","url":""}]},{"id":"s7-782","number":782,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿يستخلفكم في الأرض﴾ لا «يملككم الأرض»؟","answer":"الاستخلاف جعلهم خلفاء بعد عدوهم، فيتحولون من الاستعباد إلى الحرية والتمكين. ويتصل بقوله ﴿فينظر كيف تعملون﴾، ليذكرهم أن هذه النعمة موضع امتحان للعمل والشكر، فلا يقف المعنى عند مجرد تملك الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص315–316، تحت «علة اصطفاء لفظ ﴿ويستخلفكم﴾»","url":""}]},{"id":"s7-783","number":783,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"لماذا ختم بـ﴿فينظر كيف تعملون﴾ بعد بشارة الاستخلاف؟","answer":"الخاتمة تحول البشارة إلى تكليف: سيظهر في الواقع كيف يشكرون نعمة التمكين ويقيمون أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص316–317، تحت «نكتة التعبير بالفعل المضارع»","url":""}]},{"id":"s7-784","number":784,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]},{"surah":10,"verses":[14]}],"verseLabel":"الأعراف: 129؛ يونس: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف تعملون﴾ لا «ماذا تعملون»؟","answer":"﴿كيف﴾ تسأل عن هيئة العمل وصفته من طاعة وعدل أو معصية، لا عن مجرد نوع الأفعال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص316، تحت «دلالة التعبير بـ﴿كيف﴾»","url":""}]},{"id":"s7-785","number":785,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"لماذا أكد الخبر بالقسم واللام: ﴿ولقد أخذنا آل فرعون﴾؟","answer":"القسم المقدر واللام و﴿قد﴾ تؤكد أن الابتلاء وقع حقًا، تمهيدًا للعبرة من موقفهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص320–321، تحت «بلاغة تصدير الجملة بالقسم»","url":""}]},{"id":"s7-786","number":786,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿آل فرعون﴾ لا «فرعون وقومه»؟","answer":"﴿آل فرعون﴾ تشمل خاصته وأتباعه وأهل دولته المرتبطين بسلطانه، وتبرز أن البلاء أصاب النظام الفرعوني.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص323–324، تحت «الآل، والأهل»","url":""}]},{"id":"s7-787","number":787,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"لماذا عبّر عن الابتلاء بـ﴿أخذنا﴾؟","answer":"الأخذ يصور إحاطة الشدة بهم وتمكنها منهم، مع أنه ابتلاء دون الاستئصال الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص321، تحت «سر التعبير بالأخذ على طريق المجاز، أو الاستعارة»","url":""}]},{"id":"s7-788","number":788,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿بالسنين﴾، وما المراد بالسنين هنا؟","answer":"السنون هنا القحوط؛ فقد غلب استعمال السنة في الجدب إذا عرفت بأل. ويعلل المصدر الجمع بكثرة مواقع القحط وعمومه للأراضي والبلدان، فلا ينحصر الجمع في عدد الأعوام وطولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص321–322، تحت «قصدية جمع لفظ ﴿بالسنين﴾ في السياق»","url":""}]},{"id":"s7-789","number":789,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"لماذا جمع بين ﴿السنين﴾ و﴿نقص من الثمرات﴾؟","answer":"جمع بين القحط الذي يصيب نبات الزرع والحبوب، وبين نقص ثمرات الأشجار. فتنوع البلاء في وجوه معاشهم ليحملهم على الاعتبار؛ ولا يتوقف الفرق بينهما على تعيين الآفة التي أنقصت الثمار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص322، تحت «سر تنكير لفظ ﴿ونقص﴾، وقطعه عن الإضافة»","url":""}]},{"id":"s7-790","number":790,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما دلالة تنكير ﴿نقص﴾ في ﴿ونقص من الثمرات﴾؟","answer":"يحتمل التنكير التقليل، أي قلة إنتاج الثمرات على خلاف المعتاد، ويحتمل تعظيم النقص وشدته. فصور التعبير اختلال ما ألفوه من وفرة الثمار، واتصل بسياق أخذهم بالقحط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص322، تحت «سر تنكير لفظ ﴿ونقص﴾، وقطعه عن الإضافة»","url":""}]},{"id":"s7-791","number":791,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما دلالة ﴿لعلهم يذكرون﴾ في بيان غاية الابتلاء؟","answer":"التذكر رجوع إلى الاعتبار بآيات الله واستحضار ما ينبه إلى ترك المعصية؛ فالابتلاء يدعوهم إلى قبول التذكير والرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص322–323، تحت «نكتة التعبير بصيغة الترجي، وفعل المطاوعة»","url":""}]},{"id":"s7-1615","number":1615,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما دلالة ﴿لعلهم يضرعون﴾ في الأعراف94؟","answer":"التضرع هو التذلل والتخشع، وهو كناية عن الاعتراف بالذنب والتوبة؛ فالمطلوب أن يحملهم الابتلاء على الانكسار لله والرجوع إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص71، تحت «بلاغة الكناية في لفظ التضرع»","url":""}]},{"id":"s7-792","number":792,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما أثر صيغة ﴿يذكرون﴾ في بيان غاية الابتلاء؟","answer":"تفيد صيغة المطاوعة قوة حصول التذكر والاعتبار المراد منهم، وتوحي بعظم الآثار التي تدعو إليه. فالابتلاء ينبههم ليقبلوا التذكير ويرجعوا عن المعصية، ولا يعني الترجي جهلًا من الله بمآلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص322–323، تحت «نكتة التعبير بصيغة الترجي، وفعل المطاوعة»","url":""}]},{"id":"s7-793","number":793,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما دلالة ﴿إذا﴾ في ﴿فإذا جاءتهم الحسنة﴾؟","answer":"إذا هنا شرطية تفيد تكرر مجيء الحسنة وتحققه، بما يلائم كثرة النعم. وتفرع الفاء وصف حالهم على خبر ابتلائهم السابق: لم يعتبروا، بل كانوا ينسبون النعمة إلى استحقاقهم ويتشاءمون عند الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص330، تحت «دلالة اقتران المعرف بحرف التحقيق، واقتران المنكر بحرف الشك»","url":""}]},{"id":"s7-794","number":794,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"لم عرفت ﴿الحسنة﴾ ونكرت ﴿سيئة﴾ في الآية؟","answer":"تعريف الحسنة يلائم شمول النعم وكثرتها، وتنكير السيئة يلائم ندرة ما يصيبهم منها بالنسبة إلى ذلك الخير. وفي المقابلة توبيخ لهم؛ ينسبون جنس الحسنات إلى أنفسهم، ويتشاءمون بموسى عند أي سيئة تصيبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص329–330، تحت «سر تعريف الحسنة، وتنكير السيئة»","url":""}]},{"id":"s7-795","number":795,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ تعبيرهم في الحسنة بقولهم: ﴿لنا هذه﴾؟","answer":"قولهم ﴿لنا هذه﴾ ادعاء للاستحقاق الذاتي، كأن النعمة حق ثابت لهم لا فضل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص327–328، تحت «سر اختيار حروف الجر، وتقديم الضمير»","url":""}]},{"id":"s7-796","number":796,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"لماذا أشاروا إلى الحسنة بـ﴿هذه﴾؟","answer":"الإشارة إلى الحسنة دون التصريح بمصدرها تلائم إنكارهم أنها نعمة من الله؛ فقد نسبوها إلى استحقاقهم واكتفوا بقولهم ﴿لنا هذه﴾. ويبرز ذلك غفلتهم عن المنعم الذي يشهد به حصول النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص328، تحت «نكتة التعبير باسم الإشارة ﴿هذه﴾»","url":""}]},{"id":"s7-797","number":797,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن تصبهم سيئة﴾ بـ﴿إن﴾، بينما قال في الحسنة ﴿فإذا جاءتهم﴾؟","answer":"اقترنت الحسنة بإذا لكثرة وقوع النعم وتحققها، واقترنت السيئة بإن لندرتها بالنسبة إلى الخير الواسع. وفي ذلك إبراز لسوء موقفهم: يغترون بالنعم الكثيرة، ويتشاءمون عند السيئة القليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص330–331، تحت «دلالة اقتران المعرف بحرف التحقيق، واقتران المنكر بحرف الشك»","url":""}]},{"id":"s7-798","number":798,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى في الحسنة ﴿جاءتهم﴾، وفي السيئة ﴿تصبهم﴾؟","answer":"﴿جاءتهم﴾ تلائم الحسنة كوافد مرغوب، و﴿تصبهم﴾ تصور السيئة كضربة تقع عليهم؛ فاختلاف الفعلين يرسم اختلاف تلقيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص328–329، تحت «دلالة التعبير عن الحسنة بـ﴿جاءتهم﴾، وعن السيئة بـ﴿تصبهم﴾»","url":""}]},{"id":"s7-799","number":799,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ تشاؤمهم بـ﴿موسى ومن معه﴾، وإغفالهم النظر في أعمالهم؟","answer":"تشاءموا بموسى ومن معه، فجعلوا مجيئهم سبب الشدة، بدل أن يردّوا المصائب إلى كفرهم وأعمالهم؛ فجاء الرد بأن نصيبهم وما يحل بهم بتقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص333، تحت «الغرض من التعبير بالباء، في ﴿بموسى﴾»","url":""}]},{"id":"s7-800","number":800,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما أثر افتتاح الرد بـ﴿ألا﴾ في قوله: ﴿ألا إنما طائرهم عند الله﴾؟","answer":"تستفتح ﴿ألا﴾ الكلام بالتنبيه القوي إلى بطلان تشاؤمهم، وتهيئ السامع للحكم الذي يصحح زعمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص333، تحت «سر التعبير بأداة الاستفتاح والتنبيه»","url":""}]},{"id":"s7-1616","number":1616,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما أثر القصر بـ﴿إنما﴾ في قوله: ﴿إنما طائرهم عند الله﴾؟","answer":"يقصر ما يصيبهم من شؤم وعقاب على تقدير الله وجزائه، فيبطل نسبته إلى موسى ومن معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص335، تحت «سر أسلوب القصر، بالأداة ﴿إنما﴾»","url":""}]},{"id":"s7-801","number":801,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"لماذا كرر مادة الطير في ﴿يطيروا﴾ و﴿طائرهم﴾؟","answer":"في ﴿يطيروا﴾ حكاية لتشاؤمهم الباطل، وفي ﴿طائرهم﴾ مشاكلة لهم مع نقل اللفظ إلى سببه الحق: نصيبهم المترتب على أعمالهم عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص334–335، تحت «بلاغة التصريح بلفظ الطائر، على طريق الاستعارة»","url":""}]},{"id":"s7-802","number":802,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿عند الله﴾ لا «من الله»؟","answer":"﴿عند الله﴾ تفيد أن أمر حظهم وجزائهم في حكم الله وتقديره، لا أن موسى هو منشأ ما أصابهم؛ فالمقام مقام رد الأمر إلى تدبيره وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص334، تحت «بلاغة المجاز، والإظهار في مقام الإضمار، في قوله: ﴿عند الله﴾»","url":""}]},{"id":"s7-803","number":803,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"لماذا ختم بـ﴿ولكن أكثرهم لا يعلمون﴾؟","answer":"نفت الخاتمة عن أكثرهم العلم بأن ما أصابهم من عند الله وبسبب أعمالهم، وأشعرت بأن قليلًا منهم يعلم الحق ولكنه لا يعمل بمقتضاه عنادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص335–336، تحت «قصدية التعبير بالاعتراض، والاستدراك»","url":""}]},{"id":"s7-804","number":804,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"ما دلالة قولهم: ﴿مهما تأتنا به من آية﴾ بدل «أي آية تأتنا»؟","answer":"﴿مهما﴾ من ألفاظ العموم؛ فالمعنى: أيّ آية تأتنا بها، مهما كانت، لن نؤمن، وفيه إعلان العناد قبل النظر في الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص339–340، تحت «دلالة تنوع المعاني وتعدد التوجيهات، في تركب ﴿مهما﴾»","url":""}]},{"id":"s7-805","number":805,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"ما الذي يكشفه قولهم لموسى: ﴿لتسحرنا بها﴾؟","answer":"سمّوا الآية سحرًا، وزعموا أن غرض موسى بها صرفهم عما هم عليه؛ فحوّلوا الدليل إلى تهمة ليثبتوا على الإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص341–342، تحت «فائدة فعلية الجملة، والتعبير بالمضارع في ﴿لتسحرنا﴾»","url":""}]},{"id":"s7-806","number":806,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"لماذا أعادوا الضمير في ﴿به من آية﴾ ثم ﴿بها﴾؟","answer":"ذكر الضمير في ﴿به﴾ مراعاة للفظ ﴿مهما﴾ ومعناه المبهم، ثم أنثه في ﴿بها﴾ بعدما بين ذلك المبهم بقوله ﴿من آية﴾. فانتقل التعبير من مراعاة اللفظ إلى ما كشف عنه البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص341، تحت «نكتة تذكير الضمير وتأنيثه، في قوله: ﴿به﴾ و﴿بها﴾»","url":""}]},{"id":"s7-807","number":807,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"ما سرّ تعبيرهم: ﴿فما نحن لك بمؤمنين﴾ بدل «فلن نؤمن بك»؟","answer":"الجملة الاسمية مع الباء الزائدة في ﴿بمؤمنين﴾ أشد توكيدًا لنفي الإيمان من قولهم: لن نؤمن؛ فهي تصور تمكّن العناد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص342، تحت «بلاغة التعبير بالمؤكدات، واسمية الجملة، وتقديم الجار والمجرور»","url":""}]},{"id":"s7-808","number":808,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"لماذا قدّموا ﴿لك﴾ على ﴿بمؤمنين﴾؟","answer":"تقديم ﴿لك﴾ يخص موسى بالرفض ويبرز عنادهم لشخصه ورسالته: فما نحن لك، على وجه الخصوص، بمصدقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص342، تحت «بلاغة التعبير بالمؤكدات، واسمية الجملة، وتقديم الجار والمجرور»","url":""}]},{"id":"s7-809","number":809,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"لماذا عبّروا باسم الفاعل ﴿مؤمنين﴾؟","answer":"اسم الفاعل في ﴿مؤمنين﴾ يثبت نفي صفة الإيمان عنهم، لا مجرد نفي فعل يقع مرة؛ وهو ملائم لإصرارهم الدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص342، تحت «بلاغة التعبير بالمؤكدات، واسمية الجملة، وتقديم الجار والمجرور»","url":""}]},{"id":"s7-810","number":810,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا عطف إرسال الآيات بالفاء: ﴿فأرسلنا عليهم﴾؟","answer":"الفاء تفيد تعقيب العقوبات على عنادهم المعلن في الآية السابقة، فكان الإرسال جوابًا عمليًا عن قولهم إنهم لن يؤمنوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص346، تحت «بلاغة الوصل بالفاء، في قوله: ﴿فأرسلنا﴾»","url":""}]},{"id":"s7-811","number":811,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا عُدّيت الآيات بـ﴿على﴾: ﴿أرسلنا عليهم﴾؟","answer":"عدّي الإرسال بـ﴿على﴾ لأن هذه الآيات عقوبات نازلة مستعلية محيطة بهم، لا آيات مسوقة لهم على جهة التكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص346–347، تحت «علة صوغ الإرسال ماضيًا، وتعديه بعلى»","url":""}]},{"id":"s7-812","number":812,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"ما أثر نظم أسماء الآفات في ﴿الطوفان والجراد والقمل والضفادع والدم﴾؟","answer":"جمعت الآية أسماء أصناف متناسبة من العذاب في نسق واحد. ويبرز المصدر حسن تأليف هذه الألفاظ وترتيبها في اللفظ، بما فيه من انسجام يخفف ثقل بعض مفرداتها عند اجتماعها، مع وضوح تنوع العقوبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص348، تحت «بلاغة مراعاة النظير، وما لها من حسن وتأثير»","url":""}]},{"id":"s7-813","number":813,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"كيف تلائم صيغة ﴿الطوفان﴾ تصوير العذاب؟","answer":"الطوفان ما يطوف ويحيط، ويذكر المصدر أن بناء فعلان يفيد المبالغة أو يجيء اسم جنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343، تحت «شرح المفردات: ﴿الطوفان﴾»","url":""}]},{"id":"s7-814","number":814,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"كيف تنوعت صيغ أسماء الآفات في الآية، وما دلالة هذا التنوع؟","answer":"لم تجئ كلها مفردة؛ فالضفادع جمع ضفدع، ويعرض المصدر في الطوفان والجراد والقمل أبنية تدل على المبالغة أو أسماء الجنس. أما الدم فاسم جنس يصدق على قليله وكثيره. فيجتمع اختلاف الأبنية مع تصوير كثرة العذاب وتنوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص347–348، تحت «بديع تنوع الصيغ الصرفية، تعبيرًا عن صنوف العذاب المرئية»","url":""}]},{"id":"s7-815","number":815,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا خُتمت القائمة بـ﴿الدم﴾؟","answer":"يربط المصدر تأخير ﴿الدم﴾ بحسن نظم القائمة وائتلاف ألفاظها؛ فاللفظ أخف وأحسن في السمع في هذا الموضع بعد الأسماء السابقة. ولا يجعل سبب تأخيره مجرد بلوغ العذاب ماء الشرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص348، تحت «بلاغة مراعاة النظير، وما لها من حسن وتأثير»","url":""}]},{"id":"s7-816","number":816,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا وصفها بـ﴿آيات مفصلات﴾؟","answer":"﴿مفصلات﴾ أي مبينات ظاهرات، يفصل بعضها عن بعض، تأتي آية بعد آية وبينها مهلة ليعتبروا ويرجعوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص349–350، تحت «سبب التعبير بلفظ ﴿آيات﴾، ووصفها بأنها ﴿مفصلات﴾»","url":""}]},{"id":"s7-817","number":817,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا جاءت ﴿مفصلات﴾ بصيغة التفعيل؟","answer":"صيغة التفعيل تدل على قوة الفصل والتبيين؛ فقد جاءت الآيات متميزة متتابعة، لا حادثة ملتبسة يمكن صرفها عن دلالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص349–350، تحت «سبب التعبير بلفظ ﴿آيات﴾، ووصفها بأنها ﴿مفصلات﴾»","url":""}]},{"id":"s7-818","number":818,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستكبروا﴾ بعد ظهور الآيات؟","answer":"تفرع الفاء استكبارهم على ظهور الآيات، مع أن مقتضى تلك الدلائل أن يصدقوا ويؤمنوا. فتكشف شدة عنادهم وفساد تلقيهم، وصيغة الاستكبار تصور تعاظمهم عن القبول، لا خفاء الدليل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص350، تحت «إيثار التعبير بالفاء السببية، والفعل المزيد، في ﴿فاستكبروا﴾»","url":""}]},{"id":"s7-819","number":819,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا ختم بـ﴿وكانوا قومًا مجرمين﴾؟","answer":"الخاتمة تبين أن الاستكبار ليس عارضًا؛ فقد كانوا راسخين في الإجرام، ولذلك قابلوا الآيات الواضحة بالعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص350–351، تحت «بلاغة التعبير بفن التذييل»","url":""}]},{"id":"s7-820","number":820,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿قومًا مجرمين﴾ بدل «وكانوا مجرمين»؟","answer":"﴿قومًا﴾ خبر موطئ للوصف بعده، فيقوي تقرير صفة الإجرام ويبالغ في إثباتها لهم. والجملة تذيل خبر استكبارهم، فتفسره بما رسخ فيهم من الإجرام قبل ظهور هذه الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص350–351، تحت «بلاغة التعبير بفن التذييل»","url":""}]},{"id":"s7-821","number":821,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما وقع عليهم الرجز﴾، فصوّر العذاب واقعًا عليهم؟","answer":"﴿وقع﴾ يصور الرجز كحمل نازل استقر فوقهم وأحاط بهم، فيجسد شدة العذاب وتمكنه منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص355–356، تحت «بلاغة التعبير بلفظ ﴿وقع﴾، على طريق الاستعارة»","url":""}]},{"id":"s7-822","number":822,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا عبّر بـ﴿الرجز﴾ بعد تسمية الآيات الخمس؟","answer":"الرجز هو العذاب الموجب للاضطراب.؛ ويرجح المصدر أن أل للعهد، فيجمع اللفظ أصناف العذاب المذكورة قبلها تحت وصف العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص356–357، تحت «دلالة أل العهدية، في لفظ ﴿الرجز﴾»","url":""}]},{"id":"s7-823","number":823,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا نادوا: ﴿يا موسى﴾ بعد أن اتهموه بالسحر؟","answer":"لما مسهم العذاب عادوا إلى من اتهموه بالسحر، ونادوه باسمه استمالةً وطلبًا للنجدة؛ فكشف البلاء اضطرارهم إلى الاعتراف بمكان دعائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص357، تحت «سر التعبير بالنداء، وقصدية إظهار المنادى ﴿يا موسى﴾»","url":""}]},{"id":"s7-824","number":824,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"ما الذي تكشفه إضافتهم الرب إلى موسى في قولهم: ﴿ادع لنا ربك﴾ لا «ربنا»؟","answer":"إضافتهم الرب إلى موسى في ﴿ربك﴾ لا ﴿ربنا﴾ تكشف أنهم لم يدخلوا بعد في الإيمان، وإنما طلبوا كشف الضر ممن عرفوا قربه من ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص357–358، تحت «سر انتقاء الضمير في الإضافة إلى موسى بلفظ ﴿ربك﴾»","url":""}]},{"id":"s7-825","number":825,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"ما دلالة قولهم: ﴿بما عهد عندك﴾، وما المراد بالعهد؟","answer":"العهد هو ما أعطاه الله موسى من وعد بإجابة دعائه أو ما خصه به من النبوة والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص358، تحت «التعبير عن النبوة بالعهد»","url":""}]},{"id":"s7-826","number":826,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا قدّموا رفع الرجز: ﴿لئن كشفت عنا الرجز لنؤمنن لك﴾؟","answer":"جعلوا كشف الرجز شرطًا سابقًا، ثم رتبوا عليه وعد الإيمان والإرسال؛ فدل ترتيبهم على أن همهم العاجل النجاة من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص359–360، تحت «دلالة استئناف جملة ﴿لئن كشفت﴾»","url":""}]},{"id":"s7-827","number":827,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا اختير ﴿كشفت﴾ لا «رفعت»؟","answer":"الكشف إزالة ما يغطي ويحيط، فصور الرجز كغطاء ثقيل أطبق عليهم ثم أزيل، وهو أنسب من الرفع المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص354، تحت «شرح المفردات: ﴿كشفت﴾»","url":""}]},{"id":"s7-828","number":828,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا أكدوا وعد الإيمان والإرسال بالنون واللام؟","answer":"اللام ونون التوكيد الثقيلة في ﴿لنؤمنن﴾ و﴿لنرسلن﴾ غلظتا وعدهم، لتظهر المفارقة حين نكثوه بعد كشف الرجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص359–360، تحت «بديع حشد التوكيدات في الآية»","url":""}]},{"id":"s7-829","number":829,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"ما سرّ تعبيرهم: ﴿لنؤمنن لك﴾ لا «بك»؟","answer":"الإيمان المعدّى باللام هنا بمعنى التصديق والانقياد لموسى فيما جاء به، لا مجرد الإقرار بوجوده؛ أي لنصدقن دعوتك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص360، تحت «دلالة التضمين في لفظ الإيمان، في قوله: ﴿لنؤمنن لك﴾»","url":""}]},{"id":"s7-830","number":830,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا عطفوا ﴿ولنرسلن معك بني إسرائيل﴾ على الإيمان؟","answer":"جمعوا بين حق الله بالإيمان وحق بني إسرائيل بإطلاقهم؛ لأن موسى طالبهم بالأمرين، فتعهدوا بهما معًا رجاء كشف البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص360–361، تحت «بلاغة تقديم الإيمان، في قوله: ﴿لنؤمنن لك﴾»","url":""}]},{"id":"s7-831","number":831,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما كشفنا عنهم الرجز﴾ بالفاء؟","answer":"الفاء تصل الكشف مباشرة بدعاء موسى ووعدهم، وتبين سرعة إجابة الطلب وإقامة الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص364–365، تحت «دلالة الفاء، والتعبير بالفعل الماضي ﴿كشفنا﴾»","url":""}]},{"id":"s7-832","number":832,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"لماذا أعاد لفظ ﴿الرجز﴾ ظاهرًا ولم يضمره؟","answer":"كرر ﴿الرجز﴾ تصريحًا به وتوكيدًا لمعناه، مع اختلاف المقام: جاء أولًا في طلبهم، ثم في خبر كشفه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص365–366، تحت «بيان التقديم والتأخير، في قوله: ﴿عنهم الرجز﴾»","url":""}]},{"id":"s7-833","number":833,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"لماذا قيد الكشف بـ﴿إلى أجل هم بالغوه﴾؟","answer":"بيّن القيد أن الكشف إمهال مؤقت إلى نهاية مقدرة سيبلغونها حتمًا، لا نجاة مطلقة من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص366–367، تحت «سر التعبير بالأجل، دون غيره»","url":""}]},{"id":"s7-834","number":834,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"ما أثر وصف الأجل بالجملة ﴿هم بالغوه﴾؟","answer":"جاء الوصف جملة اسمية، و﴿هم﴾ مبتدأ و﴿بالغوه﴾ خبره، فتقوى نسبة بلوغ الأجل إليهم وتصور تحققها. وفي ذلك تقرير أنهم صائرون إلى الغاية المقدرة لهم، وأن كشف العذاب لا يخرجهم من سلطانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص367، تحت «فائدة العدول عن الوصف بالمفرد، إلى الوصف بالجملة»","url":""}]},{"id":"s7-835","number":835,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"لماذا جاءت المفاجأة: ﴿إذا هم ينكثون﴾؟","answer":"﴿إذا﴾ الفجائية تصور أنهم ما إن وجدوا العافية حتى بادروا إلى نقض العهد، من غير تردد أو وفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص367، تحت «نكتة التعبير بحرف المفاجاة ﴿اذا﴾»","url":""}]},{"id":"s7-836","number":836,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"لماذا عبّر بالمضارع ﴿ينكثون﴾؟","answer":"المضارع يستحضر مشهد النكث ويصوره عادة متجددة منهم كلما كشف عنهم البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص368–369، تحت «قصدية تقديم ضمير الفصل، والتعبير بالفعل المضارع»","url":""}]},{"id":"s7-837","number":837,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿ينكثون﴾ لا «يخلفون»؟","answer":"النكث أصله نقض المفتول بعد إحكامه، فصوّر إفسادهم للعهد المؤكد كحل حبل محكم، وهو أبلغ من مطلق الإخلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص368–369، تحت «بلاغة التعبير عن نقض العهد، على طريق الاستعارة»","url":""}]},{"id":"s7-838","number":838,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا بدأت العقوبة بـ﴿فانتقمنا منهم﴾ بعد تكرر النكث؟","answer":"الفاء تجعل الانتقام نتيجة متعقبة لتكرر النكث بعد تمام الحجة، فلا يبدو الإغراق عقوبة بلا سبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص373–374، تحت «سر التعبير عن الانتقام بصيغة الافتعال ﴿فانتقمنا﴾»","url":""}]},{"id":"s7-839","number":839,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]},{"surah":15,"verses":[79]}],"verseLabel":"الأعراف: 136؛ الحجر: 79","question":"ما سر اختيار لفظ ﴿فانتقمنا﴾ في قوله تعالى: ﴿فانتقمنا منهم﴾؟","answer":"لأن الانتقام هنا عقوبة مترتبة على ظلم متقدم وإصرار على التكذيب؛ فدل اللفظ على أن ما نزل بهم جزاء عدل بسبب جرمهم وكفرانهم للنعمة، لا عذابًا مجردًا بلا سبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص681، تحت «سر اختيار لفظ ﴿فانتقمنا﴾ دون (عذبنا) أو (عاقبنا)»","url":""}]},{"id":"s7-840","number":840,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا فصّل الانتقام بقوله: ﴿فأغرقناهم في اليم﴾؟","answer":"جاء ﴿فأغرقناهم﴾ بيانًا لصورة الانتقام وكيفية وقوعه، بعد ذكره إجمالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص374–375، تحت «دلالة تفريع الانتقام بالإغراق، في ﴿فأغرقناهم في اليم﴾»","url":""}]},{"id":"s7-841","number":841,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا اختير ﴿اليم﴾ لا «البحر»؟","answer":"اليم اسم للماء الكثير العميق الذي لا يدرك قعره، وهو يلائم مقام الإغراق والهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص379–381، تحت «البحر واليم»","url":""}]},{"id":"s7-842","number":842,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لم أجمل خبر إغراق فرعون وقومه في ﴿فأغرقناهم في اليم﴾؟","answer":"ساق خبر الإغراق هنا موجزًا لأن المقام مقام الأخذ الحاسم بعد طول الإمهال، فناسبه الإيجاز وسرعة انقضاء الخبر. وأجمل ما فصلته مواضع أخرى، ليقع الوعيد في النفس ويتهيأ الانتقال إلى خبر إنجاء المستضعفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص375–376، تحت «سر العدول عن الإطناب، إلى الإيجاز والإجمال»","url":""}]},{"id":"s7-843","number":843,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا صرّح بسبب الإغراق: ﴿بأنهم كذبوا بآياتنا﴾؟","answer":"صرح بالسبب ليبين عدل العقوبة وأنها جزاء تكذيب مقصود بالآيات، لا حادثة منفصلة عن أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص376–377، تحت «دلالة الباء والمصدر في قوله: ﴿بأنهم كذبوا﴾»","url":""}]},{"id":"s7-844","number":844,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا جمع بين التكذيب والغفلة: ﴿كذبوا بآياتنا وكانوا عنها غافلين﴾؟","answer":"التكذيب فعلهم الظاهر في مقابلة الحجج، والغفلة إعراضهم المستمر عن دلالتها وعواقبها؛ فجمع بين الجحود وترك الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص377، تحت «نكتة التعبير بالجملتين: الاسمية والفعلية»","url":""}]},{"id":"s7-845","number":845,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"كيف وُصفوا بالغفلة مع أنهم رأوا الآيات وطلبوا كشف العذاب؟","answer":"الغفلة هنا ليست عدم رؤية الآيات، بل الإعراض عن موجبها وترك الاعتبار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص377–378، تحت «دلالة عود الضمير في ﴿عنها﴾، إلى الآيات المدرجات في السياق»","url":""}]},{"id":"s7-846","number":846,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"ما سرّ التعبير في قوله تعالى: ﴿عنها غافلين﴾ بتقديم الجار والمجرور؟","answer":"تقديم ﴿عنها﴾ يبرز أن الآيات، مع وضوحها وكثرتها، هي عين ما أعرضوا عنه؛ وفيه تشديد للتوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص378–379، تحت «علة تقديم شبه الجملة على الخبر، والتعبير باسم الفاعل ﴿غافلين﴾»","url":""}]},{"id":"s7-847","number":847,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿وأورثنا القوم الذين كانوا يستضعفون﴾، دون أن يقال: وأعطينا بني إسرائيل؟","answer":"الإيراث تمليك يعقب زوال المالك السابق من غير كلفة على الوارث، فناسب انتقال أرض الجبارين إلى المستضعفين، وذكرهم بوصفهم السابق يبرز انقلاب الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص386–387، تحت «علة إيثار التعبير بالإيراث ﴿وأورثنا﴾، وكونه بصيغة الماضي»","url":""}]},{"id":"s7-848","number":848,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا وصفهم بالماضي المستمر: ﴿كانوا يستضعفون﴾؟","answer":"﴿كانوا يستضعفون﴾ تدل على أن الاستضعاف كان حالة مستمرة متكررة قبل التمكين، لا واقعة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص388، تحت «علة بناء فعل الاستضعاف ﴿يستضعفون﴾ للمجهول»","url":""}]},{"id":"s7-849","number":849,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا بُني ﴿يستضعفون﴾ للمجهول؟","answer":"يصور البناء للمجهول وقوع الاستضعاف عليهم من قاهر، ولا يصفهم بضعف ذاتي لازم. ويتصل بكان والمضارع لإبراز استمرار ما فرض عليهم من أسباب الضعف وتجددها، ثم يظهر الفرق بين تلك الحال وما أورثهم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص388، تحت «علة بناء فعل الاستضعاف ﴿يستضعفون﴾ للمجهول»","url":""}]},{"id":"s7-850","number":850,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿مشارق الأرض ومغاربها﴾ بالجمع؟","answer":"الجمع يلحظ تعدد جهات الشروق والغروب واختلافها في الأرض الموروثة، فيفيد سعتها وشمول التمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص389، تحت «السر في جمع المشارق والمغارب»","url":""}]},{"id":"s7-851","number":851,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا جمع بين المشارق والمغارب؟","answer":"ذكر المشارق والمغارب إحاطة بطرفي الأرض، أي أورثهم نواحيها الممتدة كلها، لا جهة واحدة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص388–389، تحت «دلالة وجهي المجاز والحقيقة، في التعبير عن تمليك أطراف الأرض»","url":""}]},{"id":"s7-852","number":852,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا وصف الأرض بـ﴿التي باركنا فيها﴾؟","answer":"يبين الوصف دوام الخير والخصب وسعة الأرزاق في الأرض التي أورثوها، ويذكر المصدر كونها مساكن الأنبياء والصالحين. ويعرض تفسير الأرض بالشام، ويذكر أيضًا مصر والشام؛ فلا يحصر الجواب تعيينها في قول واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص389–390، تحت «نكتة إيثار صيغة فاعل، في ﴿باركنا﴾»","url":""}]},{"id":"s7-853","number":853,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿وتمت كلمة ربك الحسنى﴾، وكيف تتم الكلمة؟","answer":"تمام الكلمة تحقق مضمون الوعد كاملًا في الواقع؛ فقد أنجز الله وعده بنجاة المستضعفين وتمكينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص390–391، تحت «براعة التعبير بالتمام على طريق الاستعارة، في قوله: ﴿وتمت﴾»","url":""}]},{"id":"s7-854","number":854,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا أضيف الرب إلى النبي: ﴿ربك﴾ بعد أن كان الخطاب عن بني إسرائيل؟","answer":"إضافة الرب إلى النبي ﷺ في ﴿ربك﴾ تسلية له وتثبيت: فالرب الذي أنجز وعده لبني إسرائيل سينجز وعده لرسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص392، تحت «الالتفات في قوله: ﴿ربك﴾»","url":""}]},{"id":"s7-855","number":855,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا وُصفت الكلمة بـ﴿الحسنى﴾؟","answer":"﴿الحسنى﴾ لأن الكلمة وعد جميل بالنصر والتمكين، ولأن عاقبتها الحسنى ظهرت بتمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص392، تحت «بلاغة الوصف بلفظ ﴿الحسنى﴾»","url":""}]},{"id":"s7-856","number":856,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿بما صبروا﴾ لا «لأنهم استُضعفوا»؟","answer":"علّق تمام الوعد بصبرهم ليبين أن التمكين جزاء ثباتهم على البلاء، لا لمجرد وقوع الاستضعاف عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص393، تحت «سر التعبير بالباء السببية والمصدر في ﴿بما صبروا﴾»","url":""}]},{"id":"s7-857","number":857,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿ودمرنا ما كان يصنع فرعون وقومه﴾؟","answer":"التدمير إهلاك الشيء وإفساد بنائه، فشمل ما أنشأه فرعون وقومه من صنائع ومنشآت وما أقاموه من سلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص393–394، تحت «فائدة التعبير بالتدمير عن الإهلاك»","url":""}]},{"id":"s7-858","number":858,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لم أظهر اسما فرعون وقومه في ﴿ما كان يصنع فرعون وقومه﴾؟","answer":"في التصريح بهما زيادة في ذمهما بعد ذكر تدمير مصنوعاتهما، إذ وقع الاسمان في مقام الخسران والعقوبة. وعطف قومه عليه يبين مشاركتهم له في أعمال الاستعباد والظلم والفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص393–394، تحت «بلاغة تقديم الصنع، وإظهار فاعليه»","url":""}]},{"id":"s7-859","number":859,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما أثر اجتماع كان والمضارع في ﴿ما كان يصنع فرعون وقومه وما كانوا يعرشون﴾؟","answer":"تدل كان على تحقق تلك الأعمال في الماضي، ويستحضر المضارع تكرر الصنع والعرش واستمرارهما. فيصور ما كانوا يزاولونه عملًا متجددًا مألوفًا، ثم وقع عليه التدمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص395، تحت «دلالة الجمع بين الماضي والمضارع، والعدول في الخبر إلى المضارع»","url":""}]},{"id":"s7-860","number":860,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما الفرق بين ﴿ما كان يصنع فرعون وقومه﴾ و﴿ما كانوا يعرشون﴾؟","answer":"الصنع أعم، فيشمل تدبيرهم وأعمالهم ومنشآتهم؛ والعروش أخص بما كانوا يرفعونه من أبنية أو سقوف وكروم، فجمع النص العام والخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص385، تحت «شرح المفردات: ﴿يصنع﴾ و﴿يعرشون﴾»","url":""}]},{"id":"s7-861","number":861,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاوزنا ببني إسرائيل البحر﴾، فعُدّي التجاوز بالباء؟","answer":"تتضمن الباء معنى التعدية، أي جعلناهم يجاوزون البحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص401–402، تحت «دلالة الباء، في قوله: ﴿ببني إسرائيل﴾»","url":""}]},{"id":"s7-862","number":862,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما وجه استئناف خبر العبور بالواو في ﴿وجاوزنا ببني إسرائيل البحر﴾؟","answer":"وصلت الواو هذا الخبر بأصل القصة التي بدأت ببعثة موسى، لأن القرآن يقص جوانب منها في مقاطع متعددة. فانتقل من خبر هلاك فرعون وإيراث المستضعفين إلى ما أحدثه بنو إسرائيل بعد النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص403، تحت «سر العطف على أول القصة»","url":""}]},{"id":"s7-863","number":863,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتوا على قوم﴾ لا «فمروا بقوم»؟","answer":"ضمن الإتيان معنى المرور، فعدي بعلى التي تفيد استعلاء مجازيًا. فقد وجدوا القوم في طريقهم ولم يقصدوا الإقامة عندهم؛ فالتعبير يصور ما صادفوه في مسيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص403–404، تحت «دلالة تعدية فعل الإتيان بعلى، على طريق التضمين»","url":""}]},{"id":"s7-864","number":864,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما دلالة تنكير ﴿أصنام﴾ في وصف القوم؟","answer":"أبهم التنكير هذه الأصنام وحقر شأنها، ثم جاء وصفها بأنها ﴿لهم﴾ ليزيد التهكم باتخاذ القوم مصنوعات يملكونها آلهة يعبدونها. فالتنكير يبرز ضآلة معبوداتهم في مقام الإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص404، تحت «نكتة تنكير لفظ ﴿أصنام﴾»","url":""}]},{"id":"s7-865","number":865,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿يعكفون على أصنام لهم﴾؟","answer":"العكوف هو الملازمة مع الإقبال والتعظيم؛ فصورت الآية دوام إقامتهم على أصنام يعبدونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص404، تحت «سر التعبير بالمضارع ﴿يعكفون﴾»","url":""}]},{"id":"s7-866","number":866,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"لماذا عُدّي العكوف بـ﴿على﴾ لا بـ«عند»؟","answer":"عدي العكوف بـ﴿على﴾ لما فيه من الملازمة والإقبال والمواظبة على الشيء، وهي أبلغ من مجرد الكون عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص404، تحت «تعدية فعل العكوف بعلى على طريق التضمين»","url":""}]},{"id":"s7-867","number":867,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"لماذا وصف الأصنام بأنها ﴿لهم﴾؟","answer":"﴿لهم﴾ تكشف اختصاصهم بهذه الأصنام واتخاذهم إياها لأنفسهم، مع أنها مصنوعات مملوكة لهم لا آلهة تملكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص404، تحت «سر وصف الأصنام بأنها ﴿لهم﴾»","url":""}]},{"id":"s7-868","number":868,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"كيف طلب بنو إسرائيل إلهًا بعد أن جاوزوا البحر ورأوا هلاك فرعون؟","answer":"ولذلك واجههم موسى بالإنكار والتوبيخ على هذا الطلب بعد ما رأوه من آيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص407، تحت «سر الوصف بالجهل المطلق، على طريق التوكيد بإن»","url":""}]},{"id":"s7-869","number":869,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما دلالة طلبهم: ﴿اجعل لنا إلهًا﴾، وهل يُجعل الإله؟","answer":"طلبهم ﴿اجعل﴾ لا يعني إمكان خلق إله حق، بل طلبوا أن يعين لهم معبودًا محسوسًا يتخذونه إلهًا كما اتخذ أولئك أصنامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص405–406، تحت «بلاغة التشبيه في قوله: ﴿كما لهم آلهة﴾»","url":""}]},{"id":"s7-870","number":870,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ قولهم: ﴿كما لهم آلهة﴾ بالجمع بعد طلب إله واحد؟","answer":"طلبوا معبودًا واحدًا لجماعتهم، وشبهوا حالهم بقوم لهم أصنام متعددة؛ فالمقصود مماثلتهم في أصل اتخاذ المعبود المحسوس لا في العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص405–406، تحت «بلاغة التشبيه في قوله: ﴿كما لهم آلهة﴾»","url":""}]},{"id":"s7-871","number":871,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما مناسبة جواب موسى: ﴿إنكم قوم تجهلون﴾؟","answer":"جاء الرد مؤكدًا بـ﴿إن﴾، ووصفهم بأنهم ﴿قوم تجهلون﴾ لأن طلبهم تعلق بأصل التوحيد بعد مشاهدة أعظم آيات النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص407–408، تحت «فائدة التعبير بالجملة الاسمية ﴿إنكم قوم تجهلون﴾»","url":""}]},{"id":"s7-872","number":872,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿تجهلون﴾ بالمضارع لا «جاهلون»؟","answer":"يصور المضارع الجهل متجددًا منهم في الحال والاستقبال، ويجعله خلة يظهر أثرها في سلوكهم. ويقوي هذا الإنكار تركيب ﴿قوم تجهلون﴾؛ فلا يدل اختيار المضارع وحده على أن الجهل عارض لا ثبات له.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص406–407، تحت «سر التعبير بالمضارع ﴿تجهلون﴾»","url":""}]},{"id":"s7-873","number":873,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما أثر الانتقال من حكاية ﴿قالوا﴾ إلى مواجهتهم بقوله ﴿إنكم قوم تجهلون﴾؟","answer":"انتقل السرد من الحديث عنهم إلى خطاب موسى المباشر لهم، فبلغ الإنكار أسماعهم معينًا إياهم. وفي هذه المواجهة تقريع على طلبهم، وزجر لهم عن اتباع أهل الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص408، تحت «سر الالتفات من الغيبة إلى الخطاب»","url":""}]},{"id":"s7-874","number":874,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"لماذا بدأ إبطال عبادة الأصنام باسم الإشارة: ﴿إن هؤلاء﴾؟","answer":"اسم الإشارة يحضر أهل الأصنام أمام السامعين كأنهم مشاهدون، ثم يصدر الحكم على حالهم: ما هم فيه إلى هلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص417، تحت «سر التعريف باسم الإشارة، في قوله: ﴿هؤلاء﴾»","url":""}]},{"id":"s7-875","number":875,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿متبر ما هم فيه﴾، وما دلالة «متبر»؟","answer":"﴿متبر﴾ أي مهلك مدمر؛ فالمعنى أن ما هم فيه من دين وعبادة مصيره الزوال والهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص417–418، تحت «التعبير بالاشتقاق المضعف ﴿متبر﴾، على طريق الاستعارة التبعية»","url":""}]},{"id":"s7-876","number":876,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"لماذا جاء ﴿متبر﴾ اسمًا لا فعلًا؟","answer":"اسم المفعول ﴿متبر﴾ يثبت الحكم ويصوره مآلًا محققًا قائمًا، لا فعلًا عارضًا قد يقع أو لا يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص417–418، تحت «بلاغة التعبير بالتتبير، على صيغة التفعيل»","url":""}]},{"id":"s7-877","number":877,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿ما هم فيه﴾ بدل «عبادتهم»؟","answer":"﴿ما هم فيه﴾ يصور العبادة الباطلة كظرف أحاط بهم واستغرق حياتهم، وهو أوسع من تسمية فعل العبادة وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص419، تحت «بلاغة التعريف بالموصول ﴿ما﴾»","url":""}]},{"id":"s7-878","number":878,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿وباطل ما كانوا يعملون﴾ بعد ﴿متبر ما هم فيه﴾؟","answer":"الأول يحكم على المعبودات والحال التي لابسوها بالهلاك، والثاني يحكم على أعمالهم نفسها بالبطلان؛ فشمل فساد المعبود والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص419–420، تحت «بلاغة التعبير بالجملة الاسمية ﴿وباطل ما كانوا يعملون﴾»","url":""}]},{"id":"s7-880","number":880,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"ما الفرق بين ﴿متبر ما هم فيه﴾ و﴿باطل ما كانوا يعملون﴾؟","answer":"﴿متبر﴾ يبين مآل ما هم فيه إلى التدمير، و﴿باطل﴾ يبين أن أعمالهم لا حقيقة نافعة لها ولا ثواب؛ فالأول للعاقبة والثاني للقيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص417–418، تحت «بلاغة التعبير بالتتبير، على صيغة التفعيل»","url":""}]},{"id":"s7-881","number":881,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"ما دلالة الاستفهام في قول موسى: ﴿أغير الله أبغيكم إلهًا﴾؟","answer":"الاستفهام إنكاري تعجبي: أيستبدل موسى بالله إلهًا آخر يطلبه لهم؟ وفيه إظهار فظاعة طلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص426–427، تحت «غرض الاستفهام في الآية الكريمة»","url":""}]},{"id":"s7-882","number":882,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"لماذا قدّم ﴿غير الله﴾ على الفعل؟","answer":"قدم ﴿غير الله﴾ لأنه محور الإنكار؛ فالمنكر أولًا أن يكون المطلوب أحدًا غير الله، أيًا كان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص427–428، تحت «بلاغة تقديم المفعول، وإنكاره بالهمزة»","url":""}]},{"id":"s7-883","number":883,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿أبغيكم﴾ لا «أجعل لكم» كما طلبوا؟","answer":"﴿أبغيكم﴾ تعني أطلب لكم وألتمس، وفيها رد طلبهم بصورته: أتطلبون مني أن أبحث لكم عن معبود غير الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص423–424، تحت «شرح المفردات: ﴿أبغيكم﴾»","url":""}]},{"id":"s7-884","number":884,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"ما أثر مقابلة ﴿غير﴾ باسم الجلالة في ﴿أغير الله أبغيكم إلهًا﴾؟","answer":"﴿غير﴾ من أشد الأسماء إبهامًا، واسم الجلالة أعرف الأعلام وأخصها بالمعبود الحق. فتقابل الصيغتان يقرر إنكار طلب أي معبود آخر، مهما تنوعت صورته أو عظم في ظن طالبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص426، تحت «نكتة الإيغال في التنكير والتعريف»","url":""}]},{"id":"s7-885","number":885,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"لماذا عقب بقوله: ﴿وهو فضلكم على العالمين﴾؟","answer":"ذكّرهم بتفضيل الله لهم بالنعم والنجاة ليقيم الحجة من واقع إحسانه إليهم: فكيف يطلبون غير المنعم إلهًا؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص428–429، تحت «معنى اختصاصهم المعنوي بالتفضيل في ﴿فضلكم﴾»","url":""}]},{"id":"s7-886","number":886,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿فضلكم﴾ بالماضي؟","answer":"الماضي في ﴿فضلكم﴾ يقرر نعمة تحققت وشاهدوها، فتقوم بها الحجة عليهم ولا تبقى وعدًا منتظرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص429–430، تحت «بلاغة تقديم الضمير هو، والتخصيص بالفعل الماضي»","url":""}]},{"id":"s7-887","number":887,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"كيف يُفهم قوله تعالى: ﴿على العالمين﴾ مع وجود أمم أفضل منهم؟","answer":"المراد عالمو زمانهم، أو التفضيل بما خصوا به من النجاة والآيات في ذلك المقام، لا أنهم أفضل من كل أمة في كل زمان وعلى كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص430–431، تحت «نكتة اختيار لفظ ﴿العالمين﴾، في السياق»","url":""}]},{"id":"s7-888","number":888,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا انتقل الخطاب إلى ﴿وإذ أنجيناكم من آل فرعون﴾؟","answer":"ليقابل قبح الشرك بعظمة النعمة التي تلقوها من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص434–435، تحت «بلاغة تكرار الآية، والتذكير بالعذاب دون النعمة»","url":""}]},{"id":"s7-889","number":889,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿أنجيناكم﴾ هنا، وفي البقرة: ﴿نجيناكم﴾؟","answer":"فيربط أنجيناكم في الأعراف بشدة المعاناة والحاجة إلى سرعة الخلاص، بينما تأتي نجيناكم في البقرة ضمن تذكيرهم بنعم امتدت في قصتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص436–437، تحت «نكتة العدول من لفظ نجيناكم إلى ﴿أنجيناكم﴾»","url":""}]},{"id":"s7-890","number":890,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"كيف يوجه خطاب ﴿أنجيناكم﴾ إذا حمل على أبناء الذين نجوا من فرعون؟","answer":"يعد الإنجاء نعمة على الأبناء أيضًا؛ فلو أهلك الآباء لم يوجد نسلهم. وعلى هذا التوجيه يكون إسناد نجاة الآباء إلى المخاطبين من المجاز العقلي، لأن صلاح حال الأسلاف يعود أثره على أخلافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص436، تحت «سر تعلق الإنجاء بالمخاطبين، ودلالة المجاز العقلي»","url":""}]},{"id":"s7-891","number":891,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]},{"surah":14,"verses":[6]}],"verseLabel":"الأعراف: 141؛ إبراهيم: 6","question":"ما سر التعبير بـ﴿آل فرعون﴾ بدل الاقتصار على فرعون؟","answer":"لأن الآل تشمل خاصة فرعون وأتباعه وأعوانه القائمين بأمره، وهم الذين باشروا استضعاف بني إسرائيل؛ فالنجاة كانت من سلطان جماعة ونظام بطش، لا من فعل شخص واحد فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص555، تحت «سر اختيار ﴿آل﴾»","url":""}]},{"id":"s7-892","number":892,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿يسومونكم سوء العذاب﴾، وما صورة «السوم»؟","answer":"السوم إلزام الشيء وإدامته؛ فصورت العبارة آل فرعون يذيقونهم العذاب مرارًا ويكلفونهم صنوفه بلا انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص441–442، تحت «وجه التضمين في قوله: ﴿يسومونكم﴾»","url":""}]},{"id":"s7-893","number":893,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا أضيف ﴿سوء﴾ إلى ﴿العذاب﴾؟","answer":"الإضافة في ﴿سوء العذاب﴾ تبين أنه أشد العذاب وأقبحه، ثم فصلت صورته بقتل الأبناء واستحياء النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص443، تحت «بلاغة التعبير بالسوء، على صيغة التنكير والمصدرية»","url":""}]},{"id":"s7-894","number":894,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا قدّم ﴿يقتلون أبناءكم﴾ على ﴿ويستحيون نساءكم﴾؟","answer":"قدم قتل الأبناء لأنه أفجع وأشد إهلاكًا للجماعة، ثم ذكر إبقاء النساء للخدمة والاستذلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص445، تحت «سر تقديم ﴿يقتلون﴾ على ﴿ويستحيون﴾، وتخصيصه بالذكور»","url":""}]},{"id":"s7-895","number":895,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"ما الفرق بين ﴿يقتلون﴾ في الأعراف و﴿يذبحون﴾ في البقرة؟","answer":"القتل أعم من الذبح ويصور إزهاق الأرواح، أما ﴿يذبحون﴾ فتفصل هيئة القتل البشعة؛ فكل موضع يبرز جهة من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص452، تحت «يذبح و يقتل»","url":""}]},{"id":"s7-896","number":896,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لم جاءت ﴿يقتلون﴾ في الأعراف و﴿يذبحون﴾ في البقرة بلا واو، وجاءت ﴿ويذبحون﴾ في إبراهيم بالواو؟","answer":"في البقرة والأعراف جاءت جملة القتل أو التذبيح بيانًا لسوء العذاب وتفسيرًا له، فناسب الفصل. وفي إبراهيم عُطفت بالواو لأن موسى كان في مقام تعداد نعم الله على قومه، فاستحضر التذبيح عذابًا مخصوصًا مستقلًا ضمن صنوف العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص557–558، تحت «توجيه المتشابه اللفظي في الفصل والوصل»","url":""}]},{"id":"s7-897","number":897,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا عبّر بالمضارع ﴿يقتلون... ويستحيون﴾ عن أحداث ماضية؟","answer":"المضارع يستحضر مشهد القتل والاستحياء ويصور تكرره واستمراره، حتى كأن العذاب يقع أمام السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص448–449، تحت «سر العدول عن الماضي إلى المضارع، في فعلي القتل والاستحياء»","url":""}]},{"id":"s7-898","number":898,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"إلى ماذا يشير قوله تعالى: ﴿ذلكم﴾؟","answer":"يشير إلى ما سبق من العذاب والإنجاء، فيجمع المشهدين ليكونا موضع اعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص449–450، تحت «دلالة التعبير باسم الإشارة، في قوله: ﴿ذلكم﴾»","url":""}]},{"id":"s7-1617","number":1617,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا اختير لفظ ﴿البلاء﴾ في هذا الموضع؟","answer":"لأن البلاء يحتمل المحنة والاختبار والنعمة؛ فتجتمع فيه شدة ما وقع وعبرة النجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص450، تحت «بلاغة اختيار لفظ البلاء»","url":""}]},{"id":"s7-1618","number":1618,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"ما أثر تنكير ﴿بلاء﴾ و﴿عظيم﴾؟","answer":"يفخم التنكير شأن البلاء ويهول أثره، ويبين أنه عظيم صادر من ربهم ليستوجب الاعتبار والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص450–451، تحت «بلاغة تنكير لفظي ﴿بلاء﴾ و﴿عظيم﴾»","url":""}]},{"id":"s7-899","number":899,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"إلى ماذا يشير ﴿ذلكم﴾: إلى العذاب أم إلى الإنجاء؟","answer":"يجوز أن تعود الإشارة إلى سوء العذاب المذكور، وأن تشمل مجموع ما سبق من العذاب والإنجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص449–450، تحت «دلالة التعبير باسم الإشارة، في قوله: ﴿ذلكم﴾»","url":""}]},{"id":"s7-900","number":900,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا وصف البلاء بأنه ﴿من ربكم﴾؟","answer":"إضافة البلاء إلى ﴿ربكم﴾ تذكر بأن ما جرى صادر عن تدبير المربي: ابتلى بالشدة وأنعم بالنجاة، ليستوجب الصبر والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص450–451، تحت «دلالة التعبير بلفظ ﴿ربكم﴾، مضافًا إلى المخاطب»","url":""}]},{"id":"s7-901","number":901,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿وواعدنا موسى﴾ بصيغة المفاعلة مع أن ابتداء الوعد من الله؟","answer":"المواعدة تفيد أن الله وعد موسى الحضور والتكليم، وموسى قابل الوعد بالحضور والوفاء؛ فصيغت المفاعلة لاشتراك الطرفين في متعلق الموعد، وإن كان ابتداء الوعد من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص455–456، تحت «نكتة التعبير بلفظ ﴿وواعدنا﴾»","url":""}]},{"id":"s7-902","number":902,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لم أجملت الأربعون ليلة في البقرة، وفصلت إلى ثلاثين وعشر في الأعراف؟","answer":"وردت قصة الأعراف مفصلة في شأن موسى وميقاته، فناسبها بيان الثلاثين وإتمامها بعشر وما تعلق بغيابه واستخلاف هارون. أما البقرة فجاءت الأربعون مجملة في سياق تذكير بني إسرائيل بالنعم؛ فلكل من الإجمال والتفصيل موقعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص462–463، تحت «نكتة العدول من الإجمال إلى التفصيل»","url":""}]},{"id":"s7-903","number":903,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا بدأ الموعد بـ﴿ثلاثين ليلة﴾ ثم قال: ﴿وأتممناها بعشر﴾ بدل أن يقول: أربعين ليلة؟","answer":"ذُكرت الثلاثون أولًا ثم الزيادة بالعشر لإظهار أن الموعد مر بمرحلتين، وأن العشر إتمام لما سبق، وفي ذلك تمهيد لما وقع في مدة غياب موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص457–458، تحت «سر التعبير بلفظ الإتمام مع التفريق»","url":""}]},{"id":"s7-904","number":904,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا عُبّر بالليالي لا بالأيام؟","answer":"عُبر بالليالي لأنها مبدأ حساب الشهور عند العرب، ولأن الخلوة والمناجاة ألصق بالليل؛ والمراد الليالي بأيامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص464–465، تحت «سر التعبير بالليالي دون الأيام»","url":""}]},{"id":"s7-905","number":905,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿وأتممناها بعشر﴾ ولم يكرر «ليال»؟","answer":"حذف تمييز ﴿عشر﴾ لدلالة ﴿ثلاثين ليلة﴾ عليه، فاستغنى عن تكراره إيجازًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص462، تحت «سر حذف تمييز لفظ ﴿بعشر﴾ في السياق»","url":""}]},{"id":"s7-906","number":906,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿فتم ميقات ربه أربعين ليلة﴾ بعد أن صار المجموع معلومًا؟","answer":"صرح بالمجموع توكيدًا لتمام الموعد ورفعًا لاحتمال أن تكون العشر داخلة في الثلاثين؛ فثبت أن الميقات أربعون ليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص459–460، تحت «سر التكرار بجملة إتمام الأربعين»","url":""}]},{"id":"s7-907","number":907,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا أضاف الميقات إلى ﴿ربه﴾؟","answer":"إضافة الميقات إلى ﴿ربه﴾ تشريف له وبيان أن تحديده صادر عن الرب، وفي الإضافة معنى العناية بموسى وتربيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص464، تحت «نكتة العدول إلى التصريح بلفظ ﴿ربه﴾، وإضافة موسى إليه»","url":""}]},{"id":"s7-908","number":908,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا عاد من ضمير التعظيم في ﴿واعدنا... أتممنا﴾ إلى الغيبة ﴿ربه﴾؟","answer":"عدل عن ضمير المتكلم إلى ﴿ربه﴾ لإظهار ربوبية الله لموسى؛ فهو مصلحه والناظر في أمره ومالكه والمتصرف فيه. فتخدم الإضافة مقام تربيته وإصلاحه وتهيئته لما سيلقاه في الميقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص464، تحت «نكتة العدول إلى التصريح بلفظ ﴿ربه﴾، وإضافة موسى إليه»","url":""}]},{"id":"s7-909","number":909,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما دلالة طلب موسى من هارون: ﴿اخلفني في قومي﴾ مع أنه نبي؟","answer":"فالخلافة هنا في سياسة القوم وحفظهم، ولا تنافي نبوة هارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص468–469، تحت «علة استخلاف هارون وعدم اصطحابه»","url":""}]},{"id":"s7-910","number":910,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لم أضاف موسى القوم إلى نفسه في ﴿اخلفني في قومي﴾؟","answer":"تؤكد الإضافة صلته بهم ومكانته عندهم، وأنه يريد لهم الخير ويحفظ مصلحتهم حين يغيب. وفيها تقوية لوصيته إلى هارون وتذكير للقوم بمراعاة عهد موسى وطاعة من استخلفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص468–469، تحت «نكتة تأكيد موسى نسبة قومه إليه ﴿قومي﴾»","url":""}]},{"id":"s7-911","number":911,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا أمر هارون بـ﴿وأصلح﴾ مع صلاحه ونبوته؟","answer":"الأمر بالإصلاح طلب للاستمرار عليه وبذل الجهد في إصلاح ما قد يطرأ أثناء غيبة موسى، لا اتهام لهارون بالفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص465–466، تحت «وجه التعبير عن الإصلاح بالأمر ﴿وأصلح﴾، مع إضمار مفعوله»","url":""}]},{"id":"s7-912","number":912,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تتبع سبيل المفسدين﴾، دون أن يقال: ولا تفسد؟","answer":"النهي عن اتباع سبيل المفسدين أوسع من قول «لا تفسد».","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص466–467، تحت «دلالة النهي، في قوله: ﴿ولا تتبع سبيل المفسدين﴾»","url":""}]},{"id":"s7-913","number":913,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما وجه البلاغة في التعبير بالاتباع، على طريق الاستعارة؟","answer":"استعير الطريق للمنهج الذي يؤدي إلى مشاركة المفسدين أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص467، تحت «بلاغة التعبير بالاتباع، على طريق الاستعارة»","url":""}]},{"id":"s7-1619","number":1619,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما دلالة تعريف النكرة بالإضافة، والتعبير باسم الفاعل مجموعًا؟","answer":"ويصور اسم الفاعل ﴿المفسدين﴾ الصفة راسخة في أصحاب هذا المنهج.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص470، تحت «دلالة تعريف النكرة بالإضافة، والتعبير باسم الفاعل مجموعًا»","url":""}]},{"id":"s7-914","number":914,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"كيف يوجه تعلق المجيء بالميقات في ﴿جاء موسى لميقاتنا﴾؟","answer":"يذكر المصدر أن اللام للاختصاص، أي جاء في الميقات المعين له دون تأخر، ويجوز أن تكون للأجل، أي جاء لأجل الموعد وما تضمنه من المناجاة. فليس لازمًا أن يفسر التركيب بمجيء إلى الزمن نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص477، تحت «نكتة توجيه معنى اللام، في قوله: ﴿لميقاتنا﴾»","url":""}]},{"id":"s7-915","number":915,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا أضاف الميقات إلى الله: ﴿لميقاتنا﴾ بعد قوله ﴿ميقات ربه﴾؟","answer":"في ﴿ميقات ربه﴾ إبراز لعناية الرب بموسى، وفي ﴿لميقاتنا﴾ تشريف الموعد بإضافته إلى ضمير العظمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص464، تحت «نكتة العدول إلى التصريح بلفظ ﴿ربه﴾، وإضافة موسى إليه»","url":""}]},{"id":"s7-916","number":916,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما أثر اقتران التكليم بمجيء موسى في ﴿ولما جاء موسى لميقاتنا وكلمه ربه﴾؟","answer":"اجتمع المجيء والتكليم في تمهيد طلب موسى الرؤية؛ فلما أكرمه الله بالكلام ازداد شوقه إلى المعرفة والقرب فسأل أن يراه. فارتبط الطلب بما ناله في ذلك المقام من تشريف التكليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص478–479، تحت «سر جعل ﴿وكلمه ربه﴾ شرطًا للأداة ﴿ولما﴾»","url":""}]},{"id":"s7-917","number":917,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا أظهر ﴿ربه﴾ بدل الضمير: «وكلمناه»؟","answer":"إظهار ﴿ربه﴾ بدل «كلمناه» يستحضر وصف الربوبية والعناية في أشرف مقام، ويجعل المتكلم معلومًا على وجه التعظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص479، تحت «نكتة العدول عن الإضمار إلى الإظهار»","url":""}]},{"id":"s7-918","number":918,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما دلالة طلب موسى: ﴿رب أرني أنظر إليك﴾، فجمع بين الإراءة والنظر؟","answer":"طلب بقوله ﴿أرني﴾ أن يمكنه الله من رؤيته، وحذف المفعول الثاني لدلالة ﴿إليك﴾ عليه.؛ ثم بين ﴿أنظر إليك﴾ ما يرجوه من تلك الإراءة، فيكشف الجمع بينهما شدة شوقه إلى الرؤية بعد نعمة التكليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص479–480، تحت «دلالة جملة ﴿رب أرني أنظر إليك﴾»","url":""}]},{"id":"s7-919","number":919,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لم حذف حرف النداء «يا» فقال موسى: ﴿رب أرني﴾؟","answer":"يدل حذف حرف النداء على القرب في المناجاة، ويجمع لفظ ﴿رب﴾ معاني الإحسان والتربية والرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص479–480، تحت «بلاغة الحذف في ﴿رب أرني أنظر﴾»","url":""}]},{"id":"s7-920","number":920,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا أجابه الله بـ﴿لن تراني﴾ لا «لا تراني»؟","answer":"﴿لن﴾ تنفي حصول الرؤية في الحال الدنيوية التي عليها موسى نفيًا مؤكدًا، ولا تدل بذاتها على امتناع الرؤية أبدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص481–482، تحت «دلالة أداة النصب ﴿لن﴾»","url":""}]},{"id":"s7-921","number":921,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا علق الرؤية على استقرار الجبل: ﴿فإن استقر مكانه فسوف تراني﴾؟","answer":"فلما عجز الجبل عن الثبات ظهر بطريق المشاهدة أن بنية موسى البشرية لا تحتملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص483–484، تحت «وجه تعليق الشرط، بالحرف المشبه بالفعل إن»","url":""}]},{"id":"s7-922","number":922,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا اختير الجبل مقياسًا لاحتمال التجلي؟","answer":"اختير الجبل لرسوخه وصلابته وعظم جرمه؛ فإذا لم يثبت هو للتجلي فالإنسان أضعف عن احتماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص482–483، تحت «بلاغة الاستدراك بلفظ ﴿ولكن﴾»","url":""}]},{"id":"s7-923","number":923,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما دلالة ﴿فسوف تراني﴾ في سياق تعليق الرؤية باستقرار الجبل؟","answer":"تأتي في جواب الشرط، ويجعل المصدر التعبير بالمستقبل البعيد ملائمًا للاستبعاد في هذا المقام. فاختبار ثبات الجبل يكشف عجز القوة البشرية عن احتمال ذلك التجلي، ولا يفسر سوف هنا بمجرد إعطاء مهلة للنظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص483–484، تحت «نكتة التعبير بأسلوب التعريض»","url":""}]},{"id":"s7-924","number":924,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما تجلى ربه للجبل﴾، وعُدي التجلي باللام؟","answer":"التجلي الظهور والانكشاف، واللام في ﴿للجبل﴾ توجه التجلي إليه وتخصه به، فوقع أثره عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص484–485، تحت «سر التعبير بصيغة التجلي، دون غيره»","url":""}]},{"id":"s7-925","number":925,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿جعله دكًا﴾ لا «فدكّه»؟","answer":"﴿جعله دكًا﴾ يدل على تحويل الجبل كله إلى هيئة الدك والتسوية، لا مجرد وقوع فعل الدق عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص485، تحت «نكتة الإخبار عن الجبل بلفظ الدك»","url":""}]},{"id":"s7-926","number":926,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما أثر الإخبار عن الجبل بالمصدر في ﴿جعله دكًا﴾؟","answer":"أخبر عنه بالمصدر مبالغة في شدة ما أصابه من الهدم وتفرق الأجزاء؛ فالمعنى جعله مدكوكًا. وتقابل قوة الجبل وثباته مع هذا التحول يزيد المشهد تهويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص485، تحت «نكتة الإخبار عن الجبل بلفظ الدك»","url":""}]},{"id":"s7-927","number":927,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿وخر موسى صعقًا﴾ لا «سقط»؟","answer":"الخرور سقوط تقترن به جلبة؛ وأصل اللفظ متصل بصوت الخرير. فيصور سقوط موسى وصعقه في ذلك المشهد المهيب، ويزيد الإحساس بهول ما وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص486، تحت «إيثار التعبير بالفعل: ﴿وخر﴾»","url":""}]},{"id":"s7-928","number":928,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما دلالة الصفة المشبهة ﴿صَعِقًا﴾ في ﴿وخر موسى صعقًا﴾؟","answer":"﴿صَعِقًا﴾ صفة مشبهة من الصعق، وليست مصدرًا هنا. تصور ما استولى عليه من الغشي وشدة التأثر بهول المشهد، وتؤكد تمكن تلك الحالة منه حين خر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص486، تحت «سر التعبير بالماضي المشدد، والصفة المشبهة»","url":""}]},{"id":"s7-929","number":929,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أفاق﴾ لا «فلما استيقظ»؟","answer":"الإفاقة رجوع العقل والحس بعد غشي أو صعق، أما الاستيقاظ فرجوع من النوم؛ فالإفاقة هي المطابقة لما أصابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص486–487، تحت «دلالة إظهار الحرف، وحذفه في السياق»","url":""}]},{"id":"s7-930","number":930,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا بدأ موسى بعد الإفاقة بالتسبيح: ﴿سبحانك﴾؟","answer":"بدأ بالتسبيح تنزيهًا لله عن أن تحيط به الأبصار، واعترافًا بعظمته بعد أن شاهد أثر التجلي في الجبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص487–488، تحت «إنشاء الثناء على الله، والتنزيه عما لا يليق به، ديدن النبيئين»","url":""}]},{"id":"s7-931","number":931,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿تبت إليك﴾، وممَّ تاب موسى؟","answer":"تاب من الإقدام على سؤال الرؤية في الدنيا قبل الإذن، ورجع إلى الوقوف عند ما بينه الله له، لا من شك في ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص488، تحت «بلاغة التعبير عن التوبة بالفعل الماضي»","url":""}]},{"id":"s7-932","number":932,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا ختم بقوله: ﴿وأنا أول المؤمنين﴾؟","answer":"أطلق الأول على المبادر إلى الإيمان؛ فالأولية هنا كناية عن قوة إيمانه وشدة يقينه حتى كأنه سبق غيره إليه. وفي ختام الموقف بهذا الإقرار إعلان للتسليم والثبات على الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص488، تحت «دلالة التعبير عن أولية الإيمان على طريق المجاز كناية»","url":""}]},{"id":"s7-933","number":933,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا خاطبه الله باسمه: ﴿يا موسى﴾ بعد الصعق والإفاقة؟","answer":"النداء باسمه تلطف وتشريف بعد الإفاقة، ورد له من هول الصعق إلى خطاب الاصطفاء والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص494، تحت «بلاغة المجاز المرسل في النداء»","url":""}]},{"id":"s7-934","number":934,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا أكد الخبر بـ﴿إني اصطفيتك﴾؟","answer":"التوكيد هنا للاعتناء بشأن الخبر وإثارة اهتمام موسى بما اختصه الله به؛ إذ لا إنكار منه للاصطفاء. ويلائم هذا الاهتمام ما راعه في مشهد التجلي، فيتلقى خبر النعمة والتشريف مؤكدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص494–495، تحت «توجيه التوكيد بالحرف ﴿إن﴾»","url":""}]},{"id":"s7-935","number":935,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿اصطفيتك﴾ لا «اخترتك»؟","answer":"الاصطفاء اختيار مع تنقية وتفضيل، فهو أخص من مطلق الاختيار، ويلائم الرسالة والتكليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–492، تحت «شرح المفردات: ﴿اصطفيتك﴾»","url":""}]},{"id":"s7-936","number":936,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا عُدّي الاصطفاء بـ﴿على الناس﴾؟","answer":"﴿على الناس﴾ تبين رفعة منزلته بينهم بما خص به، فالاصطفاء تفضيل لا مجرد اختيار لمهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص495–496، تحت «توجيه تعدية الاصطفاء بحرف الجر ﴿على﴾»","url":""}]},{"id":"s7-937","number":937,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"هل المراد بـ﴿على الناس﴾ جميع البشر أم أهل زمان موسى؟","answer":"يذكر المصدر أكثر من توجيه: أن المراد قومه الذين أرسل إليهم، أو أهل زمانه، ويجوز حمله على العموم بالنظر إلى اجتماع الرسالة والتكليم له. فلا يلزم من الاصطفاء بهذه الخصيصة تفضيله على كل نبي في كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص496، تحت «دلالة العموم مع إرادة الخصوص، في لفظ ﴿الناس﴾»","url":""}]},{"id":"s7-938","number":938,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"ما وجه الجمع في ﴿برسالاتي﴾، ووجه قراءة الإفراد «برسالتي»؟","answer":"الجمع يلائم تعدد ما أرسل به من العقائد والأحكام والإرشادات، وتعدد الإبلاغ في أوقاته. والإفراد يجري على معنى المصدر أو يجعل الرسالة بمجموعها رسالة واحدة؛ فتلتقي القراءتان في أصل المعنى مع اختلاف الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص497–498، تحت «توجيه قراءتي الجمع والإفراد، للفظ ﴿برسالاتي﴾»","url":""}]},{"id":"s7-939","number":939,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا قدّم ﴿برسالاتي﴾ على ﴿بكلامي﴾؟","answer":"يذكر المصدر أن الرسالة أسبق في الزمان، ويذكر وجهًا آخر هو الانتقال من شريف إلى أشرف، فيأتي التكليم زيادة في التشريف بعد الاصطفاء بالرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص497، تحت «نكتة تقديم الرسالات على الكلام»","url":""}]},{"id":"s7-940","number":940,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لم كررت الباء في ﴿برسالاتي وبكلامي﴾؟","answer":"إعادة الباء تنبه إلى أن الاصطفاء بالتكليم منقبة متميزة عن الاصطفاء بالرسالات، وتبرز خصوصية تكليم الله لموسى من غير واسطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص498، تحت «سر تكرار حرف الجر ﴿الباء﴾ في لفظ ﴿وبكلامي﴾»","url":""}]},{"id":"s7-941","number":941,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا فرّع على الاصطفاء قوله: ﴿فخذ ما آتيتك﴾؟","answer":"الفاء تجعل أخذ العطاء والشكر نتيجة عملية للاصطفاء؛ فمن اختير للرسالة لزمه قبولها والقيام بحقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص501، تحت «جمال الإجمال والتفريع في الآية»","url":""}]},{"id":"s7-942","number":942,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿ما آتيتك﴾ ولم يحدد المأخوذ؟","answer":"﴿ما آتيتك﴾ تعم ما وهبه الله من الرسالات والكلام والألواح وسائر النعم، فلم تقيده بشيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص499–500، تحت «بلاغة التعبير عن الإيتاء، بين المجاز والحقيقة»","url":""}]},{"id":"s7-943","number":943,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿وكن من الشاكرين﴾ لا «واشكر»؟","answer":"﴿كن من الشاكرين﴾ تطلب ثباته في جماعة المتصفين بالشكر ودوام الصفة، لا فعل شكر عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص498–499، تحت «بلاغة التعبير بفعل الأمر ﴿وكن﴾»","url":""}]},{"id":"s7-944","number":944,"surah":7,"verses":[144,145],"references":[{"surah":7,"verses":[144,145]}],"verseLabel":"الأعراف: 144–145","question":"ما سرّ ذكر القوة في قوله تعالى: ﴿فخذها بقوة﴾، وعدم ذكرها قبلها في ﴿فخذ ما آتيتك﴾؟","answer":"الأولى إجمال في الأخذ وجاءت عقب الإفاقة من الصعق؛ والثانية في الألواح المفصلة وتبليغ القوم والعمل بها، وذلك يحتاج إلى قوة وعزيمة. فناسب الإجمالُ الإجمالَ والتفصيلُ التفصيلَ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص513، تحت «نكتة ذكر القوة مع الأخذ في هذه الآية»","url":""}]},{"id":"s7-945","number":945,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما أثر الانتقال من ﴿إني اصطفيتك﴾ إلى ضمير التعظيم في ﴿وكتبنا﴾؟","answer":"يلائم الإفراد في خطاب الاصطفاء مقام القرب والتأنيس، ثم يأتي ضمير التعظيم عند كتابة الألواح لما فيها من عظمة الشرائع والأحكام. فيناسب كل ضمير المقام الذي ورد فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص507، تحت «نكتة الالتفات إلى ضمير التعظيم، في ﴿وكتبنا﴾»","url":""}]},{"id":"s7-946","number":946,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما دلالة إسناد كتابة الألواح إلى الله في ﴿وكتبنا له﴾؟","answer":"تدل الإضافة على تشريف المكتوب وكونه بأمر الله وتقديره؛ فهو وحي محض لا صنع لفكر إنسان فيه ولا كسب لبشر من عند نفسه. ويقرر الماضي تحقق الكتابة ووقوع الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص506–507، تحت «التعبير بالماضي في ﴿وكتبنا﴾، وإضافته إلى نفسه»","url":""}]},{"id":"s7-947","number":947,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما وجه تعريف ﴿الألواح﴾ مع أنها لم تذكر قبل ذلك صراحة؟","answer":"يجوز أن يكون تعريف عهد لما يفهم من العطاء المذكور في ﴿ما آتيتك﴾، فيبين الكلام أن ذلك العطاء كان في ألواح. ويجوز تعريف الجنس؛ أي كتب له في ألواح من هذا الجنس، وقيل إن الألواح معروفة الصفة بينه وبين موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص507–508، تحت «نكتة تعريف ﴿الألواح﴾»","url":""}]},{"id":"s7-948","number":948,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿من كل شيء﴾ مع أن الألواح لم تشمل كل معلومات الوجود؟","answer":"﴿من كل شيء﴾ أي من كل ما يحتاج إليه بنو إسرائيل في دينهم وشريعتهم، لا كل معلومات الوجود؛ فالعموم مقيد بالمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص508، تحت «دلالة العموم في ﴿كل شيء﴾»","url":""}]},{"id":"s7-949","number":949,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"كيف يجمع المكتوب في الألواح بين ﴿موعظة﴾ و﴿تفصيلًا﴾؟","answer":"الموعظة تذكر بما يرغب في الطاعة وينفر من المعصية، والتفصيل يبين الأحكام والحلال والحرام. فجمع العطاء بين تربية النفس وبيان ما تعمل به، ولم يقتصر على جانب منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص508–509، تحت «سر الجمع بين الموعظة والتفصيل»","url":""}]},{"id":"s7-950","number":950,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما سرّ تقديم ﴿موعظة﴾ على ﴿تفصيلًا﴾؟","answer":"قُدمت الموعظة لأنها تصلح القلب وتحمله على القبول، ثم يأتي التفصيل الذي يبين الأحكام والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص509، تحت «فائدة تقديم الموعظة على التفصيل».","url":""}]},{"id":"s7-951","number":951,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"لماذا كرر ﴿كل شيء﴾ في الآية نفسها؟","answer":"الأولى تعم أنواع ما يحتاجون إليه من المكتوبات، والثانية تؤكد تفصيل كل أمر من تلك الأمور وبيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص508–509، تحت «دلالة العموم في ﴿كل شيء﴾»","url":""}]},{"id":"s7-952","number":952,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿فخذها بقوة﴾، وما القوة المطلوبة في أخذ الألواح؟","answer":"الأخذ بقوة هو الجد والعزم في الحفظ والفهم والعمل والتبليغ، لا مجرد حمل الألواح باليد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص510–511، تحت «سر التعبير بلفظ ﴿القوة﴾، دون غيره»","url":""}]},{"id":"s7-953","number":953,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"لماذا انتقل من خطاب موسى إلى قومه: ﴿وأمر قومك يأخذوا بأحسنها﴾؟","answer":"لم يكن العطاء لموسى وحده؛ فانتقل الخطاب من تكليفه بالأخذ إلى تكليفه بتبليغ قومه وحملهم على العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص513–514، تحت «فائدة التفريق بين أخذ موسى عليه السلام وأخذ قومه»","url":""}]},{"id":"s7-954","number":954,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما دلالة جزم ﴿يأخذوا﴾ في ﴿وأمر قومك يأخذوا بأحسنها﴾؟","answer":"جزم الفعل في جواب الأمر ﴿وأمر﴾، وفيه تصوير امتثالهم كأنه حاصل عند صدور أمر موسى إليهم. فيقوي طلب التسليم لأمر الله والعمل بما جاء في الألواح.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص514–515، تحت «فائدة جزم الفعل ﴿يأخذوا﴾»","url":""}]},{"id":"s7-955","number":955,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"كيف يُفهم قوله تعالى: ﴿يأخذوا بأحسنها﴾، وهل في الألواح ما ليس حسنًا؟","answer":"قد تأتي صيغة التفضيل للمبالغة في الحسن، فتكون الألواح كلها حسنة ويطلب الأخذ بجميعها. وقد تحمل على التفاضل بين وجوه العمل، كالعفو مع جواز الاقتصاص؛ فلا يلزم أن في شريعة الله حكمًا قبيحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص515–516، تحت «وجوه التعبير بلفظ ﴿بأحسنها﴾»","url":""}]},{"id":"s7-956","number":956,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿سأريكم دار الفاسقين﴾؟","answer":"الوعيد يجعل مصير الفاسقين منظورًا كأنه دار تُرى، ليعتبروا بعاقبة من خرج عن أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص516–517، تحت «علة التعبير بقوله: ﴿سأريكم دار الفاسقين﴾»","url":""}]},{"id":"s7-957","number":957,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما المراد بـ﴿دار الفاسقين﴾: مصر أم مساكن الهالكين أم جهنم؟","answer":"والسياق يحتمل العبرة بمصير الفاسقين في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص517–518، تحت «علة التعبير بقوله: ﴿سأريكم دار الفاسقين﴾»","url":""}]},{"id":"s7-958","number":958,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿سأصرف عن آياتي﴾، وما معنى صرف المتكبرين عنها؟","answer":"الصرف مجازاة لهم على الاستكبار: يحرمون فهم الآيات والاعتبار بها، أو يصرفون عن إبطالها، لا أنهم يمنعون قسرًا من إيمان أرادوه بإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص524–525، تحت «دلالة الفعل ﴿سأصرف﴾، على حماية الله لآياته وأوليائه»","url":""}]},{"id":"s7-959","number":959,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لم اختلف الضمير في ﴿عن آياتي﴾ و﴿كذبوا بآياتنا﴾ في الآية نفسها؟","answer":"افتتحت الآية بضمير المتكلم المفرد، وختمت بضمير التعظيم. ويبين المصدر مناسبة الافتتاح لما قبله من ﴿سأريكم﴾، ومناسبة الختام لما بعده من ﴿والذين كذبوا بآياتنا﴾؛ فينتظم التعبير مع السياق من جهتيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص534–535، تحت «علة التباين في نسبة الآيات إليه تعالى»","url":""}]},{"id":"s7-960","number":960,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا وُصفوا بـ﴿الذين يتكبرون﴾ بالمضارع؟","answer":"المضارع في ﴿يتكبرون﴾ يصور تجدد تكبرهم واستمراره حتى صار دأبًا يصدهم عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص527، تحت «سر التعبير عن التكبر بصيغة المضارع»","url":""}]},{"id":"s7-961","number":961,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا قُيّد تكبرهم بـ﴿في الأرض﴾؟","answer":"يبرز القيد ضآلة موطنهم؛ فهم متكبرون في بقعة من الأرض ليست شيئًا يعتد به أمام سعة الخلق. فذكر الأرض يشهر تكبرهم ويفضح غرورهم مع صغر شأنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص527–528، تحت «بلاغة الإطناب، بزيادة: ﴿في الأرض﴾»","url":""}]},{"id":"s7-962","number":962,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿بغير الحق﴾، وهل يكون التكبر بحق؟","answer":"القيد كاشف لواقع تكبرهم؛ فالكبرياء الحق لله وحده، ولا يكون تكبر البشر بحق. وقيل للاحتراز من إظهار العزة على أهل الباطل دون بطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص528، تحت «وجوه التعبير بقوله: ﴿بغير الحق﴾»","url":""}]},{"id":"s7-963","number":963,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا كرر الشرط: ﴿وإن يروا كل آية... وإن يروا سبيل الرشد... وإن يروا سبيل الغي﴾؟","answer":"تكرار الشرط يفصل وجوه عنادهم: لا يؤمنون بالدليل مهما ظهر، ويرفضون طريق الرشد، ويتخذون طريق الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص531–532، تحت «سر تكرار ألفاظ ﴿الرؤية﴾، و﴿السبيل﴾، و﴿الاتخاذ﴾»","url":""}]},{"id":"s7-964","number":964,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما دلالة ﴿كل آية﴾ في وصف عناد المتكبرين؟","answer":"يفسر المصدر ﴿كل﴾ هنا بالتكثير واستغراق ما يرونه من الآيات، مبالغة في شدة عنادهم؛ مهما كثرت الدلائل أمامهم لا يؤمنون. فلا يشترط أن يشاهدوا جميع آيات الله التي لا تحصى حتى يصدق الوصف عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص529، تحت «دلالة لفظ ﴿كل﴾ بين المجاز والحقيقة»","url":""}]},{"id":"s7-965","number":965,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما أثر التعبير بالأفعال في ﴿وإن يروا كل آية لا يؤمنوا بها﴾؟","answer":"تصور الجملة الفعلية تجدد جحودهم وعدم إيمانهم بتجدد رؤيتهم الآيات. فعند كل دليل يتكرر منهم الموقف نفسه، ويتصل ذلك بوصفهم بالتكبر قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص528–529، تحت «دلالة الوصل، والتعبير بالجملة الفعلية»","url":""}]},{"id":"s7-966","number":966,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا قوبل ﴿سبيل الرشد﴾ بـ﴿سبيل الغي﴾؟","answer":"الرشد إصابة طريق الحق والصلاح، والغي العدول عنه إلى الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص522–523، تحت «شرح المفردات: ﴿الرشد﴾ و﴿الغي﴾»","url":""}]},{"id":"s7-967","number":967,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى في الطريقين: ﴿لا يتخذوه سبيلًا﴾ و﴿يتخذوه سبيلًا﴾؟","answer":"الاتخاذ فعل قصد واختيار؛ فهم لا يكتفون بترك الرشد بل يرفضون جعله طريقًا، ويعمدون إلى الغي فيجعلونه طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص529–530، تحت «بلاغة الاستعارة، بألفاظ السبيل، والرؤية، والاتخاذ»","url":""}]},{"id":"s7-968","number":968,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا أعيد لفظ ﴿سبيلًا﴾ بعد ﴿سبيل الرشد﴾ و﴿سبيل الغي﴾؟","answer":"أعيد ﴿سبيلًا﴾ لتأكيد أن موقفهم ليس رؤية عابرة للطريقين، بل اتخاذ أحدهما منهجًا ورفض الآخر منهجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص531–532، تحت «سر تكرار ألفاظ ﴿الرؤية﴾، و﴿السبيل﴾، و﴿الاتخاذ﴾»","url":""}]},{"id":"s7-969","number":969,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك بأنهم كذبوا بآياتنا وكانوا عنها غافلين﴾؟","answer":"اسم الإشارة يلخص سبب الصرف واتخاذ الغي: تكذيبهم بآيات الله وإعراضهم عن تدبرها والعمل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص532–533، تحت «سر التعبير بالباء السببية، في: ﴿بأنهم كذبوا﴾»","url":""}]},{"id":"s7-970","number":970,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا جُمِع بين التكذيب والغفلة مرة أخرى بعد الآية 136؟","answer":"في الآية 136 وصف حال فرعون وقومه قبل الإغراق، وهنا وصف سنة المتكبرين وعلة صرفهم عن الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص534، تحت «بلاغة جملتي الإخبار في سياق الآية»","url":""}]},{"id":"s7-971","number":971,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"لماذا أعيد الموصول: ﴿والذين كذبوا بآياتنا ولقاء الآخرة﴾؟","answer":"عدل عن الضمير إلى الموصول وصلته ليظهر أن التكذيب سبب خسران الأعمال وحبوطها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص539–540، تحت «بلاغة العدول، من الإضمار إلى التعريف بالموصولية»","url":""}]},{"id":"s7-972","number":972,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"لماذا عُطف ﴿لقاء الآخرة﴾ على ﴿آياتنا﴾؟","answer":"يضم إلى تكذيب الآيات إنكار يوم الجزاء، وهو المقام الذي يظهر فيه ثواب الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص539–540، تحت «سر إضافة ﴿لقاء﴾ إلى ﴿الآخرة﴾»","url":""}]},{"id":"s7-973","number":973,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"ما سرّ التعبير بقوله تعالى: ﴿لقاء الآخرة﴾ لا «لقاء الله»؟","answer":"﴿لقاء الآخرة﴾ يعم لقاء ما في الدار الآخرة من بعث وحساب وجزاء، فيناسب مقام حبوط الأعمال والجزاء عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص540، تحت «سر إضافة ﴿لقاء﴾ إلى ﴿الآخرة﴾»","url":""}]},{"id":"s7-974","number":974,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"ما سرّ التعبير في قوله تعالى: ﴿حبطت أعمالهم﴾، وصوّر الأعمال كشيء يفسد؟","answer":"شبه ضياع ثواب الأعمال وعدم الانتفاع بها بفساد ما كان ينتظر نفعه. فقد تبدو بعض أعمالهم صالحة في نفسها، ولكن تكذيبهم بآيات الله ولقاء الآخرة يحرمهم ثمرتها عند الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص540–541، تحت «بلاغة التعبير بالفعل ﴿حبط﴾، على طريق التشبيه»","url":""}]},{"id":"s7-975","number":975,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"ما وجه التعبير بإحباط الأعمال دون مطلق إبطالها؟","answer":"الإحباط أخص هنا؛ فهو إبطال عمل البر من الحسنات بالسيئات. فيلائم السياق الذي يبين أن تكذيبهم بآيات الله ولقاء الآخرة أذهب ثواب ما ظنوه من أعمال الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص543، تحت «الإبطال، والإدحاض، والإحباط»","url":""}]},{"id":"s7-976","number":976,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"لماذا ختم باستفهام: ﴿هل يجزون إلا ما كانوا يعملون﴾؟","answer":"الاستفهام إنكاري تقريري يفيد عدل الجزاء وحصره: لا يجزون إلا جنس ما داوموا على عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص541–542، تحت «نكتة الاستفهام بالأداة ﴿هل﴾»","url":""}]},{"id":"s7-978","number":978,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿واتخذ قوم موسى من بعده﴾، دون أن يقال: بنو إسرائيل؟","answer":"إضافتهم إلى موسى تستحضر قبح انقلاب قوم نبيهم في غيبته، وتبرئ موسى من فعلهم؛ وهي أنسب من الاسم النسبي المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص549–550، تحت «دلالة التعبير بالبعدية في قوله: ﴿من بعده﴾»","url":""}]},{"id":"s7-979","number":979,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعده﴾ مع أن غيبة موسى معلومة؟","answer":"﴿من بعده﴾ أي بعد ذهابه إلى الميقات، وفيها تصوير سرعة الفتنة فور غيابه، لا بعد وفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص549–550، تحت «فائدة التعبير بـ﴿من﴾، في قوله: ﴿من بعده﴾»","url":""}]},{"id":"s7-980","number":980,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿من حليهم﴾، وما دلالة نسبة الحلي إليهم؟","answer":"نسب الحلي إليهم لأنها صارت في أيديهم وحيازتهم، وإن كان أصلها مما استعاروه من القبط؛ ومنها صيغ العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص550–551، تحت «سر إضافة الحلي إلى القوم»","url":""}]},{"id":"s7-981","number":981,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"لم قدم ﴿من بعده﴾ و﴿من حليهم﴾ على ﴿عجلًا﴾؟","answer":"ينبه التقديم إلى موضع التعجيب والتوبيخ: سرعة اتخاذ العجل بعد غياب موسى، وإسهامهم بحليهم في صنع ما عبدوه. فيبرز قبح فعلهم قبل ذكر المفعول نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص551، تحت «سر تقديم شبه الجملة على المفعول»","url":""}]},{"id":"s7-982","number":982,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿عجلًا جسدًا﴾ لا «تمثال عجل»؟","answer":"يبين ﴿جسدًا﴾ أن المراد صورة عجل ذات جسم، لا عجل حي يعقل أو يميز، ولا مجرد نقش على سطح. ففي القيد احتراس يحدد حقيقة ما اتخذوه ويزيد توبيخهم على عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص551–552، تحت «بلاغة الاحتراس، في إتباع ﴿العجل﴾ بلفظ ﴿الجسد﴾»","url":""}]},{"id":"s7-983","number":983,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما معنى ﴿خوار﴾؟","answer":"الخوار صوت البقر، وذُكر هنا صوتًا خرج من العجل المصنوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص546، تحت «شرح المفردات: ﴿خوار﴾»","url":""}]},{"id":"s7-1620","number":1620,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما الذي يكشفه قوله تعالى: ﴿له خوار﴾ عن فتنة العجل؟","answer":"وجود الصوت لا يثبت للعجل حياة ولا ألوهية؛ فهو صوت لا يفيد كلامًا ولا هداية، ومع ذلك كان موضع افتتانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص552–553، تحت «دلالة قوله: ﴿له خوار﴾، وأثرها في السياق»","url":""}]},{"id":"s7-984","number":984,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"لماذا احتج عليهم بقوله: ﴿ألم يروا أنه لا يكلمهم﴾؟","answer":"الكلام من أوضح دلائل العلم والإرادة، فإذا كان لا يجيب عابديه ظهر بطلان ألوهيته مما يشاهدونه بأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص553–554، تحت «توجيه الاستفهام في قوله: ﴿ألم يروا﴾»","url":""}]},{"id":"s7-985","number":985,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما وجه الاحتجاج بنفي التكليم والهداية عن العجل؟","answer":"نفي التكليم يكشف افتقاره إلى العلم والحياة، ونفي الهداية يكشف افتقاره إلى القدرة على الإرشاد. وبانتفاء هذه الصفات يظهر بطلان اتخاذه إلهًا، فيقيم الكلام الحجة من حال المعبود المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص554، تحت «تجلي بلاغة المذهب الكلامي بالاحتجاج النظري»","url":""}]},{"id":"s7-986","number":986,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سر التعبير بقوله تعالى: ﴿ولا يهديهم سبيلًا﴾ لا «ولا يهديهم» فقط؟","answer":"ذكر ﴿سبيلًا﴾ يعمم نفي الإرشاد إلى الخير؛ فلا يدلهم العجل على طريق ينتفعون به، فضلًا عن هداية الدين والنجاة، فيظهر عجز ما اتخذوه معبودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص546، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-987","number":987,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"لماذا كرر ﴿اتخذوه﴾ بعد تفصيل صنعه وعجزه؟","answer":"أعيد ﴿اتخذوه﴾ بعد إظهار عجزه للتعجيب والتوبيخ: مع وضوح أنه جسد لا يكلم ولا يهدي، اتخذوه إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص555–556، تحت «بلاغة الكناية في ﴿اتخذوه﴾»","url":""}]},{"id":"s7-988","number":988,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"لماذا ختم بـ﴿وكانوا ظالمين﴾؟","answer":"الخاتمة تبين أن فعلهم ناشئ عن ظلم راسخ: ظلموا أنفسهم بالشرك ووضعوا العبادة في غير موضعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص556–557، تحت «وجوه التعبير بجملة: ﴿وكانوا ظالمين﴾»","url":""}]},{"id":"s7-989","number":989,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما سقط في أيديهم﴾، وما صورة السقوط في اليد؟","answer":"كأن الندم وقع في أيديهم أو عضوا أيديهم بعد فوات الأمر، فصاروا عاجزين متحسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص562–563، تحت «الاستعارة التمثيلية، أو الكناية، أو التشبيه في: ﴿ولما سقط في أيديهم﴾»","url":""}]},{"id":"s7-990","number":990,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"لماذا بُني ﴿سقط﴾ للمجهول ولم يذكر الساقط؟","answer":"أجري التعبير مجرى المثل، فالمقصود تصوير الندم والعجز لا تعيين شيء سقط حقيقة. ويذكر المصدر أن البناء للمجهول يلائم وقوع هذه الحال عليهم من غير اختيار، وكأنهم صاروا مغلوبين محصورين لا حيلة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص566–567، تحت «براعة التعبير بالفعل المبني للمجهول ﴿سقط﴾»","url":""}]},{"id":"s7-991","number":991,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"لماذا جمع بين ﴿سقط في أيديهم﴾ و﴿ورأوا أنهم قد ضلوا﴾؟","answer":"الأول يصور حال الندم والحسرة، والثاني يبين سببها العقلي: تبين لهم أنهم فارقوا طريق الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص568–569، تحت «نكتة تقديم الندم على تبين الضلال»","url":""}]},{"id":"s7-992","number":992,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"لماذا أكد ضلالهم بـ﴿أنهم قد ضلوا﴾؟","answer":"﴿أن﴾ و﴿قد﴾ تثبتان تحقق الضلال ووضوحه لهم بعد انكشاف الفتنة؛ فلم يعد مجرد ظن.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص569، تحت «سر التعبير بالفعلين الماضيين ﴿ورأوا﴾، و﴿ضلوا﴾»","url":""}]},{"id":"s7-993","number":993,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"ما سرّ تقديم الرحمة على المغفرة في قولهم: ﴿لئن لم يرحمنا ربنا ويغفر لنا﴾؟","answer":"قدمت الرحمة لأنها المقصود الأصيل، ولأنها تشمل إرادة الخير لهم وتوفيقهم للتوبة التي تكون سببًا للمغفرة. فقدموا ما يرجون به الرجوع إلى الله، ثم طلبوا محو الذنب والتجاوز عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص571، تحت «علة تقديم الرحمة على المغفرة»","url":""}]},{"id":"s7-994","number":994,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"ما دلالة قولهم: ﴿ربنا﴾ بعد عبادتهم العجل؟","answer":"قولهم ﴿ربنا﴾ اعتراف بالرجوع إلى ربهم الحق بعد بطلان العجل، واستعطاف بوصف الربوبية والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص570، تحت «سر الإتيان باللفظين ﴿ربنا﴾، و﴿لنا﴾»","url":""}]},{"id":"s7-995","number":995,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"لماذا أكدوا الخسران باللام والنون: ﴿لنكونن من الخاسرين﴾؟","answer":"اللام ونون التوكيد تثبتان يقينهم بأن عدم الرحمة والمغفرة يوقعهم حتمًا في الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص569، تحت «بلاغة حشد المؤكدات في الآية»","url":""}]},{"id":"s7-996","number":996,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"ما سرّ تعبيرهم: ﴿من الخاسرين﴾ لا «خاسرين»؟","answer":"﴿من الخاسرين﴾ تدخلهم في زمرة معروفة استقر فيها الخسران، فهي أبلغ من وصفهم بخسارة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص570–571، تحت «بلاغة التعبير بـ﴿من﴾، على طريق الكناية»","url":""}]},{"id":"s7-997","number":997,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما رجع موسى إلى قومه غضبان أسفًا﴾، فجمع الغضب والأسف؟","answer":"الغضب إنكار شديد لما وقع من الشرك، والأسف شدة الحزن والتلهف عليه؛ فجمع بين الغيرة للحق والألم على ضلال قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص592، تحت «الأسف والغضب والحزن».","url":""}]},{"id":"s7-998","number":998,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما سرّ تقديم ﴿غضبان﴾ على ﴿أسفًا﴾؟","answer":"قدم الغضب لأن مقام الرسول أمام الشرك يقتضي الإنكار والغيرة على الدين، ولا يكتفى فيه بالحزن وحده. ثم جاء الأسف ليصور شدة التألم على ما آل إليه قومه، فجمع الموقف بين الإنكار والحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص578، تحت «علة تقديم الغضب على الأسف»","url":""}]},{"id":"s7-999","number":999,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿بئسما خلفتموني من بعدي﴾؟","answer":"﴿بئسما﴾ ذم شديد لما صنعوه في غيبته، و﴿خلفتموني﴾ أي بئس الخلافة التي قمتم بها بعدي إذ عبدتم العجل وخالفتم وصيتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص578–579، تحت «دلالة التعبير بفعل الذم ﴿بئسما﴾»","url":""}]},{"id":"s7-1000","number":1000,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا جمع بين ﴿خلفتموني﴾ و﴿من بعدي﴾؟","answer":"يذم ﴿خلفتموني﴾ ما صنعوه في غيبته، ويصرح ﴿من بعدي﴾ بأن الانقلاب وقع بعد مفارقته؛ فيؤكد قبح الجحود ويرفع توهم أن اتخاذ العجل وقع بإقراره أو بحضوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص579–580، تحت «بلاغة الإطناب في قوله: ﴿من بعدي﴾»","url":""}]},{"id":"s7-1001","number":1001,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا سألهم: ﴿أعجلتم أمر ربكم﴾؟","answer":"الاستفهام إنكاري: أعجلتم عن أمر ربكم وميعاده قبل تمامه، واستبقتم حكمه فاتخذتم العجل؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص580–581، تحت «دلالة الاستفهام»","url":""}]},{"id":"s7-1002","number":1002,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا أضاف الأمر إلى ﴿ربكم﴾؟","answer":"إضافة الأمر إلى الرب تعظم ما استعجلوه وخالفوه، وتذكرهم بأن الميقات والتشريع صادران ممن يربيهم وينعم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص581–582، تحت «بلاغة العدول من التعريف بأل إلى التعريف بالإضافة»","url":""}]},{"id":"s7-1003","number":1003,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا ألقى موسى الألواح مع أنه أُمر أن يأخذها بقوة؟","answer":"ألقى الألواح من شدة الغضب لله عند رؤية الشرك، إلقاءً عارضًا لا رفضًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص582–583، تحت «علة التعبير بإلقاء الألواح»","url":""}]},{"id":"s7-1004","number":1004,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿وأخذ برأس أخيه يجره إليه﴾ لا «عاتب أخاه»؟","answer":"حكى الفعل المحسوس شدة غضبه وعتابه لهارون، إذ أخذ بشعر رأسه يجره إليه ظانًا أنه قصر، وهو أبلغ في تصوير المشهد من لفظ العتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص583–584، تحت «بلاغة التعبير بالمجاز المرسل عن أخذ الرأس»","url":""}]},{"id":"s7-1005","number":1005,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا نادى هارون موسى بقوله: ﴿ابن أم﴾ لا «يا أخي»؟","answer":"استعطفه برابطة الأم لأنها أرق وأدعى للرحمة، وهما أخوان لأب وأم؛ فاختار النداء الذي يهدئ غضبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص586–587، تحت «سر العدول من عبارة ابن أب إلى عبارة ﴿ابن أم﴾»","url":""}]},{"id":"s7-1006","number":1006,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما دلالة اعتذار هارون: ﴿إن القوم استضعفوني﴾؟","answer":"بيّن أنه لم يرض بعبادة العجل، لكن القوم عدوه ضعيفًا ولم يطيعوه، فكان قوله دفعًا لتهمة التقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص587–588، تحت «علة تأكيد الخبر بـ﴿إن﴾»","url":""}]},{"id":"s7-1007","number":1007,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا جمع بين ﴿استضعفوني﴾ و﴿كادوا يقتلونني﴾؟","answer":"﴿استضعفوني﴾ يبين بداية تسلطهم ورفضهم أمره، و﴿كادوا يقتلونني﴾ يبلغ بهذا التسلط غايته؛ فالعجز كان عن مقاومة فتنة تهدد حياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص588–589، تحت «فائدة تقديم فعل الاستضعاف على إرادة القتل»","url":""}]},{"id":"s7-1008","number":1008,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تشمت بي الأعداء﴾ قبل قوله ﴿ولا تجعلني مع القوم الظالمين﴾؟","answer":"بدأ بطلب دفع الأمر الأخص، وهو شماتة الأعداء به، ثم طلب الأمر الأعم، وهو ألا يلحق بالقوم الظالمين. فترقى في الالتماس من دفع أثر العتاب عنه إلى إظهار براءته من ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص590، تحت «نكتة تقديم فعل النهي عن الشماتة على فعل الترك»","url":""}]},{"id":"s7-1009","number":1009,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا سمّى بعض القوم ﴿الأعداء﴾ مع أنهم من بني إسرائيل؟","answer":"سموا أعداء لأنهم عاندوا التوحيد وفرحوا بما يصيب هارون، وإن جمعهم نسب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص589–590، تحت «إيثار لفظ ﴿الأعداء﴾ على غيره»","url":""}]},{"id":"s7-1010","number":1010,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"لماذا بدأ موسى بالدعاء: ﴿رب اغفر لي ولأخي﴾ بعد سماع عذر هارون؟","answer":"جاء الدعاء جوابًا لما سمعه من اعتذار هارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص594–595، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-1011","number":1011,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"لماذا قدّم نفسه في المغفرة: ﴿لي ولأخي﴾؟","answer":"بدأ بنفسه تأدبًا مع الله، ثم سأل المغفرة لأخيه وجمعه معه في الدعاء. وفي ذلك إظهار رضاه عنه، وقطع لطمع من أراد أن يشمت بهما أو يفرق بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص595، تحت «سر تقديم مغفرته على مغفرة أخيه»","url":""}]},{"id":"s7-1012","number":1012,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"لماذا طلب المغفرة لهارون مع ظهور عذره؟","answer":"الاستغفار لا يقتضي ثبوت ذنب محقق؛ هو دعاء بالستر والتجاوز عما قد يكون وقع من قصور في مقاومة القوم، وزيادة في التواضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص595–596، تحت «سر تقديم مغفرته على مغفرة أخيه»","url":""}]},{"id":"s7-1013","number":1013,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿وأدخلنا في رحمتك﴾، فصوّر الرحمة مكانًا يُدخل فيه؟","answer":"صورت الرحمة كحيز واسع يحيط بهما ويحميهما، فطلبا رحمة شاملة لا عطاءً جزئيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص596–597، تحت «جمال التعبير بفعل الإدخال ﴿وأدخلنا﴾»","url":""}]},{"id":"s7-1014","number":1014,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"لماذا ختم بـ﴿وأنت أرحم الراحمين﴾؟","answer":"ختم بأوسع وصف للرحمة توسلًا يناسب قوله ﴿وأدخلنا في رحمتك﴾، وإقرارًا بأن رحمته فوق رحمة كل راحم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص597، تحت «بلاغة رد العجز على الصدر»","url":""}]},{"id":"s7-1015","number":1015,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لماذا أعيد وصفهم بـ﴿الذين اتخذوا العجل﴾ بدل الضمير؟","answer":"أظهر الموصول ليعيد وصف جرمهم نفسه في مقام الوعيد، فيكون سبب العقوبة حاضرًا: اتخاذ العجل إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص602، تحت «براعة التعريف بالموصولية بلفظ ﴿الذين﴾»","url":""}]},{"id":"s7-1017","number":1017,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿سينالهم غضب﴾، فجعل الغضب نائلًا لهم؟","answer":"استعير النيل لإصابتهم بالغضب والذلة وتلبسهم بهما، فصور وقوع الجزاء عليهم. وتؤكد السين تحقق الوعيد في المستقبل، وأن ما توعدوا به سيلحقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص602–603، تحت «علة التعبير بسين الاستقبال ﴿سينالهم﴾»","url":""}]},{"id":"s7-1018","number":1018,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لماذا نُكّر ﴿غضب﴾ و﴿ذلة﴾؟","answer":"التنكير للتهويل: غضب عظيم وذلة عظيمة لا يحيط السامع بمقدارهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص603–604، تحت «نكتة تنكير الغضب والذلة»","url":""}]},{"id":"s7-1019","number":1019,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لم خص الغضب بقوله ﴿من ربهم﴾، ولم يكرر القيد مع الذلة؟","answer":"يذكر المصدر وجهًا يختص فيه غضب الآخرة بالله، فلا يشاركه فيه أحد، أما الذلة في الدنيا فقد تجري على أيدي البشر بإذنه. فناسب تقييد الغضب بأنه من ربهم، مع إطلاق الذلة التي تصيبهم في حياتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص604–605، تحت «نكتة قصر الغضب على الله دون الذلة»","url":""}]},{"id":"s7-1020","number":1020,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لماذا قيّد الذلة بـ﴿في الحياة الدنيا﴾؟","answer":"قيدها بالدنيا لبيان أن أثر الشرك لا ينتظر الآخرة، بل يلحقهم فيه هوان دنيوي، مع بقاء عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص604–605، تحت «سر الجمع بين لفظي ﴿الحياة﴾ و﴿الدنيا﴾»","url":""}]},{"id":"s7-1021","number":1021,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لماذا سمّى عبادة العجل افتراءً: ﴿وكذلك نجزي المفترين﴾؟","answer":"لأنهم اختلقوا على الله شريكًا ونسبوا الألوهية إلى العجل بلا برهان؛ فهذا أظهر الافتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص605–606، تحت «نكتة التعبير بفعل الافتراء»","url":""}]},{"id":"s7-1022","number":1022,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"ما أثر التذييل بقوله ﴿وكذلك نجزي المفترين﴾؟","answer":"يعمم التذييل الجزاء بعد ذكر عبدة العجل؛ فكل مفتر داخل في الوعيد بحسب افترائه. ويصور المضارع ﴿نجزي﴾ تجدد المجازاة واستمرارها، فلا ينحصر الحكم في أصحاب القصة وحدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص606، تحت «دلالة التعبير باسم الفاعل ﴿المفترين﴾»","url":""}]},{"id":"s7-1023","number":1023,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"لماذا قابل وعيد المفترين بقوله: ﴿والذين عملوا السيئات ثم تابوا﴾؟","answer":"بعد الوعيد فتح باب الرجاء: حتى من عمل السيئات إذا تاب وآمن وجد المغفرة والرحمة، فلا يتحول الوعيد إلى يأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–608، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-1024","number":1024,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿عملوا السيئات﴾ لا «أساؤوا»؟","answer":"التعبير بـ﴿عملوا السيئات﴾ يصرح بإسناد العمل السيئ إليهم، سواء تعلق سوء الفعل بالمباشرة أو كان العمل سيئًا في نفسه. وهو أخص من مطلق الإساءة، فإذا قبلت التوبة ممن تحقق منه هذا العمل كان ذلك أبلغ في فتح باب الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص608–609، تحت «سر العدول عن التعبير بعبارة والذين أساؤوا»","url":""}]},{"id":"s7-1025","number":1025,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"ما أثر صيغة الماضي والجمع في ﴿تابوا﴾ و﴿آمنوا﴾؟","answer":"يثبت الماضي وقوع التوبة والإيمان والعزم عليهما، ويعلن الجمع اتساع القبول للتائبين؛ فلا يعظم على مغفرة الله ذنب تاب صاحبه منه، مهما كثر الذنب أو طال زمنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص610، تحت «سر التعبير بالماضي والجمع»","url":""}]},{"id":"s7-1026","number":1026,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"لماذا عطف التوبة بـ﴿ثم﴾؟","answer":"تفيد ﴿ثم﴾ التراخي، فتفتح باب التوبة ولو جاءت بعد زمن طويل قضاه العبد في السيئات. وفي ذلك ترغيب في الرجوع إلى الله، دون اليأس بسبب طول المدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص609، تحت «جمال التعبير بحرف العطف ﴿ثم﴾»","url":""}]},{"id":"s7-1027","number":1027,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"إلى ماذا يعود الضمير في موضعي ﴿من بعدها﴾ في الآية؟","answer":"في ﴿ثم تابوا من بعدها﴾ يعود إلى السيئات، أي بعد عملها. وفي ﴿إن ربك من بعدها لغفور رحيم﴾ يرجح المصدر عوده إلى التوبة المفهومة من ﴿تابوا﴾، ويذكر احتمال عوده إلى السيئات مع تقدير العمل والتوبة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص609–610، تحت «توجيه عود الضمير في ﴿من بعدها﴾»","url":""}]},{"id":"s7-1028","number":1028,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"لماذا أكد المغفرة بـ﴿إن ربك من بعدها لغفور رحيم﴾؟","answer":"أكدت الجملة بـ﴿إن﴾ واللام لرفع اليأس بعد عظم السيئات، وتثبيت أن المغفرة والرحمة حاصلتان لمن صدق في التوبة والإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص611–612، تحت «بلاغة التوكيد بحشد المؤكدات»","url":""}]},{"id":"s7-1029","number":1029,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"ما أثر إضافة الرب إلى المخاطب في ﴿إن ربك﴾؟","answer":"في الإضافة تشريف للمخاطب بانتسابه إلى ربه، وفي وصف الربوبية تمهيد للمغفرة والرحمة بما يتضمنه من التربية والرعاية والإحسان. ويجعل المصدر الخطاب لمحمد ﷺ على الأظهر، ويذكر احتمال أن يكون لموسى في حكاية الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص611، تحت «كمال التعريف بالإضافة، والوصف بالربوبية»","url":""}]},{"id":"s7-1030","number":1030,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"لماذا جُمع بين ﴿غفور رحيم﴾؟","answer":"﴿غفور﴾ لمحو الذنب وستره، و﴿رحيم﴾ لإيصال الخير بعد المغفرة؛ فالتائب لا ينجو فقط بل تناله الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص612، تحت «دلالة التعبير بصيغتي المبالغة فعول وفعيل»","url":""}]},{"id":"s7-1031","number":1031,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما سكت عن موسى الغضب﴾، فجعل الغضب كأنه متكلم؟","answer":"شبه الغضب بشخص كان يحرك موسى ويدفعه إلى الكلام والفعل ثم سكت عنه؛ فصوّر هدوء ثورته بعد زوال سببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص615–616، تحت «كمال الاستعارات وتنوعها في لفظة السكوت»","url":""}]},{"id":"s7-1032","number":1032,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا عُدّي السكوت بـ﴿عن﴾؟","answer":"﴿سكت عن موسى﴾ تفيد انصراف سلطان الغضب عنه وكف أثره، كما يكف المتكلم كلامه عن شخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص614–615، تحت «وجه التعبير بلفظ ﴿سكت﴾ على طريق التضمين»","url":""}]},{"id":"s7-1033","number":1033,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا أعاد موسى أخذ الألواح بعد أن ألقاها؟","answer":"لما هدأ غضبه عاد إلى الألواح تعظيمًا للوحي وامتثالًا للأخذ بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص617، تحت «دلالة أل التعريف في لفظ ﴿الألواح﴾»","url":""}]},{"id":"s7-1034","number":1034,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿وفي نسختها﴾ لا «وفيها»؟","answer":"﴿نسختها﴾ أي ما نُسخ وكتب فيها، فوجه النظر إلى مضمونها المثبت لا إلى جرم الألواح وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص617–618، تحت «وجه التعبير عن نسخة ﴿الألواح﴾ على طريق الإيجاز»","url":""}]},{"id":"s7-1035","number":1035,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا جمع بين ﴿هدى ورحمة﴾؟","answer":"الهدى يبين طريق الحق، والرحمة ثمرة سلوكه من خير ونجاة؛ فجمعت الألواح الدلالة والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص619–620، تحت «سر تقديم الهدى على الرحمة»","url":""}]},{"id":"s7-1036","number":1036,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا خُص الهدى والرحمة بـ﴿للذين هم لربهم يرهبون﴾؟","answer":"الألواح هدى ورحمة في ذاتها، لكن الانتفاع الخاص بهما لمن يخاف ربه فيقبل أمره ويترك نهيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص620، تحت «علة تخصيص أهل الرهبة بالذكر، والتعبير بالمضارع»","url":""}]},{"id":"s7-1037","number":1037,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"ما سرّ تقديم ﴿لربهم﴾ على ﴿يرهبون﴾؟","answer":"تقديم ﴿لربهم﴾ للاختصاص والعناية: رهبتهم متوجهة إلى ربهم لا إلى سواه، ومن هذه الرهبة ينشأ امتثالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص620، تحت «نكتة تقديم المفعول في ﴿يرهبون﴾»","url":""}]},{"id":"s7-1038","number":1038,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا جيء بضمير ﴿هم﴾؟","answer":"ضمير ﴿هم﴾ يقوي الحكم ويخص المنتفعين الكاملين بالرهبة، فيفصلهم عمن يقرأ ولا يتعظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص620، تحت «فائدة الضمير ﴿هم﴾ في قوله: ﴿هم لربهم﴾»","url":""}]},{"id":"s7-1039","number":1039,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿واختار موسى قومه سبعين رجلًا﴾ من غير حرف جر؟","answer":"ويصور الحذف شدة اتصال المختارين بقومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص624–625، تحت «سر حذف حرف الجر في السياق»","url":""}]},{"id":"s7-1040","number":1040,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لم قدم ﴿قومه﴾ على ﴿سبعين رجلًا﴾؟","answer":"قدم ذكر القوم لأن الاختيار وقع فيهم، وللعناية بهم وبصلتهم بموسى، ثم بين المختارين منهم. ويعرض المصدر التقديم بوصفه عناية بالمجموعة التي انتخب منها خيارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص625–626، تحت «فائدة تقديم المجرور، وتأخير المفعول»","url":""}]},{"id":"s7-1041","number":1041,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما دلالة لفظ الميقات واللام في ﴿لميقاتنا﴾؟","answer":"الميقات وقت معين مقدر للعمل، فهو أخص من مطلق الوقت.؛ أي اختارهم ليأتوا إلى ذلك الميقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص627، تحت «الغاية من التعبير بلفظ الميقات، والفرق بينه وبين الوقت»","url":""}]},{"id":"s7-1042","number":1042,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أخذتهم الرجفة﴾، فجعل الرجفة آخذة؟","answer":"شبهت الرجفة بقوة تقبض عليهم وتستولي على أجسادهم، فكان الأخذ تصويرًا لشدة إحاطتها وتمكنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص628، تحت «بلاغة المجاز اللغوي والعقلي في ﴿أخذتهم الرجفة﴾»","url":""}]},{"id":"s7-1043","number":1043,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما دلالة قول موسى: ﴿لو شئت أهلكتهم من قبل وإياي﴾؟","answer":"ويذكر المصدر أنه تذكير بالعفو السابق واستجلاب للعفو اللاحق، مع تسليم موسى نفسه لأمر ربه، لا اعتراض على حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص631–632، تحت «سر تفريق موسى عليه السلام في الإهلاك بينه وبينهم»","url":""}]},{"id":"s7-1044","number":1044,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لم قال ﴿أهلكتهم من قبل وإياي﴾ ولم يجمعهم في «أهلكتنا»؟","answer":"يفرد التعبير كل فريق بالذكر ليناسب اختلاف الحال وما يتعلق بكل منهم. ويذكر المصدر وجهًا آخر في ذكر موسى نفسه: أنه تسليم لأمر الله مع طلب العفو لقومه، فكأنه لا يطلب سلامتهم مع الاستثناء لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص631–632، تحت «سر تفريق موسى عليه السلام في الإهلاك بينه وبينهم»","url":""}]},{"id":"s7-1045","number":1045,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا سأل: ﴿أتهلكنا بما فعل السفهاء منا﴾؟","answer":"الاستفهام استعطاف وتبرؤ من فعل السفهاء: أتهلك الجماعة بسبب من اقترف الجرم منها؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص632–633، تحت «بلاغة الاستفهام في ﴿أتهلكنا﴾»","url":""}]},{"id":"s7-1046","number":1046,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا وصف الفاعلين بـ﴿السفهاء منا﴾؟","answer":"وصفهم بالسفه لأن طلب الرؤية أو عبادة العجل صدر عن خفة عقل وجهل، و﴿منا﴾ تقر بالانتساب إليهم من غير تعميم الجرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص634، تحت «إيثار لفظ ﴿السفهاء﴾ والتعبير به»","url":""}]},{"id":"s7-1047","number":1047,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿إن هي إلا فتنتك﴾ بالقصر؟","answer":"القصر يرد الأمر كله إلى اختبار الله وحده: هذه الحادثة ليست خارجة عن تدبيره، بل امتحان يكشف المواقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص635، تحت «بلاغة القصر باستعمال الخبر والتعبير به»","url":""}]},{"id":"s7-1048","number":1048,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"إلى ماذا يعود الضمير في ﴿إن هي إلا فتنتك﴾؟","answer":"يعود إلى الفتنة الواقعة، كعبادة العجل أو طلب الرؤية وما ترتب عليه من الرجفة؛ والتأنيث لمراعاة لفظ ﴿فتنة﴾ المفهوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص634–635، تحت «بيان عود الضمير ﴿هي﴾»","url":""}]},{"id":"s7-1049","number":1049,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا جمع بين ﴿تضل بها من تشاء وتهدي من تشاء﴾؟","answer":"جمع الضدين لإظهار أن الفتنة الواحدة تكون سببًا لضلال من يعرض وهداية من يعتبر، وكل ذلك بمشيئة الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص636، تحت «بلاغة الطباق في ﴿تضل﴾ و﴿تهدي﴾»","url":""}]},{"id":"s7-1050","number":1050,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"كيف يتضمن قوله ﴿تضل بها من تشاء وتهدي من تشاء﴾ طلب الهداية؟","answer":"أقر موسى بأن الهداية بمشيئة الله، وفي هذا الإقرار تعريض بطلبها لقومه واسترحام لهم. فلم يقتصر الكلام على الإخبار، بل حمل معنى الدعاء بأدب وتضرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص635، تحت «نكتة التعريض بطلب الهداية لهم»","url":""}]},{"id":"s7-1051","number":1051,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما سرّ تقديم ضمير المخاطب في قوله: ﴿أنت ولينا﴾؟","answer":"تقديم ﴿أنت﴾ يفيد القصر والتوكيد: أنت وحدك متولي أمرنا وناصرنا، لا ملجأ لنا في هذه الفتنة إلا إليك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص636–637، تحت «بلاغة القصر والتقديم في ﴿أنت ولينا﴾»","url":""}]},{"id":"s7-1052","number":1052,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا جمع بين ﴿فاغفر لنا وارحمنا﴾؟","answer":"المغفرة تزيل أثر الذنب، والرحمة تجلب العفو والخير؛ فطلب رفع الضر وإحلال الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص637–638، تحت «علة تقديم المغفرة على الرحمة»","url":""}]},{"id":"s7-1053","number":1053,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا ختم بـ﴿وأنت خير الغافرين﴾ لا «أرحم الراحمين»؟","answer":"لأن المقام بدأ بطلب المغفرة في ﴿فاغفر لنا﴾، فناسبه ﴿خير الغافرين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص638–639، تحت «سر قوله: ﴿وأنت خير الغافرين﴾»","url":""}]},{"id":"s7-1054","number":1054,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿واكتب لنا في هذه الدنيا حسنة﴾، واستعار الكتابة للحسنة؟","answer":"الكتابة استعارة للإثبات والتقدير المحكم؛ أي قدر لنا حسنة ثابتة لا تزول كأنها مكتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص644–645، تحت «سر التعبير بالكتابة دون الإيتاء»","url":""}]},{"id":"s7-1055","number":1055,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿في هذه الدنيا﴾ باسم الإشارة؟","answer":"الإشارة تحضر الدنيا القريبة المشاهدة وتقابلها بالآخرة الغائبة، وفيها اعتراف بقصر هذه الدار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص646–647، تحت «سر الإشارة بـ﴿هذه الدنيا﴾»","url":""}]},{"id":"s7-1056","number":1056,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا نكّر ﴿حسنة﴾ في الدنيا وحذفها بعد ﴿وفي الآخرة﴾؟","answer":"نُكرت ﴿حسنة﴾ لتعم كل نعمة حسنة في الدنيا، وحذفت بعد ﴿وفي الآخرة﴾ لدلالة الأولى عليها، أي واكتب لنا حسنة في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص652–653، تحت «سر عدم تكرار لفظ ﴿حسنة﴾ مع الآخرة»","url":""}]},{"id":"s7-1057","number":1057,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما دلالة قولهم: ﴿إنا هدنا إليك﴾، وما معنى «هدنا»؟","answer":"﴿هدنا﴾ أي رجعنا وتبنا إليك، فأعلنوا الانتقال من المعصية إلى ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص654–655، تحت «دلالة التعبير بالماضي ﴿هدنا﴾»","url":""}]},{"id":"s7-1058","number":1058,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما صلة ﴿هدنا﴾ بتسمية اليهود؟","answer":"يذكر المصدر وجه اشتقاق تسميتهم من الهود بمعنى الرجوع والتوبة، لقولهم ﴿إنا هدنا إليك﴾. فالآية في هذا التوجيه تعلن توبتهم ورجوعهم، وهذا وجه في تعليل الاسم وليس جزمًا بحصر أصله فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–642، تحت «شرح المفردات: ﴿هدنا﴾»","url":""}]},{"id":"s7-1059","number":1059,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا جاء الجواب: ﴿عذابي أصيب به من أشاء ورحمتي وسعت كل شيء﴾؟","answer":"جاء الجواب موزعًا بين العدل والفضل: العذاب يصيب من تعلقت به المشيئة لحكمة، أما الرحمة فأصلها واسع ثم تكتب كتابة خاصة للمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص661–662، تحت «دلالة الإتيان بجملة: ﴿ورحمتي﴾ عقب ﴿قال عذابي﴾»","url":""}]},{"id":"s7-1060","number":1060,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى في العذاب: ﴿أصيب به﴾، وفي الرحمة: ﴿وسعت﴾؟","answer":"﴿أصيب به﴾ يجعل العذاب محددًا يقع على من استحقه، أما ﴿وسعت﴾ فتصور الرحمة محيطة بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص658–659، تحت «سر التعبير بالإصابة، في قوله: ﴿أصيب به﴾»","url":""}]},{"id":"s7-1061","number":1061,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ تقديم العذاب على الرحمة هنا؟","answer":"قدم العذاب للتخويف والتحذير في مقام الخوف من الهلاك، ثم عقب بسعة الرحمة ليقوي الرجاء. ويذكر المصدر أن البدء بالرحمة ثم ختم الكلام بالعذاب قد يجعل الخوف هو الأثر الأخير؛ فجاء هذا الترتيب ألطف بالمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص662، تحت «دلالة تقديم ذكر العذاب على الرحمة»","url":""}]},{"id":"s7-1062","number":1062,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا نُسب العذاب والرحمة إلى ضمير المتكلم: ﴿عذابي... رحمتي﴾؟","answer":"الإضافة في ﴿عذابي﴾ و﴿رحمتي﴾ تثبت أن التصرف لله وحده، وتعظم الأمرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص658، تحت «دلالة الإضافة في قوله: ﴿عذابي﴾»","url":""}]},{"id":"s7-1063","number":1063,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿ورحمتي وسعت كل شيء﴾، دون أن يقال: وأرحم من أشاء؟","answer":"أبرزت الجملة سعة الرحمة وعمومها فلم يقيد أصلها بفئة في صدر الكلام، ثم فرع عليها الوعد الخاص لمن يتقون ويؤتون الزكاة ويؤمنون بالآيات. فاجتمع عموم الرحمة مع بيان أهل الوعد المخصوص بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص665–666، تحت «دلالة الجمع بين ﴿كل﴾ و﴿شيء﴾ في الآية»","url":""}]},{"id":"s7-1064","number":1064,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"كيف تجمع الآية بين سعة الرحمة لكل شيء وقوله: ﴿فسأكتبها للذين يتقون﴾؟","answer":"الأولى تقرر عموم رحمة الله وسعة آثارها في الخلق، والثانية وعد مخصوص لمن اتصفوا بالتقوى والإيمان والعمل المذكور. فالتخصيص يتعلق بكتابة هذا الوعد لهم، ولا ينفي ما ينال سائر الخلق من آثار الرحمة العامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص665–666، تحت «دلالة الجمع بين ﴿كل﴾ و﴿شيء﴾ في الآية»","url":""}]},{"id":"s7-1065","number":1065,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا عُبر عن الرحمة الخاصة بالكتابة: ﴿فسأكتبها﴾؟","answer":"الكتابة تفيد التثبيت والإيجاب بوعد لا يتخلف؛ فهي رحمة خاصة مقدرة للمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص644–645، تحت «سر التعبير بالكتابة دون الإيتاء»","url":""}]},{"id":"s7-1066","number":1066,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا رتبت صفات مستحقي الرحمة: ﴿يتقون ويؤتون الزكاة والذين هم بآياتنا يؤمنون﴾؟","answer":"بدأ بالتقوى لأنها أصل الكف عن المعصية، ثم الزكاة مثال البذل العملي، ثم الإيمان بالآيات أصل التصديق الجامع للأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص668–669، تحت «دلالة الواو في ﴿ويؤتون الزكاة﴾»","url":""}]},{"id":"s7-1067","number":1067,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا أعيد الموصول في ﴿والذين هم بآياتنا يؤمنون﴾؟","answer":"أعيد الموصول للاهتمام بالإيمان بالآيات وجعله صفة مستقلة جامعة، مع تقوية فصلها عما قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص671–672، تحت «سر إعادة اسم الموصول ﴿والذين﴾»","url":""}]},{"id":"s7-1068","number":1068,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ تقديم ﴿بآياتنا﴾ على ﴿يؤمنون﴾؟","answer":"تقديم ﴿بآياتنا﴾ للعناية والاختصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص672–673، تحت «سر التعبير بالآيات في قوله: ﴿بآياتنا﴾»","url":""}]},{"id":"s7-1069","number":1069,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا وصف محمد ﷺ بـ﴿الرسول النبي الأمي﴾، وجمع هذه الأوصاف؟","answer":"﴿الرسول﴾ يبرز حمله الرسالة إلى الناس، و﴿النبي﴾ صلته بالوحي، و﴿الأمي﴾ قيام الحجة بأن ما جاء به ليس مكتسبًا من قراءة كتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص681–682، تحت «سر الجمع بين وصفي ﴿الرسول النبي﴾»","url":""}]},{"id":"s7-1070","number":1070,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما سرّ تقديم ﴿الرسول﴾ على ﴿النبي﴾ هنا؟","answer":"قدم وصف الرسول لشرف الرسالة وإبراز كونه مرسلًا من الله إلى الناس، ثم أتبع بالنبوة التي تؤكد تلقيه الوحي. واجتماع الوصفين يقوي الحجة الداعية إلى اتباعه ويجمع أسباب الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص680–681، تحت «سر الجمع بين وصفي ﴿الرسول النبي﴾»","url":""}]},{"id":"s7-1071","number":1071,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا وُصف النبي ﷺ بـ﴿الأمي﴾؟","answer":"وصفه بالأمي لأنه لم يقرأ كتابًا ولم يكتب، فكان مجيئه بالقرآن دليلًا على الوحي، وهو أيضًا من الأمة الأمية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص682–683، تحت «دلالة تأخير وصف ﴿الأمي﴾ على الرسالة والنبوة»","url":""}]},{"id":"s7-1072","number":1072,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿الذي يجدونه مكتوبًا عندهم﴾؟","answer":"﴿يجدونه﴾ يدل على أنهم يعثرون على صفته حاضرة ثابتة، و﴿مكتوبًا عندهم﴾ يلزمهم بما في الكتب التي بأيديهم لا بخبر بعيد عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص684–685، تحت «فائدة التعبير بالظرفية في قوله: ﴿عندهم﴾ دون فيه»","url":""}]},{"id":"s7-1073","number":1073,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا جمع بين ﴿في التوراة والإنجيل﴾؟","answer":"ذكرا لأن البشارة به وصفاته ثبتت في كتابي اليهود والنصارى، فالحجة قائمة على الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص685–686، تحت «دلالة الجمع بين التوراة والإنجيل»","url":""}]},{"id":"s7-1074","number":1074,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا رتبت وظائفه: ﴿يأمرهم بالمعروف وينهاهم عن المنكر ويحل لهم الطيبات ويحرم عليهم الخبائث﴾؟","answer":"بدأ بإصلاح المجتمع بالأمر والنهي، ثم بيان الحلال والحرام، ثم رفع التكاليف الشاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص691–692، تحت «سر الإتيان بالتحليل والتحريم، مقابل الأمر بالمعروف والنهي عن المنكر»","url":""}]},{"id":"s7-1075","number":1075,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما أثر التعبير بالمعروف والمنكر والطيبات والخبائث في وصف رسالته؟","answer":"وذكر الطيبات والخبائث يبين أن الحل والتحريم متعلقان بما فيه نفع وحسن أو خبث وضرر، فيقترن بيان الحكم بما يرغب في امتثاله أو ينفر من مخالفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص693–694، تحت «دلالة التعبير بلفظ ﴿الطيبات﴾ عن الحلال»","url":""}]},{"id":"s7-1076","number":1076,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿ويضع عنهم إصرهم﴾، وصوّر الإصر كحمل؟","answer":"الإصر الثقل والتكليف الشاق؛ فصوّر الشرائع الثقيلة بحمل موضوع فوقهم، والرسول يرفعه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص694–695، تحت «بلاغة الاستعارة، في قوله: ﴿ويضع عنهم﴾»","url":""}]},{"id":"s7-1077","number":1077,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا أفرد ﴿إصرهم﴾ وجمع ﴿الأغلال﴾؟","answer":"الإصر مفرد لأنه اسم جنس للثقل الجامع، والأغلال جمعت لتعدد القيود والتكاليف التي كانت تكبلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص696–697، تحت «دلالة الإفراد والجمع، في القراءة المتواترة: ﴿إصرهم﴾»","url":""}]},{"id":"s7-1078","number":1078,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿والأغلال التي كانت عليهم﴾؟","answer":"شبهت التكاليف الشديدة بالأغلال المحيطة بالأعناق، و﴿كانت عليهم﴾ تدل على ثقلها واستعلائها قبل أن ترفعها الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص697–698، تحت «سر التعبير بقوله عليهم دون فوقهم»","url":""}]},{"id":"s7-1079","number":1079,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا رتبت الاستجابة: ﴿آمنوا به وعزروه ونصروه واتبعوا النور﴾؟","answer":"بدأوا بتصديقه في القلب، ثم تعظيمه وتوقيره، ثم نصر رسالته، ثم ملازمة القرآن والعمل به؛ فانتقل من الاعتقاد إلى النصرة والاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص699–700، تحت «سر الترتيب في أوصاف: الإيمان والتعزير والنصر واتباع التنزيل»","url":""}]},{"id":"s7-1080","number":1080,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا سمّى القرآن ﴿النور الذي أنزل معه﴾؟","answer":"سماه نورًا لأنه يكشف الحق من الباطل ويهدي في ظلمات الجهل، كما يكشف النور الطريق المحسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص700، تحت «بلاغة التعبير بلفظ ﴿النور﴾ عن القران»","url":""}]},{"id":"s7-1081","number":1081,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿أنزل معه﴾ مع أن القرآن أُنزل إليه؟","answer":"﴿معه﴾ تفيد المصاحبة بين الرسول والقرآن في أداء الرسالة؛ أنزل القرآن مؤيدًا له ومقترنًا ببعثته، وإن كان التنزيل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص701، تحت «سر التعبير بالمعية في ﴿أنزل معه﴾»","url":""}]},{"id":"s7-1082","number":1082,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا خُتم بـ﴿أولئك هم المفلحون﴾؟","answer":"اسم الإشارة مع ضمير الفصل وتعريف الخبر يفيد اختصاصهم بالفلاح الكامل؛ لأنهم جمعوا الإيمان والتعظيم والنصرة والاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص701–702، تحت «بلاغة التركيب، في قوله: ﴿أولئك هم المفلحون﴾»","url":""}]},{"id":"s7-1083","number":1083,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا انتقل إلى الأمر العام: ﴿قل يا أيها الناس﴾ بعد خطاب بني إسرائيل؟","answer":"انتقل من حكاية البشارة به في كتب أهل الكتاب إلى إعلان عموم رسالته لكل البشر، فلا يظن أنها خاصة بأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص706، تحت «دلالة جملة النداء ﴿يا أيها الناس﴾»","url":""}]},{"id":"s7-1084","number":1084,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"ما أثر النداء في ﴿يا أيها الناس﴾؟","answer":"يلفت النداء انتباه المخاطبين إلى الدعوة ويوقظهم من الغفلة، ولفظ الناس يعمم الإعلان ليشمل البشر جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص706، تحت «دلالة جملة النداء ﴿يا أيها الناس﴾»","url":""}]},{"id":"s7-1085","number":1085,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا أكد: ﴿إني رسول الله إليكم جميعًا﴾؟","answer":"أكد بـ﴿إن﴾ لمواجهة من ينكر عموم رسالته أو يقصرها على العرب، وقرر أنه رسول الله إلى المخاطبين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص707–708، تحت «دلالة التأكيد بـ﴿إني﴾»","url":""}]},{"id":"s7-1086","number":1086,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿إليكم جميعًا﴾ مع أن ﴿الناس﴾ تفيد العموم؟","answer":"﴿جميعًا﴾ نص في استغراق أفراد الناس وتدفع احتمال إرادة طائفة مخصوصة من لفظ ﴿الناس﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص708–709، تحت «سر التعبير بقوله تعالى ﴿جميعًا﴾»","url":""}]},{"id":"s7-1087","number":1087,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا وُصف الله بـ﴿الذي له ملك السماوات والأرض﴾ عقب عالمية الرسالة؟","answer":"من له ملك السماوات والأرض يملك إرسال رسول إلى جميع من فيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص709–710، تحت «علاقة قوله ﴿الذي له ملك السماوات والأرض﴾ بما قبله»","url":""}]},{"id":"s7-1089","number":1089,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا أعقب الملك بقوله: ﴿لا إله إلا هو﴾؟","answer":"إذا انفرد بالملك لزم انفراده بالعبادة، فجاء التوحيد نتيجة لتمام السلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص710، تحت «دلالة موقع جملة ﴿لا إله إلا هو يحيي ويميت﴾ مما قبلها»","url":""}]},{"id":"s7-1090","number":1090,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا جمع بين ﴿يحيي ويميت﴾؟","answer":"جمعهما لإثبات السلطان على طرفي الوجود الإنساني ومصيره، ومن يحيي ويميت وحده يستحق العبادة والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص710–711، تحت «سر الإتيان بصفة الإحياء والإماتة»","url":""}]},{"id":"s7-1091","number":1091,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا فرّع الأمر بالإيمان: ﴿فآمنوا بالله ورسوله﴾؟","answer":"الفاء تفرع وجوب الإيمان على البراهين السابقة: عموم الرسالة، وملك الله، ووحدانيته، وإحياؤه وإماتته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص712–713، تحت «دلالة الفاء في قوله ﴿فآمنوا﴾»","url":""}]},{"id":"s7-1092","number":1092,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا أعيد وصف الرسول بـ﴿النبي الأمي﴾ بعد الآية السابقة؟","answer":"أعيد الوصف لتعيين الرسول المأمور بالإيمان به، ولتذكير الناس بدليل أميته الذي سبق أن أقيم على أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص714–715، تحت «سر إعادة وصفه بقوله ﴿النبي الأمي﴾»","url":""}]},{"id":"s7-1093","number":1093,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"ما سرّ التعبير في قوله تعالى عن الرسول: ﴿الذي يؤمن بالله وكلماته﴾؟","answer":"يعلن الوصف كمال إيمانه بالله وتصديقه بكلماته؛ فالإيمان بالله لا ينفك عن الإيمان بوحيه وآياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص715–716، تحت «دلالة التصريح بإيمانه بالله في قوله ﴿الذي يؤمن بالله﴾»","url":""}]},{"id":"s7-1094","number":1094,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا جُمعت ﴿كلماته﴾؟","answer":"الجمع يشمل كلمات الله الكونية والشرعية وكتبه ووحيه المتعدد، وفيه كمال تصديق الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص716–717، تحت «سر اختيار صيغة الجمع ﴿وكلماته﴾»","url":""}]},{"id":"s7-1095","number":1095,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا ختم بـ﴿واتبعوه لعلكم تهتدون﴾ بعد الأمر بالإيمان؟","answer":"الإيمان أصل القلب، والاتباع أثره العملي؛ فليس المقصود مجرد التصديق، وإنما سلوك هديه، وبه ترجى الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص718، تحت «بلاغة موقع فاصلة الآية: ﴿لعلكم تهتدون﴾».","url":""}]},{"id":"s7-1096","number":1096,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]},{"surah":57,"verses":[7]},{"surah":64,"verses":[8]}],"verseLabel":"الأعراف: 158؛ الحديد: 7؛ التغابن: 8","question":"ما سرّ التعبير في قوله تعالى في الأعراف والتغابن: ﴿فآمنوا بالله ورسوله﴾ بالفاء، وفي الحديد: ﴿آمنوا بالله ورسوله﴾ بلا فاء؟","answer":"في الأعراف جاءت الفاء تفريعًا على صفات الله من الملك والتوحيد والإحياء والإماتة، وفي التغابن فاء فصيحة: إذا تبينت الحجج والعواقب فآمنوا؛ أما الحديد فانتقل من الاستدلال إلى الأمر المباشر بلا حاجة إلى تفريع ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص658، تحت «سر اختلاف التعبير بالإيمان في الأعراف والتغابن»","url":""}]},{"id":"s7-1097","number":1097,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن قوم موسى أمة﴾ بعد ذكر انحرافات بني إسرائيل؟","answer":"استدرك بأن من قوم موسى جماعة ثابتة على الحق، إنصافًا للصالحين منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص722–723، تحت «دلالة الواو في قوله ﴿ومن قوم موسى﴾»","url":""}]},{"id":"s7-1098","number":1098,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"لم اختير لفظ ﴿أمة﴾ دون طائفة أو جماعة؟","answer":"يشعر لفظ الأمة باجتماعهم على قصد واحد هو الحق، وبائتمامهم بموسى وهداهم الذي يقتدي به غيرهم. فلا يراد مجرد جماعة اجتمع أفرادها، بل جماعة يجمعها مقصد هادٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص723، تحت «سر اختيار لفظ ﴿أمة﴾ دون طائفة أو جماعة»","url":""}]},{"id":"s7-1099","number":1099,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿يهدون بالحق﴾ لا «يهتدون»؟","answer":"﴿يهدون﴾ متعدٍّ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص723–724، تحت «سر اختيار ﴿يهدون﴾ دون يدعون»","url":""}]},{"id":"s7-1100","number":1100,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"لماذا عُدّيت الهداية بـ﴿الباء﴾: ﴿بالحق﴾؟","answer":"الباء للملابسة؛ فهم يهدون ملازمين للحق، ويقيمون العدل به. فهدايتهم وعدلهم مرتبطان بالحق لا بالهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص724، تحت «سر تكرار الجار والمجرور ﴿وبه﴾ في السياق»","url":""}]},{"id":"s7-1101","number":1101,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"لماذا كرر الحق ضميرًا في ﴿وبه يعدلون﴾؟","answer":"أعيد الحق ضميرًا وقدّم في ﴿وبه يعدلون﴾ لإبراز أنه الأداة والمعيار الذي يقيمون به العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص724، تحت «سر تكرار الجار والمجرور ﴿وبه﴾ في السياق»","url":""}]},{"id":"s7-1102","number":1102,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"لماذا جمع بين الهداية والعدل؟","answer":"الهداية تبليغ الحق والدلالة عليه، والعدل تنفيذه في الحكم والعمل؛ فجمعوا العلم بالحق وتطبيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص724–725، تحت «سر ختام الآية بالعدل في قوله ﴿يعدلون﴾»","url":""}]},{"id":"s7-1103","number":1103,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿وقطعناهم اثنتي عشرة أسباطًا أممًا﴾، واستعمل «قطعنا» للتقسيم؟","answer":"﴿قطعناهم﴾ أي قسمناهم جماعات متميزة، فصوّر انفصال الأسباط بعضهم عن بعض مع بقائهم من أصل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص731، تحت «نكتة المجاز في قوله ﴿وقطعناهم﴾»","url":""}]},{"id":"s7-1104","number":1104,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا أُنّث العدد في ﴿اثنتي عشرة﴾ مع ﴿أسباطًا﴾ المذكر؟","answer":"العدد يطابق معدودًا مؤنثًا مقدرًا، أي اثنتي عشرة فرقة أو قطعة.؛ و﴿أسباطًا﴾ بدل يبين تلك الفرق، وليس تمييز العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص732–733، تحت «دلالة التأنيث في العدد اثنتي عشرة»","url":""}]},{"id":"s7-1105","number":1105,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا جمع بين ﴿أسباطًا﴾ و﴿أممًا﴾؟","answer":"﴿أسباطًا﴾ تبين أن التقسيم بحسب الأنساب، و﴿أممًا﴾ تبين أن كل سبط صار جماعة مستقلة لها نظامها وشؤونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص733–734، تحت «تنكير أممًا»","url":""}]},{"id":"s7-1106","number":1106,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما أثر ﴿إذ استسقاه قومه﴾ في بيان وقت الوحي؟","answer":"فإدخاله بين الإيحاء ومضمونه يبرز اتصال الإغاثة بالطلب وعناية الله بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص734–735، تحت «فائدة دخول إذ استسقاه بين فعل الإيحاء ومضمونه»","url":""}]},{"id":"s7-1107","number":1107,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا أضيف القوم إلى موسى: ﴿قومه﴾؟","answer":"الإضافة تربطهم بنبيهم الذي طلبوا منه واستسقى لهم، وتذكر بمسؤوليته عنهم وصلتهم برسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص736–737، تحت «فائدة إضافة القوم إلى الضمير العائد في قومه»","url":""}]},{"id":"s7-1108","number":1108,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿أن اضرب بعصاك الحجر﴾، وجُعل الضرب سببًا لخروج الماء؟","answer":"جعل الضرب بالعصا سببًا ظاهرًا لخروج الماء مع أن القدرة لله، لتظهر المعجزة من اجتماع سبب لا يخرج الماء عادة بنتيجة خارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص737–738، تحت «معنى الباء في قوله ﴿بعصاك﴾»","url":""}]},{"id":"s7-1109","number":1109,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا عُرّف ﴿الحجر﴾؟","answer":"على التوجيه الذي يختاره المصدر، أل للجنس: أي اضرب أي حجر، فلا تختص المعجزة بحجر معين. وبذلك تبرز الآية أثر القدرة الإلهية في خروج الماء بالضرب بالعصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص738، تحت «معنى أل الجنس في ﴿الحجر﴾»","url":""}]},{"id":"s7-1110","number":1110,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فانبجست﴾، وفي البقرة: ﴿فانفجرت﴾؟","answer":"الانبجاس بدء خروج الماء بقلة، والانفجار خروجه بغزارة، فيمكن أن يصورا مرحلتين من النعمة. وذكر الانفجار في البقرة يبرز كمال الإنعام في مقام التذكير به وتوبيخ من لم يشكره، أما الانبجاس في الأعراف فيثبت أصل المنة بخروج الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص739، تحت «دلالة التعبير بالفعل فانبجست»","url":""}]},{"id":"s7-1111","number":1111,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما فائدة قوله: ﴿قد علم كل أناس مشربهم﴾ بعد تفجير العيون؟","answer":"جعل لكل جماعة عينًا ومشربًا تعرفه وتختص به، منعًا للتزاحم والنزاع، فصارت النعمة منظمة ظاهرة لكل سبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص740–741، تحت «فائدة إضافة المشرب إليهم»","url":""}]},{"id":"s7-1112","number":1112,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿قد علم كل أناس مشربهم﴾؟","answer":"﴿قد﴾ تحقق العلم، و﴿كل أناس﴾ تفيد أن كل جماعة عرفت موردها المخصص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص741–742، تحت «فائدة دخول قد»","url":""}]},{"id":"s7-1113","number":1113,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لم نكر ﴿أناس﴾ في ﴿قد علم كل أناس مشربهم﴾؟","answer":"يفيد التنكير التكثير؛ فكل سبط جماعة كثيرة، ومع كثرتهم عرفت كل جماعة مشربها. وفي ذلك إبراز إحكام تقسيم الماء وكفايته لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص741، تحت «نكتة تنكير أناس»","url":""}]},{"id":"s7-1114","number":1114,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿وظللنا عليهم الغمام﴾، فجعل الغمام مظلة؟","answer":"جعل الغمام فوقهم يحجب حر الشمس، فالفعل يصور السحاب مظلة ممتدة بعناية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص742–743، تحت «فائدة تعدية الفعل وظللنا بعلى»","url":""}]},{"id":"s7-1115","number":1115,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا اختير ﴿الغمام﴾ لا «السحاب»؟","answer":"الغمام من الغم بمعنى الستر، فناسب التعبير به عن التظليل وحجب الشمس. أما السحاب فيلحظ في تسميته معنى السحب والحركة، فاختير ما يبرز وظيفة الستر في هذه النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص750–751، تحت «الغمام والسحاب»","url":""}]},{"id":"s7-1116","number":1116,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا جمع بين الماء والظل والمن والسلوى في آية واحدة؟","answer":"جمعت مقومات بقائهم في الصحراء: الماء للشرب، والغمام للوقاية، والمن والسلوى للطعام؛ فتكامل الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص745–746، تحت «بلاغة ترتيب ذكر النعم»","url":""}]},{"id":"s7-1117","number":1117,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنزلنا عليهم المن والسلوى﴾؟","answer":"﴿أنزلنا﴾ يفيد أن الرزق جاءهم من فوق من غير كسب معتاد، و﴿عليهم﴾ تشعر بإحاطته وكثرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص729–730، تحت «شرح المفردات: المن والسلوى»","url":""}]},{"id":"s7-1118","number":1118,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا جاء الأمر: ﴿كلوا من طيبات ما رزقناكم﴾؟","answer":"الأمر للإباحة والامتنان: انتفعوا بالحلال المستطاب الذي رزقكم الله، وفي إضافة الرزق إليه تذكير بالمنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص744–745، تحت «دلالة فعل الأمر كلوا في الآية»","url":""}]},{"id":"s7-1120","number":1120,"surah":7,"verses":[160,177],"references":[{"surah":7,"verses":[160,177]}],"verseLabel":"الأعراف: 160؛ الأعراف: 177","question":"ما دلالة تقديم ﴿أنفسهم﴾ في قوله تعالى: ﴿وأنفسهم كانوا يظلمون﴾؟","answer":"يفيد التقديم قصر ظلمهم على أنفسهم واختصاص ضرره بهم؛ فتكذيبهم لا يتعدى أثره إلى الله ولا يضر غيرهم، وإنما ترجع عاقبته عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص177، تحت «بلاغة القصر بتقديم المفعول به: ﴿وأنفسهم﴾»","url":""}]},{"id":"s7-1121","number":1121,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا جرت آية الأعراف أولًا بضمير الغيبة: ﴿وقطعناهم... وأوحينا... استسقاه قومه﴾، ثم التفتت إلى الخطاب: ﴿كلوا من طيبات ما رزقناكم﴾؟","answer":"بدأت القصة حكايةً عن أسلاف المخاطبين بضمير الغيبة، ثم التفتت إلى خطابهم في النعمة والتكليف ليشعر السامعون أنهم معنيون بالشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص470، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-1122","number":1122,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا خوطب بنو إسرائيل في البقرة بقوله: ﴿وظللنا عليكم... وأنزلنا عليكم﴾، وحُكي عنهم في الأعراف بضمير الغيبة: ﴿وظللنا عليهم... وأنزلنا عليهم﴾؟","answer":"البقرة تخاطب بني إسرائيل مباشرة في مقام تعداد نعم الله عليهم، أما الأعراف فتسرد قصتهم للنبي ﷺ والأمة، فغلب فيها ضمير الغيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص470، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-1123","number":1123,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا ذُكر في البقرة: ﴿كلوا واشربوا من رزق الله﴾، ولم يذكر الشرب في آية الأعراف؟","answer":"جمعت البقرة: 60 الأكل والشرب لتجمع التذكير بالنعم وتبرز كمال الإكرام بعد تفجر العيون. أما ﴿كلوا من طيبات ما رزقناكم﴾ في الأعراف فمتصل بذكر المن والسلوى، وهو الأمر الذي جاء أيضًا في البقرة: 57 بعد ذكرهما؛ فكل تعبير منظور فيه إلى موضعه وسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص497–499، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-1124","number":1124,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وإذ قيل لهم اسكنوا هذه القرية﴾، وفي البقرة: ﴿وإذ قلنا ادخلوا هذه القرية﴾؟","answer":"في الأعراف أوجز بذكر ﴿قيل﴾ لعلم القائل، وفي البقرة صرح بإسناد القول إلى الله. والدخول أول الوصول إلى القرية، أما السكن فالإقامة فيها بعد الدخول؛ فكل سورة تذكر من القصة ما يلائم مقامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773–774، تحت «فائدة التعبير بفعل الأمر اسكنوا»","url":""}]},{"id":"s7-1125","number":1125,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"لماذا بُني ﴿قيل﴾ للمجهول هنا، وأُسند القول إلى الله في البقرة؟","answer":"بناء ﴿قيل﴾ للمجهول يوجز الحكاية لأن القائل معلوم، أما ﴿قلنا﴾ في البقرة فيبرز المنعم ضمن سياق الامتنان المباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص755، تحت «نكتة بناء الفعل قيل لما لم يسم فاعله»","url":""}]},{"id":"s7-1126","number":1126,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿اسكنوا﴾ هنا و﴿ادخلوا﴾ في البقرة؟","answer":"﴿ادخلوا﴾ يلحظ ابتداء الوصول إلى القرية، و﴿اسكنوا﴾ يلحظ الإقامة والاستقرار فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص756–757، تحت «فائدة التعبير بفعل الأمر اسكنوا»","url":""}]},{"id":"s7-1127","number":1127,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿وكلوا منها حيث شئتم﴾، وفي البقرة: ﴿فكلوا منها حيث شئتم رغدًا﴾؟","answer":"وفي الأعراف عطف الأكل بالواو على السكن لتلازمهما في حال الاستقرار، فذكر كل موضع ما يلائم الحال التي يصورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص757–758، تحت «دلالة العطف في فعل الأمر، من اسكنوا وكلوا منها»","url":""}]},{"id":"s7-1128","number":1128,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"لماذا حُذفت ﴿رغدًا﴾ في الأعراف؟","answer":"يذكر المصدر أن موضع البقرة يتحدث عن ابتداء الدخول، فصرح برغد الأكل فيه إظهارًا لمزيد الامتنان. أما الأعراف فذكرت حال السكن والاستقرار، حيث يكون الأكل معتادًا ملازمًا للإقامة، فاستغنت عن هذه الزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773، 775، تحت «بلاغة المتشابه اللفظي بين آيتي الأعراف161 و162 وآيتي البقرة58 و59»","url":""}]},{"id":"s7-1129","number":1129,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ تقديم هنا ﴿قولوا حطة﴾ على ﴿وادخلوا الباب سجدًا﴾، وعُكس الترتيب في البقرة؟","answer":"في الأعراف قدم طلب المغفرة ثم ذكر الدخول خاضعين، فيقترن الاعتراف بالذنب بهيئة التواضع.؛ ويبين اختلاف الترتيب في السورتين، مع العطف بالواو، أن المطلوب جمع القول والخضوع من غير إلزام بتقديم أحدهما على الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص762، تحت «نكتة تأخير الدخول على لفظ حطة»","url":""}]},{"id":"s7-1130","number":1130,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما دلالة الأمر بكلمة واحدة: ﴿حطة﴾؟","answer":"﴿حطة﴾ كلمة جامعة، أي مسألتنا حط خطايانا عنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص760–761، تحت «بلاغة الإيجاز في قوله حطة»","url":""}]},{"id":"s7-1131","number":1131,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿وادخلوا الباب سجدًا﴾، وكيف يكون الدخول سجودًا؟","answer":"أي ادخلوا خاضعين منحنين أو حال كونكم سجدًا عند الباب؛ فالسجود وصف لهيئتهم الدالة على التواضع، لا لعملية المشي نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص763، تحت «بلاغة التعبير بسجدًا، ودلالتها على الحال»","url":""}]},{"id":"s7-1132","number":1132,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿نغفر لكم خطيئاتكم﴾، وفي البقرة: ﴿نغفر لكم خطاياكم﴾؟","answer":"يذكر المصدر أن اختلاف صيغ الجمع يوسع الوعد بالمغفرة، فيشمل الذنوب قليلة كانت أو كثيرة متى امتثلوا الأمر وتابوا.؛ فصيغة جمع القلة لا تحصر المغفرة في القليل، كما تدل صيغة الكثرة على سعة العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص764–765، تحت «نكتة جمع لفظ خطيئاتكم»","url":""}]},{"id":"s7-1133","number":1133,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿سنزيد المحسنين﴾ من غير واو، وفي البقرة: ﴿وسنزيد المحسنين﴾؟","answer":"في الأعراف استؤنفت جملة ﴿سنزيد﴾ وعدًا مستقلًا، أما الواو في البقرة فعطفت الزيادة على المغفرة ضمن تعداد النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص765، تحت «نكتة ترك العطف في قوله سنزيد المحسنين»","url":""}]},{"id":"s7-1134","number":1134,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"لماذا تجاوز الوعد المغفرة إلى الزيادة للمحسنين؟","answer":"المغفرة ترفع أثر الإساءة، ثم الزيادة تمنح المحسنين فضلًا فوق مجرد العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص765–766، تحت «نكتة ترك العطف في قوله سنزيد المحسنين»","url":""}]},{"id":"s7-1135","number":1135,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿فبدل الذين ظلموا منهم﴾، وزاد ﴿منهم﴾ خلاف موضع البقرة؟","answer":"﴿منهم﴾ للتبعيض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص768–769، تحت «معنى من في قوله منهم»","url":""}]},{"id":"s7-1136","number":1136,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"لماذا وُصف المبدّلون بـ﴿الذين ظلموا﴾؟","answer":"وصفهم بالظلم لأنهم وضعوا القول والفعل في غير موضعهما، فكان التبديل مظهرًا من ظلمهم لا مجرد خطأ لفظي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص767–768، تحت «نكتة مجيء جملة صلة الموصول الذين ظلموا»","url":""}]},{"id":"s7-1137","number":1137,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"ما أثر تنكير ﴿قولًا﴾ ووصفه بـ﴿غير الذي قيل لهم﴾؟","answer":"يفيد التنكير تحقير القول الذي اختاروه، والوصف بالمغايرة يحقق أنهم خالفوا المأمور به واستبدلوا به غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص769–770، تحت «نكتة تنكير لفظ قولًا»","url":""}]},{"id":"s7-1138","number":1138,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"لماذا كرر مادة القول: ﴿قولًا غير الذي قيل لهم﴾؟","answer":"الأول مفعول يبين أنهم استبدلوا قولًا، والثاني في الصلة يذكر القول المأمور به؛ فتقابل القولان وظهر التبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص769–770، تحت «فائدة التعبير بالاسم الموصول وصلته في الذي قيل لهم»","url":""}]},{"id":"s7-1139","number":1139,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿فأرسلنا عليهم رجزًا﴾ لا «فأنزلنا»؟","answer":"يفيد الإرسال توجيه العذاب إليهم، وقد ضمن هنا معنى الإنزال لأنه أرسل من فوق.؛ ويذكر المصدر في المقارنة أن الإنزال لا يشعر بالكثرة بذاته، أما الإرسال فيتصور معه بدء العذاب ثم تتابعه، فتبرز صورة التسليط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص771، تحت «نكتة تعدية الإرسال بعلى»","url":""}]},{"id":"s7-1140","number":1140,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"لماذا عُدي الرجز بـ﴿عليهم﴾؟","answer":"﴿عليهم﴾ تصور الرجز نازلًا مستوليًا محيطًا بهم من فوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص771–772، تحت «نكتة تعدية الإرسال بعلى»","url":""}]},{"id":"s7-1141","number":1141,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"لماذا قُيد الرجز بأنه ﴿من السماء﴾؟","answer":"لتأكيد أن العذاب جاء من جهة لا يملكون دفعها وبأمر إلهي، لا من سبب أرضي مألوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص772–773، تحت «معنى من في قوله من السماء»","url":""}]},{"id":"s7-1143","number":1143,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿كانوا يظلمون﴾ لا «ظلموا»؟","answer":"﴿كانوا يظلمون﴾ تفيد أن الظلم كان دأبًا متكررًا راسخًا، لا واقعة تبديل منفردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773، تحت «سر وجود كانوا مع الخبر يظلمون»","url":""}]},{"id":"s7-1144","number":1144,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما دلالة تعريف ﴿القرية﴾ في ﴿واسألهم عن القرية﴾؟","answer":"التعريف للعهد؛ فهو يسألهم عن قرية معروفة لديهم، وعن خبر أهلها الذي يذكرهم باعتدائهم. ويعينها المصدر بأيلة، ويجعل السؤال عن أحوال أهلها لا عن ذات القرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص785، تحت «معنى أل في القرية والمراد بها»","url":""}]},{"id":"s7-1145","number":1145,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا أُمر النبي أن يسألهم مع أن الله سيقص الخبر؟","answer":"السؤال للتقرير والتوبيخ؛ يجعل المخاطبين يقرون بما يعرفونه من خبر أسلافهم، فتكون مشاركتهم في تقريره أبلغ في الحجة. وإخبار النبي ﷺ به دليل على الوحي، لا طلب علم بما يجهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص783–784، تحت «سر العدول من الإخبار إلى السؤال»","url":""}]},{"id":"s7-1146","number":1146,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا وُصفت القرية بأنها ﴿كانت حاضرة البحر﴾؟","answer":"الوصف يبين سبب الفتنة: قربها من البحر جعل الصيد موردًا ظاهرًا، وكانت الحيتان تحضر عند الساحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص786، تحت «سر وصف القرية بأنها حاضرة البحر»","url":""}]},{"id":"s7-1147","number":1147,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿حاضرة البحر﴾ لا «على البحر»؟","answer":"﴿حاضرة البحر﴾ أي قريبة منه ومجاورة له؛ ففيه بيان الصلة بين مكان القرية وما سيقع لأهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص786، تحت «سر وصف القرية بأنها حاضرة البحر»","url":""}]},{"id":"s7-1148","number":1148,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ يعدون في السبت﴾، وما دلالة العدوان «في» السبت؟","answer":"﴿في السبت﴾ يدل على وقوع العدوان داخل حرمة اليوم وأحكامه؛ فقد تجاوزوا النهي عن الصيد فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص788، تحت «دلالة تقييد قوله يعدون في السبت»","url":""}]},{"id":"s7-1149","number":1149,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا كرر ﴿إذ﴾: ﴿إذ يعدون... إذ تأتيهم حيتانهم﴾؟","answer":"الأولى تحدد زمن عدوانهم، والثانية تفصل صورة الابتلاء الذي وقع في ذلك الزمن؛ فتكرار ﴿إذ﴾ ينقل إلى مشهد أدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص787–789، تحت «الموقع النحوي والبياني لجملة إذ يعدون في السبت؛ الموقع النحوي والبياني لإتيان الحيتان»","url":""}]},{"id":"s7-1150","number":1150,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا أضيفت الحيتان إليهم: ﴿حيتانهم﴾؟","answer":"الإضافة تربط الحيتان بموضعهم وبما هيئ لهم من الرزق؛ فهي الحيتان الكائنة في ناحيتهم والمخلوقة لمنفعتهم. وبهذا تبرز شدة تعلق الابتلاء بمورد معاشهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص789، تحت «نكتة إضافة الحيتان إليهم»","url":""}]},{"id":"s7-1151","number":1151,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير بقوله تعالى: ﴿يوم سبتهم﴾ فأضيف السبت إليهم؟","answer":"إضافته إليهم لأنه اليوم الذي خصص لهم وفرض عليهم تعظيمه، فازدادت مسؤوليتهم عن انتهاكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص789، تحت «دلالة إضافة السبت إليهم»","url":""}]},{"id":"s7-1152","number":1152,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا وصف مجيء الحيتان بـ﴿شرعًا﴾؟","answer":"﴿شرعًا﴾ أي ظاهرة مرتفعة قريبة على وجه الماء، كأنها شارعة رؤوسها، فاشتد الإغراء والابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص789–790، تحت «بلاغة الكناية في قوله شرعًا»","url":""}]},{"id":"s7-1153","number":1153,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا قابل ﴿يوم سبتهم﴾ بـ﴿ويوم لا يسبتون لا تأتيهم﴾؟","answer":"تقابل الآية بين مجيء الحيتان ظاهرة قريبة يوم السبت، وانتفاء مجيئها في غيره على هذا التوجيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص791–792، تحت «نكتة إضافة لفظ اليوم إلى لا يسبتون»","url":""}]},{"id":"s7-1154","number":1154,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا كرر النفي في ﴿لا يسبتون لا تأتيهم﴾؟","answer":"فلكل نفي متعلَّق مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص791–792، تحت «موقع قوله لا تأتيهم ومعنى النفي في هذا السياق»","url":""}]},{"id":"s7-1155","number":1155,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿كذلك نبلوهم﴾، وإلى ماذا تشير الكاف؟","answer":"الكاف تشير إلى هذا الابتلاء العجيب بإظهار الحيتان يوم المنع وحجبها يوم الحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص792–793، تحت «معنى الكاف في كذلك ودلالتها على التشبيه»","url":""}]},{"id":"s7-1156","number":1156,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا عبّر بالمضارع ﴿نبلوهم﴾ عن ابتلاء ماضٍ؟","answer":"المضارع يستحضر صورة الابتلاء المتكرر كل أسبوع، كأنه يجري أمام السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص793، تحت «سر التعبير بالمضارع نبلوهم»","url":""}]},{"id":"s7-1158","number":1158,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا بدأت الآية بـ﴿وإذ قالت أمة منهم﴾ مع أن الجماعات لم تُذكر بعد؟","answer":"افتتحت بـ﴿وإذ﴾ لاستحضار موقف جديد، وظهرت ﴿أمة﴾ أولًا تمهيدًا لانقسام أهل القرية إلى معتدين وواعظين وساكتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص21، تحت عنوان «بلاغة الإيجاز في التعبير عن انقسام أهل القرية إلى ثلاث فرق»","url":""}]},{"id":"s7-1159","number":1159,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا نُكرت ﴿أمة﴾؟","answer":"يذكر المصدر أن التنكير يحتمل التقليل، إشارة إلى أن الفئة المثبطة للواعظين قليلة، ويحتمل التحقير لذم موقفها من تعطيل عمل المصلحين. فالتركيز على تقويم الموقف الذي اتخذته هذه الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص12–13، تحت «فائدة تنكير لفظ أمة»","url":""}]},{"id":"s7-1160","number":1160,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما دلالة استفهامهم: ﴿لم تعظون قومًا﴾؟","answer":"الاستفهام إنكاري عند القائلين؛ يستبعدون فائدة وعظ قوم يظنون أن العقوبة واقعة بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص13، تحت «بلاغة الاستفهام الإنكاري وغرضه»","url":""}]},{"id":"s7-1161","number":1161,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا نُكّر ﴿قومًا﴾ مع أنهم معروفون؟","answer":"يحمل التنكير معنى التحقير لهؤلاء المعتدين، ويذكر المصدر معه معنى التكثير بالنظر إلى كثرة الفئة وما تكرر في تاريخهم من العصيان. فهو يصور قبح حالهم وشدة إصرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص14، تحت «نكتة تنكير قومًا»","url":""}]},{"id":"s7-1162","number":1162,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما دلالة عطف معذبهم على مهلكهم؟","answer":"تفيد أو تنويع الوعيد: إهلاك بالاستئصال أو عذاب شديد دونه، ويذكر المصدر أيضًا احتمال الإهلاك في الدنيا والعذاب في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص16–17، تحت عنوان «دلالة عطف معذبهم على مهلكهم»","url":""}]},{"id":"s7-1621","number":1621,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما معنى أو ودلالتها؟","answer":"ليست أو هنا مانعة من اجتماع الجزاءين، والمقام تأكيد سوء العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص16–17، تحت عنوان «معنى أو ودلالتها»","url":""}]},{"id":"s7-1163","number":1163,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا جاء ﴿مهلكهم﴾ و﴿معذبهم﴾ باسم الفاعل؟","answer":"اسم الفاعل يستحضر العقوبة كأمر متوقع ثابت الوقوع، لا احتمالًا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص15، تحت «نكتة التعبير باسم الفاعل»","url":""}]},{"id":"s7-1164","number":1164,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما سرّ قولهم: ﴿عذابًا شديدًا﴾ بعد ﴿معذبهم﴾؟","answer":"المصدر المؤكد ﴿عذابًا﴾ مع وصفه بالشدة يفخم نوع التعذيب بعد ذكر فاعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص17، تحت «غرض تأكيد العذاب بالمفعول المطلق ووصفه بالشدة دون الإهلاك»","url":""}]},{"id":"s7-1165","number":1165,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما دلالة جواب الواعظين بكلمة ﴿معذرة﴾؟","answer":"أي نعظهم إقامةً لمعذرتنا عند ربكم وأداءً لواجب النهي، ولو لم نر أثرًا عاجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص20، تحت «بلاغة التعبير بـ﴿معذرة﴾»","url":""}]},{"id":"s7-1166","number":1166,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما الفرق الدلالي بين قراءتي ﴿معذرةٌ﴾ بالرفع و﴿معذرةً﴾ بالنصب؟","answer":"بالرفع: خبر لمبتدأ محذوف، أي موعظتنا معذرة ثابتة؛ وبالنصب: نعظهم معذرةً، أي لأجل الاعتذار. والقراءتان تجمعان ثبوت المعذرة وكونها غاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص19–20، تحت «التوجيه البلاغي والنحوي للقراءات المتواترة في معذرة»","url":""}]},{"id":"s7-1167","number":1167,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما سرّ تعبيرهم: ﴿إلى ربكم﴾ لا «إلى ربنا»؟","answer":"خاطبوهم بـ﴿ربكم﴾ تذكيرًا بأنهم أيضًا مسؤولون أمام الرب عن ترك الإنكار، مع أن ربهم وربنا واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص20–21، تحت «نكتة التعبير بالربوبية وإضافته إليهم»","url":""}]},{"id":"s7-1168","number":1168,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا عطفوا ﴿ولعلهم يتقون﴾ على ﴿معذرة إلى ربكم﴾؟","answer":"لم يحصروا الغاية في إعذار أنفسهم، بل أبقوا باب رجوع المعتدين مفتوحًا؛ فالوعظ واجب ورجاء التقوى قائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص21–22، تحت «نكتة العطف ودلالاته في ولعلهم يتقون»","url":""}]},{"id":"s7-1169","number":1169,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"كيف يُفهم رجاؤهم ﴿لعلهم يتقون﴾ مع قول الآخرين إن الله مهلكهم؟","answer":"لم يقطع الواعظون بإهلاكهم، بل رجوا أثر النصيحة؛ لأن القلوب بيد الله، وغاية الناصح البلاغ مع عدم اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص22–23، تحت «نكتة مجيء حرف الرجاء لعل»","url":""}]},{"id":"s7-1170","number":1170,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما نسوا ما ذكروا به﴾، وهل كان نسيانًا حقيقيًا؟","answer":"النسيان هنا ترك متعمد وإعراض حتى صار المذكَّر به كأنه منسي، لا ذهاب المعلومة من الذاكرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص28، تحت «بلاغة المجاز في قوله فلما نسوا ما ذكروا به»","url":""}]},{"id":"s7-1171","number":1171,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا بُني ﴿ذُكّروا﴾ للمجهول؟","answer":"بني للمجهول لأن العناية بالموعظة التي أعرضوا عنها، لا باسم الواعظ، وقد عرف من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص29، تحت «نكتة مجيء جملة صلة الموصول بالفعلية المبنية لما لم يسم فاعله»","url":""}]},{"id":"s7-1172","number":1172,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿أنجينا الذين ينهون عن السوء﴾، فوصفهم بالمضارع؟","answer":"المضارع ﴿ينهون﴾ يبين أنهم داوموا على النهي عن السوء ولم تكن موعظتهم موقفًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص29–30، تحت «نكتة مجيء الاسم الموصول وصلته الذين ينهون»","url":""}]},{"id":"s7-1173","number":1173,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا سمّى فعل المعتدين ﴿السوء﴾؟","answer":"سماه سوءًا لجمع قبائح العدوان والتحايل والمعصية في وصف يظهر شدة قبحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص31، تحت عنوان «معنى أل في السوء»","url":""}]},{"id":"s7-1174","number":1174,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا نصت الآية على نجاة الناهين وعذاب الظالمين وسكتت عن الفرقة التي قالت: ﴿لم تعظون﴾؟","answer":"يعرض المصدر خلاف المفسرين في مصير هذه الفرقة: فمنهم من ألحقها بالهالكين لترك النهي، ومنهم من عدها ناجية، ومنهم من رأى أن السكوت عنها يفيد التبكيت والتقليل من شأنها لسكوتها عن الحق. لذلك لا يحمل هذا الموضع على قول واحد بوصفه محل اتفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص30، تحت «بلاغة الحذف أو الذكر لجزاء الفريق الثالث القائل لم تعظون قومًا»","url":""}]},{"id":"s7-1175","number":1175,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا قابل ﴿أنجينا﴾ بـ﴿وأخذنا﴾؟","answer":"الإنجاء إبعاد أهل النهي عن العذاب، والأخذ استيلاء العقوبة على الظالمين؛ فتقابلت النجاة والإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص31، تحت عنوان «بلاغة العطف في وأخذنا»","url":""}]},{"id":"s7-1176","number":1176,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا أعيد وصف المعتدين بـ﴿الذين ظلموا﴾؟","answer":"أعاد الموصول لتسجيل سبب الأخذ عليهم وإبراز أن العدوان ظلم مستحق للعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص32–33، تحت عنوان «نكتة التعبير بالاسم الموصول في الذين ظلموا»","url":""}]},{"id":"s7-1177","number":1177,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿بعذاب بئيس﴾، وما معنى «بئيس»؟","answer":"﴿بئيس﴾ شديد موجع ذو بؤس، فجاء الوصف ملائمًا لأخذ لا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص33–34، تحت عنوان «معاني القراءات في بئيس»","url":""}]},{"id":"s7-1178","number":1178,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"ما أثر القراءات المتعددة في لفظ ﴿بئيس﴾؟","answer":"تتنوع أوجه القراءة في اللفظ مع تقاربها في وصف العذاب بالشدة والإيلام. ويبين المصدر أنها ترجع، مع اختلاف الألسنة واللهجات، إلى تفظيع هذا العذاب؛ فتتكامل دلالتها ولا تتعارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص33–34، تحت «معاني القراءات في بئيس»","url":""}]},{"id":"s7-1180","number":1180,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما عتوا عما نهوا عنه﴾ لا «لما عصوا»؟","answer":"العتو تجاوز الحد باستكبار وصلابة، فهو أبلغ من مطلق العصيان، ويصور إصرارهم بعد النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص45، تحت عنوان «العتو والعثو»","url":""}]},{"id":"s7-1182","number":1182,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"لماذا بُني ﴿نهوا﴾ للمجهول؟","answer":"بني للمجهول لأن المقصود عتوهم عن النهي نفسه بعد قيامه عليهم، لا تعيين من باشره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص38، تحت «نكتة مجيء جملة صلة الموصول بالفعلية لما لم يسم فاعله»","url":""}]},{"id":"s7-1183","number":1183,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿كونوا قردة﴾ بفعل الكون؟","answer":"الأمر التكويني بـ﴿كونوا﴾ أنشأ تحولهم فورًا إلى الحال المذكورة، لا أنه تكليف يملكون رفضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص39–40، تحت عنوان «دلالة الأمر بكونوا»","url":""}]},{"id":"s7-1184","number":1184,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"لماذا نُكرت ﴿قردة﴾؟","answer":"التنكير للتحقير والتهوين من شأنهم؛ إذ انتهوا بسبب عصيانهم إلى هذه الحال المهينة. فهو يبرز ما لحقهم من الصغار بعد تمردهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص40، تحت «نكتة تنكير قردة»","url":""}]},{"id":"s7-1185","number":1185,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"لماذا وُصفوا بـ﴿خاسئين﴾ بعد مسخهم قردة؟","answer":"﴿خاسئين﴾ أي مبعدين أذلاء صاغرين؛ فالمسخ لم يكن تغير صورة فقط، بل عقوبة مهينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص40–41، تحت «غرض الوصف بخاسئين»","url":""}]},{"id":"s7-1186","number":1186,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"ما الفرق بين هذا السياق وقوله في البقرة: ﴿كونوا قردة خاسئين﴾؟","answer":"البقرة تذكر المسخ عقب بيان علم المخاطبين بالقصة ضمن تعداد النعم والنقم، والأعراف تفصّل مقدماته من الابتلاء والوعظ والعتو؛ أما عبارة الحكم فواحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص41–42، تحت «بلاغة المتشابه اللفظي في قصة أصحاب السبت»","url":""}]},{"id":"s7-1187","number":1187,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ تأذن ربك﴾ لا «وإذ أذن»؟","answer":"﴿تأذن﴾ بمعنى أعلم إعلامًا مؤكدًا أو عزم وقضى، وصيغة التفعل تشعر بإظهار الإعلان وتحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص49–50، تحت «بلاغة التعبير بتأذن»","url":""}]},{"id":"s7-1188","number":1188,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا أضيف الرب إلى النبي ﷺ: ﴿ربك﴾ في خبر بني إسرائيل؟","answer":"إضافة الرب إلى النبي ﷺ تسلية له وبيان أن مدبر تاريخ بني إسرائيل هو ربه الذي يتولى أمر رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص50، تحت «نكتة مجيء وصف الربوبية وإضافته إلى ضميره ﷺ»","url":""}]},{"id":"s7-1189","number":1189,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا أكد الوعيد باللام والنون: ﴿ليبعثن عليهم﴾؟","answer":"اللام ونون التوكيد الثقيلة تقرران حتمية استمرار هذا الوعيد وعدم تخلفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص50، تحت «بلاغة توالي المؤكدات في ليبعثن»","url":""}]},{"id":"s7-1190","number":1190,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا اختير ﴿ليبعثن﴾ لا «ليسلطن»؟","answer":"البعث إرسال وإثارة متجددة؛ يفيد أن الله يقيم عليهم في أزمنة مختلفة من يسومهم العذاب، وهو أوسع من تسليط واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص50–51، تحت «معنى البعث وغرض تعديته بعلى»","url":""}]},{"id":"s7-1191","number":1191,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى يوم القيامة﴾؟","answer":"يفيد استمرار أثر الوعيد في تاريخهم إلى قيام الساعة، لا حادثة منقطعة في زمن واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص51–52، تحت عنوان «فائدة مجيء القيد إلى يوم القيامة»","url":""}]},{"id":"s7-1192","number":1192,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿من يسومهم سوء العذاب﴾ ولم يذكر الفاعل؟","answer":"أبهم الفاعل ليعم كل من يبعثه الله عليهم في العصور المختلفة، فالعبرة بدوام سنة العقوبة لا باسم أمة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص51–52، تحت عنوان «معنى من في من يسومهم»","url":""}]},{"id":"s7-1193","number":1193,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما دلالة الاستعارة في التعبير عن معاملتهم بالسوم؟","answer":"يصور السوم دوام الإذلال والتسخير، ويشبّه معاملتهم بمعاملة الأنعام التي يسوقها صاحبها لما يريد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص52–53، تحت عنوان «بلاغة الاستعارة في التعبير عن معاملتهم بالسوم»","url":""}]},{"id":"s7-1622","number":1622,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما سر التعبير بالسوم مادة وصيغة؟","answer":"يستحضر المضارع تجدد هذه المعاملة واستمرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص52–53، تحت عنوان «بلاغة التعبير بالسوم مادة وصيغة»","url":""}]},{"id":"s7-1194","number":1194,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا ختم الوعيد بـ﴿إن ربك لسريع العقاب وإنه لغفور رحيم﴾؟","answer":"جمع بين سرعة العقاب لمن أصر، والمغفرة والرحمة لمن تاب، حتى لا يأمن العاصي ولا ييأس الراجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص55، تحت عنوان «غرض تتابع وصفين في سياق الوعد إزاء وصف واحد في سياق الوعيد»","url":""}]},{"id":"s7-1195","number":1195,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿سريع العقاب﴾ مع امتداد العقوبة إلى القيامة؟","answer":"تدل السرعة على نفاذ أمر الله من غير تردد أو عجز، ويذكر المصدر أيضًا أنها تفيد تحقق الوقوع؛ فما هو آت محقق لا يخرجه تأخر وقته عن ذلك. فلا تعارض بين سرعة النفاذ والتحقق وبين امتداد زمن الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص54، تحت «نكتة وصف العقاب بالسرعة»","url":""}]},{"id":"s7-1196","number":1196,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا أظهر ﴿ربك﴾ أولًا ثم أضمر في ﴿وإنه﴾؟","answer":"أظهر ﴿ربك﴾ لإبراز وصف الربوبية وتثبيت النبي ﷺ، ثم عاد الضمير لاتضاح المرجع وتجنب التكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص54–55، تحت عنوان «نكتة الإضمار بعد الإظهار في وإنه»","url":""}]},{"id":"s7-1197","number":1197,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما غرض تتابع وصفين في سياق الوعد إزاء وصف واحد في سياق الوعيد؟","answer":"زاد في الوعد وصفين في مقابل وصف واحد في الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص54–55، تحت عنوان «غرض تتابع وصفين في سياق الوعد إزاء وصف واحد في سياق الوعيد»","url":""}]},{"id":"s7-1623","number":1623,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما غرض تقديم الوعيد على الوعد؟","answer":"قدم الوعيد موافقة لما سبق من ذكر العقوبة، ثم أعقبه بالمغفرة والرحمة ترغيبًا في التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص54–55، تحت عنوان «غرض تقديم الوعيد على الوعد»","url":""}]},{"id":"s7-1198","number":1198,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿وقطعناهم في الأرض أممًا﴾، واستعار التقطيع للتفريق؟","answer":"صور تفريقهم في نواحي الأرض كتقطيع الشيء الواحد إلى قطع متباعدة، فدل على شدة التفرق بعد اجتماع الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص60–61، تحت «بلاغة الاستعارة في قوله وقطعناهم»","url":""}]},{"id":"s7-1199","number":1199,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿في الأرض﴾، وفي الآية 160: ﴿اثنتي عشرة أسباطًا أممًا﴾؟","answer":"في الآية 160 كان التقسيم المنظم إلى اثنتي عشرة جماعة، أما هنا فالكلام على تفريقهم في أقطار الأرض أممًا شتى؛ فزاد قيد المكان لبيان الانتشار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص61، تحت عنوان «بلاغة الاستعارة في قوله وقطعناهم»","url":""}]},{"id":"s7-1200","number":1200,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا جُمعت ﴿أممًا﴾؟","answer":"جُمعت لاختلاف جماعاتهم ومواطنهم وأحوالهم بعد تفريقهم في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص62، تحت عنوان «نكتة تنكير أممًا»","url":""}]},{"id":"s7-1201","number":1201,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا قدّم ﴿منهم الصالحون﴾ على ﴿ومنهم دون ذلك﴾؟","answer":"بدأ بالصالحين إنصافًا لهم وتنويهًا بشأنهم، حتى لا يعمم الذم على بني إسرائيل كلهم، ثم ذكر من انحط عن درجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص62، تحت عنوان «الموقع البياني والنحوي لقوله منهم الصالحون ومنهم دون ذلك»","url":""}]},{"id":"s7-1202","number":1202,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم دون ذلك﴾، دون أن يقال: ومنهم الفاسقون؟","answer":"التعبير يجعل الصلاح منزلة عليا وما عداه دونها؛ فيبرز علو مرتبة الصالحين، مهما كان لغيرهم من قوة أو مال. وهو أوسع من تسمية وصف واحد للمخالفين، إذ يجمعهم هنا كونهم أدنى من منزلة الصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص63–64، تحت عنوان «سر المقابلة بين الصالحون ودون ذلك»","url":""}]},{"id":"s7-1203","number":1203,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا استعمل اسم الإشارة ﴿ذلك﴾ في ﴿دون ذلك﴾؟","answer":"يشير ذلك إلى مقام الصالحين، واستعمل البعد الحسي للدلالة على بعد المنزلة وعلوها. فالصلاح مرتبة رفيعة، ومن خالفه دونها مهما تفاوتت أحواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص64، تحت «نكتة التعبير باسم الإشارة للبعيد ذلك»","url":""}]},{"id":"s7-1204","number":1204,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿وبلوناهم بالحسنات والسيئات﴾؟","answer":"اختبرهم الله بالنعم والنقم معًا؛ فالحسنات تمتحن الشكر، والسيئات تمتحن الصبر وتدعو إلى التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص65، تحت عنوان «معنى أل في الحسنات والسيئات»","url":""}]},{"id":"s7-1205","number":1205,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا عُدّي البلاء بالباء في ﴿بالحسنات والسيئات﴾؟","answer":"الباء للسببية على توجيه المصدر؛ فبالحسنات والسيئات تحقق اختبارهم وظهرت أحوالهم. فالنعم والنقم وسيلتان يتبين بهما الشكر والصبر أو خلافهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص64–65، تحت «معنى الباء في بالحسنات»","url":""}]},{"id":"s7-1206","number":1206,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا قدّم الحسنات على السيئات هنا، وقدمت الشدة في مواضع أخرى؟","answer":"قدم الحسنات هنا لأن السياق يذكر نعم الله عليهم، ولملاءمة تقديم الصالحين قبل قوله ﴿ومنهم دون ذلك﴾. أما الموضع الذي قدم فيه الشر على الخير فمقامه مختلف، وقد تقدم فيه ذكر الموت؛ فترتيب طرفي الابتلاء يتبع السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص65، تحت «نكتة تقديم البلاء بالحسنات على السيئات»","url":""}]},{"id":"s7-1207","number":1207,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا خُتم بـ﴿لعلهم يرجعون﴾؟","answer":"جعل غاية تنويع الابتلاء رجوعهم عن العصيان إلى الطاعة، فليس المقصود مجرد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص65–66، تحت عنوان «نكتة فصل لعلهم يرجعون عن سابقتها»","url":""}]},{"id":"s7-1208","number":1208,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما نكتة حذف متعلق يرجعون؟","answer":"حذف متعلقه ليشمل الرجوع عن المعاصي وما يندرج فيها، وتفيد المضارعة تجدد الدعوة إلى ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص66–67، تحت عنوان «نكتة حذف متعلق يرجعون»","url":""}]},{"id":"s7-1624","number":1624,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما غرض التعبير بيرجعون؟","answer":"الرجوع تحول عن الحال التي هم عليها إلى التوبة والصلاح، فيصور مفارقة المعصية والعودة إلى الامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص66–67، تحت عنوان «غرض التعبير بيرجعون»","url":""}]},{"id":"s7-1209","number":1209,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما نكتة تنكير خلف؟","answer":"﴿الخَلْف﴾ بسكون اللام يكثر في الخلف السيئ، بخلاف الخَلَف الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص73، تحت عنوان «نكتة تنكير خلف»","url":""}]},{"id":"s7-1625","number":1625,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما معنى خلف في السياق؟","answer":"اختيار اللفظ يشعر بسوء من جاء بعد الصالحين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص69، تحت عنوان «شرح المفردات: خلف»","url":""}]},{"id":"s7-1210","number":1210,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعدهم﴾ مع أن الخلافة تقتضي التأخر؟","answer":"يبين القيد ابتداء مجيء هذا الخلف بعد أسلافه وصلته بهم، ويذكر المصدر أنهم من ذريتهم. أما سرعة التعاقب فيدل عليها عطف ﴿فخلف﴾ بالفاء؛ فلكل جزء من التركيب دلالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص72، تحت عنوان «فائدة مجيء القيد من بعدهم ومعنى من»","url":""}]},{"id":"s7-1211","number":1211,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا وصفهم بأنهم ﴿ورثوا الكتاب﴾ لا «أوتوا الكتاب»؟","answer":"شبه انتقال الكتاب والعلم به إليهم بانتقال الميراث، فصاروا خلفاء لأسلافهم في حيازته والقيام عليه. وفي ذلك إقامة للحجة: فقد ورثوا الكتاب وعلموه ثم خالفوا ما فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص73، تحت عنوان «بلاغة الاستعارة في التعبير بالإرث»","url":""}]},{"id":"s7-1212","number":1212,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿يأخذون عرض هذا الأدنى﴾، دون أن يقال: متاع الدنيا؟","answer":"العَرَض متاع زائل يعرض ثم يذهب، و﴿هذا الأدنى﴾ تحقير للدنيا القريبة؛ فالتعبير يفضح استبدال الباقي بالعاجل الزهيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص70، تحت عنوان «شرح المفردات: عرض هذا الأدنى»","url":""}]},{"id":"s7-1213","number":1213,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا سمى الدنيا ﴿هذا الأدنى﴾؟","answer":"الإشارة تحضر متاع الدنيا القريب، و﴿الأدنى﴾ تجمع معنى الأقرب والأحقر في مقابل الدار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص87، تحت عنوان «الأدنى والأقرب»","url":""}]}]);
